                 *
                 * # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Edit: Renamed 
                 *       response_header_attribute 
                 *       to response_header. 
                 *       5 :: Tuesday, August 4, 2026 @ 0452 hrs.
                 *
                 */

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Initialize CLR-SSL data 
                 * write access authorization 
                 * control data structure. 
                 *
                 */
                $write_authorized_callers = array(__NAMESPACE__ . 
                                                '\crnrstn_http_manager::add_header_attribute' => 1, __NAMESPACE__ . 
                                                '\crnrstn::registry_boot'                     => 1);

                if(!isset($write_authorized_callers[$caller])){

                    $write_access_denied = true;

                    break 1;

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Initialize the response 
                 * header attribute array in 
                 * support of CRNRSTN :: 
                 * Lightsaber RoCEv2 SOAP 
                 * Services Layer (CLR-SSL) 
                 * Hypertext Transfer 
                 * Protocol (HTTP) 
                 * Management Services. 
                 *
                 *
                 * 5
                 *
                 * Tuesday, July 8, 2024 @ 0523 hrs.
                 *
                 */
                foreach($R_data_000 as 
                    $attribute_name => $value)
                {

                    $attribute_id = $this->generate_key('http_response_header_attribute_id');

                    self::$R_data['response_header']['attribute_id'][]                      = $attribute_id;
                    self::$R_data['response_header']['name'][]                              = $attribute_name;
                    self::$R_data['response_header']['isset'][\strtolower($attribute_name)] = $attribute_id;

                    self::$R_data['response_header'][$attribute_id]['name'][]               = $attribute_name;
                    self::$R_data['response_header'][$attribute_id]['value'][]              = $value;
                    self::$R_data['response_header'][$attribute_id]['overwrite_existing'][] = 1;

                }

            break;
            default:

                $clr_ssl_msg = 'Unknown index[' . 
                               \strval($resource) . 
                               '] received from ' . 
                               \strval($caller);
                // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                             'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token = array(
                         'token'                   => $msg_token, 
                         'token_generation_date'   => $token_generation_date, 
                         'request_type'            => __METHOD__, 
                         'code'                    => 200, 
                         'clr_ssl_msg'             => $clr_ssl_msg);
                $this->error_log(
                       $clr_ssl_msg, 
                       \LOG_ERR, 
                       \E_ERROR, 
                       __LINE__, 
                       __METHOD__, 
                       __FILE__, 
                       $token);

                return false;

            break;

        }

        if($write_access_denied !== false){

            $clr_ssl_msg = 'Data (index = ' . 
                           \strval($resource) . 
                           ') write access was denied to ' . 
                           \strval($caller) . 
                           '.';
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_WARNING, 
                   \E_WARNING, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token);

            return false;

        }

        return true;

    }

