    function new_registered_resource(
             $file_path,
             $registry_name,
             $title_HTML = NULL,
             $title_TEXT = NULL,
             $description_HTML = NULL,
             $description_TEXT = NULL,
             $queue_mem_pointer = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: This method, new_registered_resource(), 
         *       was taken from the Lightbox Helper by eVifweb® 
         *       on Wednesday, October 29, 2025 @ 0742 hrs. 
         *       5 :: Saturday, November 1, 2025 @ 2025 hrs.
         *
         */

        $tmp_memory_insertion_check = true;
        $tmp_resource_registered = false;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * The memory pointer for the
         * configuration resource
         * queue can just about be any
         * string or integer value.
         *
         * ...just about.
         *
         * 5 :: Thursday, July 4, 2024 @ 1112 hrs.
         *
         */
        if(!isset($queue_mem_pointer)){

            $tmp_memory_insertion_check = false;
            $queue_mem_pointer = $this->generate_new_key(50, -2);

        }

        if($tmp_memory_insertion_check !== false){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Check with current memory 
             * for pre-existing resource 
             * storage location. 
             *
             */
            if($this->isset_registered_resource_queue($queue_mem_pointer) !== false){

                self::$registered_resources_queued_ARRAY[$queue_mem_pointer][] = $registry_name;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['MEMORY_POINTER'][]     = $queue_mem_pointer;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['REGISTER_NAME'][]      = $registry_name;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['FILE_PATH'][]          = $file_path;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['TITLE_HTML'][]         = $title_HTML;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['TITLE_TEXT'][]         = $title_TEXT;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['DESCRIPTION_HTML'][]   = $description_HTML;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['DESCRIPTION_TEXT'][]   = $description_TEXT;
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['LASTMODIFIED'][]       = $this->return_micro_time();
                self::$reg_res_master_ARRAY[$registry_name][$file_path]['DATECREATED'][]        = $this->return_micro_time();

                $tmp_resource_registered = true;

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Update the configuration
                 * resource reporting numbers. 
                 *
                 */
                self::$registered_resources_sequence_flag_ARRAY[$queue_mem_pointer] = sizeof(self::$registered_resources_queued_ARRAY[$queue_mem_pointer]);

            }

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Register the resource to a 
         * new memory location. 
         *
         */
        if(!($tmp_resource_registered != false)){

            self::$registered_resources_queued_ARRAY[$queue_mem_pointer][] = $registry_name;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['MEMORY_POINTER'][]     = $queue_mem_pointer;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['REGISTER_NAME'][]      = $registry_name;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['FILE_PATH'][]          = $file_path;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['TITLE_HTML'][]         = $title_HTML;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['TITLE_TEXT'][]         = $title_TEXT;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['DESCRIPTION_HTML'][]   = $description_HTML;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['DESCRIPTION_TEXT'][]   = $description_TEXT;
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['LASTMODIFIED'][]       = $this->return_micro_time();
            self::$reg_res_master_ARRAY[$registry_name][$file_path]['DATECREATED'][]        = $this->return_micro_time();

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Update the configuration 
             * resource reporting numbers. 
             *
             */
            self::$registered_resources_sequence_flag_ARRAY[$queue_mem_pointer] = sizeof(self::$registered_resources_queued_ARRAY[$queue_mem_pointer]);

        }

        return $queue_mem_pointer;

    }

