    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    function is_file(
             $file_path, 
             $resource_name = NULL, 
             $software_version = NULL, 
             $force_file_check = false)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Added the is_file() method 
         * to crnrstn to accelerate 
         * repetitive resource 
         * dependency pings. 
         * 5 :: Saturday, May 9, 2026 @ 1158 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Added the $force_file_check = false 
         * input parameter to the CLR-SSL 
         * is_file() method. 
         * 5 :: Tuesday, June 9, 2026 @ 1137 hrs.
         *
         */

        // Can we skip this file check?
        if($force_file_check !== false){

            if($this->by_pass_is_file(
                      $file_path, 
                      $resource_name, 
                      $software_version))
            {

                // 5 :: Tuesday, June 9, 2026 @ 1129 hrs.
                return true;

            }

        }

        if(\is_file($file_path)){

            if(isset($resource_name) && 
                isset($software_version))
            {

                self::$R_data['is_file_success'][$software_version][$resource_name] = 1;
                return true;

            }

            if(isset($resource_name)){

                self::$R_data['is_file_success'][$resource_name] = 1;
                return true;

            }
            
            self::$R_data['is_file_success'][$file_path] = 1;
            return true;

        }

        return false;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    function by_pass_is_file(
             $file_path = NULL, 
             $resource_name = NULL, 
             $software_version = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Added the by_pass_is_file() method 
         * to crnrstn to accelerate 
         * repetitive resource 
         * dependency pings. 
         * 5 :: Saturday, May 9, 2026 @ 1158 hrs.
         *
         */

        if(isset($resource_name) && 
            isset($software_version))
        {

            return isset(self::$R_data['is_file_success'][$software_version][$resource_name]);

        }

        if(isset($resource_name)){

            return isset(self::$R_data['is_file_success'][$resource_name]);

        }

        return isset(self::$R_data['is_file_success'][$file_path]);

    }

