    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function return_server_system_cache($data_key)
    {

        switch($data_key){
            case 'CRNRSTN_PHP_INI':
                /*
                'ini_restore'  => 'CRNRSTN_PHP_INI',
                'ini_set'      => 'CRNRSTN_PHP_INI',
                'ini_get'      => 'CRNRSTN_PHP_INI',
                'ini_get_all'  => 'CRNRSTN_PHP_INI'

                */

                return ini_get_all();

            break;
            case 'CRNRSTN_DECLARED_CLASSES':
                /*
                'get_declared_classes' => 'CRNRSTN_DECLARED_CLASSES',

                */

                return get_declared_classes();

            break;
            case 'CRNRSTN_MODULE_EXTENSION_FUNCTIONS':
                /*
                'get_extension_funcs' => 'CRNRSTN_MODULE_EXTENSION_FUNCTIONS',

                */

                $tmp_ext_functions_ARRAY = array();
                $tmp_loaded_ext_ARRAY = get_loaded_extensions();
                foreach($tmp_loaded_ext_ARRAY as 
                    $ext_index => $ext_name)
                {

                    $tmp_ext_functions_ARRAY[$ext_name] = get_extension_funcs($ext_name);

                }

                return $tmp_ext_functions_ARRAY;

            break;
            case 'CRNRSTN_NATIVE_PHP_DEFINED_FUNCTIONS':
                /*
                'get_defined_functions' => 'CRNRSTN_NATIVE_PHP_DEFINED_FUNCTIONS',

                */

                return get_defined_functions();

            break;
            case 'CRNRSTN_PHP_DEFINED_CONSTANTS':
                /*
                'get_defined_constants' => 'CRNRSTN_PHP_DEFINED_CONSTANTS',

                */

                return get_defined_constants(true);

            break;
            case 'CRNRSTN_PHP_DEFINED_VARIABLES':
                /*
                'get_defined_vars' => 'CRNRSTN_PHP_DEFINED_VARIABLES',

                */

                return get_defined_vars();

            break;
            case 'CRNRSTN_PHP_LOADED_EXTENSIONS':
                /*
                'extension_loaded' => 'CRNRSTN_PHP_LOADED_EXTENSIONS',

                */

                return get_loaded_extensions();

            break;
            case 'CRNRSTN_PHP_LOADED_EXTENSION_MODULES':
                /*
                'get_loaded_extensions' => 'CRNRSTN_PHP_LOADED_EXTENSION_MODULES',

                */

                return get_loaded_extensions();

            break;
            case 'CRNRSTN_OPENSSL_DIGEST_METHODS':
                /*
                'openssl_get_md_methods' => 'CRNRSTN_OPENSSL_DIGEST_METHODS',

                */

                return self::$_R['kivotos']->R['env']->openssl_get_md_methods(false, false);

            break;
            case 'CRNRSTN_OPENSSL_CIPHERS':
                /*
                'openssl_get_cipher_methods' => 'CRNRSTN_OPENSSL_CIPHERS',

                */

                return self::$_R['kivotos']->R['env']->openssl_get_cipher_methods(false, false);

            break;
            case 'CRNRSTN_HMAC_HASH_ALGORITHMS':
                /*
                'hash_hmac_algos' => 'CRNRSTN_HMAC_HASH_ALGORITHMS'

                */

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Note: hash_hmac_algos() 
                 *       is supported by 
                 *       PHP >= 7.2. 
                 *
                 * TODO :: CRNRSTN :: Lightsaber 
                 *         targets to support 
                 *         PHP >= 5.5. 
                 *
                 */
                return hash_hmac_algos();

            break;
            case 'CRNRSTN_HASH_ALGORITHMS':
                /*
                'hash_algos' => 'CRNRSTN_HASH_ALGORITHMS',

                */

                return hash_algos();

            break;
            default:

                error_log(__LINE__ . 
                    ' ' . 
                    __METHOD__ . 
                    ' Unknown switch case received ['. 
                    \strval($data_key) . 
                    '].');

                return -1;

            break;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function server_system_attribute_is_valid(
             $cache_type = NULL, 
             $attribute = NULL)
    {

        switch($cache_type){
            case 'ini_restore':
            case 'ini_set':
            case 'ini_get':
            case 'ini_get_all':
            case 'get_declared_classes':
            case 'get_extension_funcs':
            case 'get_defined_functions':
            case 'get_defined_constants':
            case 'get_defined_vars':
            case 'extension_loaded':
            case 'get_loaded_extensions':
            case 'openssl_get_md_methods':
            case 'openssl_get_cipher_methods':
            case 'hash_algos':

                $tmp_attribute_is_valid = false;
                $tmp_attribute          = strtolower(trim($attribute));
                $tmp_data_key           = self::$server_operations_ARRAY[$cache_type]['KEY'];
                $tmp_data_type_family   = 'CRNRSTN::RESOURCE::SERVER_NATIVE_CONFIG_CACHE';

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Runtime accelerated 
                 * check for "is active" data. 
                 *
                 */
                if(isset(self::$server_operations_ARRAY[$cache_type])){

                    if(isset(self::$server_operations_ARRAY[$cache_type]['initialization']['options']['ISACTIVE'])){

                        if(isset(self::$server_operations_ARRAY[$cache_type]['initialization']['options']['ISACTIVE'][$tmp_attribute]))
                            return true;

                        return false;

                    }

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services 
                 * Layer (CLR-SSL) Multi-
                 * Channel Decoupled Data 
                 * Object (MC-DDO) session 
                 * accelerated check for 
                 * "is active" data. 
                 *
                 */
                if($this->isset_resource(
                          'data_value', 
                          $tmp_data_key, 
                          $tmp_data_type_family, 
                          self::$R_data['int_flag']['R_channel_SESSION']) == true)
                {

                    $tmp_server_attribute_is_active_ARRAY = $this->get_resource(
                                                                   $tmp_data_key, 
                                                                   0, 
                                                                   $tmp_data_type_family, 
                                                                   self::$R_data['int_flag']['R_channel_SESSION']);

                    if(isset($tmp_server_attribute_is_active_ARRAY[$tmp_attribute]))
                        return true;

                    return false;

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Do we need to 
                 * [RUNTIME] load the 
                 * server configuration 
                 * from scratch? 
                 *
                 */
                if(self::$server_operations_ARRAY[$cache_type]['initialization']['default'][self::$R_data['int_flag']['R_integer']] == -1){
                    //if(self::$openssl_ARRAY['cipher']['default'][self::$R_data['int_flag']['R_integer']] == -1){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Runtime initialization. 
                     *
                     */
                    switch($tmp_data_key){
                        case 'CRNRSTN_PHP_INI':
                            //'ini_restore', 'ini_set', 'ini_get', 'ini_get_all'
                        case 'CRNRSTN_DECLARED_CLASSES':
                            //'get_declared_classes'
                        case 'CRNRSTN_MODULE_EXTENSION_FUNCTIONS':
                            //'get_extension_funcs'
                        case 'CRNRSTN_NATIVE_PHP_DEFINED_FUNCTIONS':
                            //'get_defined_functions'
                        case 'CRNRSTN_PHP_DEFINED_CONSTANTS':
                            //'get_defined_constants'
                        case 'CRNRSTN_PHP_DEFINED_VARIABLES':
                            //'get_defined_vars'
                        case 'CRNRSTN_PHP_LOADED_EXTENSIONS':
                            //'extension_loaded'
                        case 'CRNRSTN_PHP_LOADED_EXTENSION_MODULES':
                            //'get_loaded_extensions'
                        case 'CRNRSTN_OPENSSL_DIGEST_METHODS':
                            //'openssl_get_md_methods'
                        case 'CRNRSTN_OPENSSL_CIPHERS':
                            //'openssl_get_cipher_methods'
                        case 'CRNRSTN_HMAC_HASH_ALGORITHMS':
                            //'hash_hmac_algos'
                        case 'CRNRSTN_HASH_ALGORITHMS':
                            //'hash_algos'

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Cache server 
                             * data in runtime. 
                             *
                             */
                            self::$server_operations_ARRAY[$cache_type]['initialization']['options']['server'] = $this->return_server_system_cache($tmp_data_key);

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Update an internal 
                             * data structure to 
                             * reference what is 
                             * available on 
                             * the server. 
                             *
                             */
                            foreach((array) self::$server_operations_ARRAY[$cache_type]['initialization']['options']['server'] as 
                                $server_config_index => $server_config_name)
                            {
                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * TODO :: Is it a guarantee that 
                                 *         the server hash name 
                                 *         will always 
                                 *         be lowercase? 
                                 *
                                 */

                                $tmp_lower_name = strtolower($server_config_name);

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * Populate a fast 
                                 * isset lookup array 
                                 * for the active 
                                 * server attribute. 
                                 *
                                 */
                                self::$server_operations_ARRAY[$cache_type]['initialization']['options']['ISACTIVE'][$tmp_lower_name] = $server_config_index;

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * If a match for the 
                                 * input attribute is 
                                 * found on the server, 
                                 * set it to default. 
                                 *
                                 */
                                if($tmp_lower_name == $tmp_attribute){

                                    $tmp_attribute_is_valid = true;

                                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                     * Set the match to 
                                     * be the "default" 
                                     * or "last lookup". 
                                     *
                                     * Sometimes this 
                                     * value can 
                                     * be useful. 
                                     *
                                     */
                                    self::$server_operations_ARRAY[$cache_type]['initialization']['default'][self::$R_data['int_flag']['R_integer']] = $server_config_index;
                                    self::$server_operations_ARRAY[$cache_type]['initialization']['default']['name'] = $tmp_attribute = $server_config_name;

                                }

                            }

                            $tmp_ddo_output = $this->add_resource(
                                                     $tmp_data_key, 
                                                     self::$server_operations_ARRAY[$cache_type]['initialization']['options']['ISACTIVE'], 
                                                     $tmp_data_type_family, 
                                                     self::$R_data['int_flag']['R_channel_SESSION'], 
                                                     0);

                        break;
                        default:

                            error_log(__LINE__ . 
                                ' ' . 
                                __METHOD__ . 
                                ' Unknown switch case received [' . 
                                \strval($cache_type) . '].');

                        break;

                    }

                }

            break;
            default:

                error_log(__LINE__ . 
                    ' ' . 
                    __METHOD__ . 
                    ' Unknown switch case received [' . 
                    \strval($cache_type) . '].');

            break;

        }

        return $tmp_attribute_is_valid;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_valid_constant(
             $data, 
             $system_source_key, 
             $default_override = NULL)
    {

        switch($system_source_key){
            case 'R_debug_mode':
            case 'R_debug_mode_ARRAY':

                $tmp_has_data = $tmp_message_added = false;

                if(isset($data)){

                    $tmp_has_data = true;

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * System input check. 
                     *
                     */
                    if(isset(self::$R_debug_mode_ARRAY[$data]))
                        return (int) self::$R_debug_mode_ARRAY[$data];

                    $tmp_err_str = 'CRNRSTN :: does not ' . 
                                   'recognize the debug ' . 
                                   'mode that has been ' . 
                                   'provided: (' .
                                    $this->gettype($data) . 
                                    ') ' . \strval($data) . '. ';

                    $this->err_message_queue_push(NULL, $tmp_err_str);

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * System input 
                 * override check. 
                 *
                 */
                if(isset($default_override)){

                    if($tmp_has_data !== false){

                        $tmp_message_added = true;

                        $tmp_err_str = 'Processing an ' . 
                                       'internal override for ' . 
                                       'an unknown system ' . 
                                       'debug mode. ';
                        $this->err_message_queue_push(NULL, $tmp_err_str);

                    }

                    if(isset(self::$R_debug_mode_ARRAY[$default_override]))
                        return (int) self::$R_debug_mode_ARRAY[$default_override];

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * System settings 
                 * override check. 
                 *
                 */
                $tmp_R_debug_mode = $this->get_resource(
                                           'R_debug_mode', 
                                           0, 
                                           'CRNRSTN::RESOURCE::DEBUG_MODE');

                if(is_numeric($tmp_R_debug_mode)){

                    if(($tmp_has_data !== false) && !($tmp_message_added !== false)){

                        $tmp_err_str = 'Processing a system ' . 
                                       'settings override for ' . 
                                       'an unknown system ' . 
                                       'debug mode. ';
                        $this->err_message_queue_push(NULL, $tmp_err_str);

                    }

                    if(isset(self::$R_debug_mode_ARRAY[$tmp_R_debug_mode])){

                        self::$R_data['R_debug_mode'] = (int) self::$R_debug_mode_ARRAY[$tmp_R_debug_mode];
                        return (int) self::$R_debug_mode_ARRAY[$tmp_R_debug_mode];

                    }

                }

                return (int) self::$R_data['R_debug_mode'];

            break;
            case 'phpmailer_debug_mode_ARRAY':

                $tmp_has_data = $tmp_message_added = false;

                if(isset($data)){

                    $tmp_has_data = true;

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * System input 
                     * check. 
                     *
                     */
                    if(isset(self::$phpmailer_debug_mode_ARRAY[$data]))
                        return (int) self::$phpmailer_debug_mode_ARRAY[$data];

                    $tmp_err_str = 'CRNRSTN :: does not ' . 
                                   'recognize the PHPMAILER ' . 
                                   'debug mode that has ' . 
                                   'been provided: (' .
                                   $this->gettype($data) . 
                                   ') ' . \strval($data) . '. ';

                    $this->err_message_queue_push(NULL, $tmp_err_str);

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * System input 
                 * override check. 
                 *
                 */
                if(isset($default_override)){

                    if($tmp_has_data !== false){

                        $tmp_message_added = true;

                        $tmp_err_str = 'Processing an internal ' . 
                                       'override for an unknown ' . 
                                       'PHPMAILER debug mode. ';
                        $this->err_message_queue_push(NULL, $tmp_err_str);

                    }

                    if(isset(self::$phpmailer_debug_mode_ARRAY[$default_override]))
                        return (int) self::$phpmailer_debug_mode_ARRAY[$default_override];

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * System settings 
                 * override check. 
                 *
                 */
                $tmp_phpmailer_debug_mode = $this->get_resource(
                                                   'phpmailer_debug_mode', 
                                                   0, 
                                                   'CRNRSTN::RESOURCE::DEBUG_MODE');

                if(is_numeric($tmp_phpmailer_debug_mode)){

                    if(($tmp_has_data !== false) && 
                        !($tmp_message_added !== false))
                    {

                        $tmp_err_str = 'Processing a PHPMAILER ' . 
                                       'settings override for an ' . 
                                       'unknown PHPMAILER debug mode. ';
                        $this->err_message_queue_push(NULL, $tmp_err_str);

                    }

                    if(isset(self::$phpmailer_debug_mode_ARRAY[$tmp_phpmailer_debug_mode])){

                        self::$R_data['phpmailer_debug_mode'] = self::$phpmailer_debug_mode_ARRAY[$tmp_phpmailer_debug_mode];
                        return (int) self::$phpmailer_debug_mode_ARRAY[$tmp_phpmailer_debug_mode];

                    }

                }

                return self::$R_data['phpmailer_debug_mode'];

            break;
            case 'system_log_output_profile_constants_ARRAY':

                $tmp_has_data = $tmp_message_added = false;

                if(isset($data)){

                    $tmp_has_data = true;

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * System input check. 
                     *
                     */
                    if(isset(self::$system_log_output_profile_constants_ARRAY[$data]))
                        return (int) self::$system_log_output_profile_constants_ARRAY[$data];

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Check all CLR-SSL Logging 
                     * supported integer constants 
                     * and bitwise combinations. 
                     *
                     */
                    if(self::$_R['kivotos']->R['logging']->is_valid_output_profile($data) !== false)
                        return (int) $data;

                    $tmp_err_str = 'CRNRSTN :: does not ' . 
                                   'recognize the CLR-SSL ' . 
                                   'Logging output profile ' . 
                                   'constant that has ' . 
                                   'been provided: (' . 
                                   $this->gettype($data) . 
                                   ') ' . \strval($data) . 
                                   '. ';

                    $this->err_message_queue_push(NULL, $tmp_err_str);

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * System input 
                 * override check. 
                 *
                 */
                if(isset($default_override)){

                    if($tmp_has_data !== false){

                        $tmp_message_added = true;

                        $tmp_err_str = 'Processing an internal ' . 
                                       'override for an unknown ' . 
                                       'CLR-SSL Logging output ' . 
                                       'profile constant. ';
                        $this->err_message_queue_push(NULL, $tmp_err_str);

                    }

                    if(isset(self::$system_log_output_profile_constants_ARRAY[$default_override]))
                        return (int) self::$system_log_output_profile_constants_ARRAY[$default_override];

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Check all CLR-SSL 
                     * Logging supported 
                     * integer constants 
                     * and bitwise 
