    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function hello_memory_performance()
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * The memory_performance() method will
         * return an array with the server's
         * current performance stats,...
         * which said performance stats can be
         * delta'd against in another request
         * when the previously provided key is
         * passed in as the $delta_key parameter.
         *
         *
         * 5 ::
         *
         * Thursday, November 13, 2025 @ 0005 hrs.
         *
         */
        $tmp_mem_output_ARRAY = $this->memory_performance('my-custom-key-before-stuff');

        error_log('[' . __LINE__ .
        '] [' . __CLASS__ .
        '] $tmp_mem_output_ARRAY[' .
        print_r($tmp_mem_output_ARRAY, true) .
        '].');

        // Do some stuff.

        $tmp_mem_output_ARRAY = $this->memory_performance(
                                       'my-after-stuff-is-done-key',
                                       'delta',
                                       'my-custom-key-before-stuff');

        error_log('[' . __LINE__ .
        '] [' . __CLASS__ .
        '] $tmp_mem_output_ARRAY[' .
        print_r($tmp_mem_output_ARRAY, true) .
        '].');

        return NULL;

    }

