         */

        // By-pass this on Windows® for now.
        if(self::$R_data['operating_system']['name'] == 'Windows®')
            return NULL;

        //$tmp_serial = $this->generate_new_key();

        if(!isset($lookup_key))
            $lookup_key = time();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Performance Tracking. 
         *
         */
        switch($output_type){
            case 'start':
            case 'delta':

            break;
            case 'usage':
            case 'history':
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Store a snapshot of 
                 * server performance 
                 * telemetry data. 
                 *
                 *
                 * 5 :: Monday, March 9, 2026 @ 0515 hrs.
                 *
                 */
                $tmp_memusage      = \memory_get_usage();
                $tmp_memusage_real = \memory_get_usage(true);
                $tmp_sysloadavg    = $this->sys_getloadavg();

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Performance 
                 * activity log. 
                 *
                 */
                $this->memory_performance_index_ARRAY[] = $lookup_key;

                $this->memory_performance_time_ARRAY['wall_time'][]  = $this->wall_time();
                $this->memory_performance_time_ARRAY['time'][]       = \time();
                $this->memory_performance_time_ARRAY['lookup_key'][] = $lookup_key;

                $this->memory_performance_history_ARRAY[$lookup_key]['memory_get_script_usage'][] = $tmp_memusage;
                $this->memory_performance_history_ARRAY[$lookup_key]['memory_get_real_usage'][]   = $tmp_memusage_real;
                $this->memory_performance_history_ARRAY[$lookup_key]['sys_getloadavg'][]          = $tmp_sysloadavg;

            break;

        }

        switch($output_type){
            case 'start':

                $tmp_ARRAY = array();

                $tmp_ARRAY['sys_getloadavg']          = self::$R_data['transparency']['R_server_load[start]'];
                $tmp_ARRAY['memory_get_real_usage']   = self::$R_data['transparency']['R_memory_real_usage[start]'];
                $tmp_ARRAY['memory_get_script_usage'] = self::$R_data['transparency']['R_memory_script_usage[start]'];

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Return current 
                 * memory performance. 
                 *
                 */
                return $tmp_ARRAY;

            break;
            case 'delta':

                if(!isset($tmp_memusage)){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Get server 
                     * telemetry data. 
                     *
                     */
                    $tmp_memusage      = \memory_get_usage();
                    $tmp_memusage_real = \memory_get_usage(true);
                    $tmp_sysloadavg    = $this->sys_getloadavg();

                }

                if(isset($delta_key)){

                    if(isset($this->memory_performance_history_ARRAY[$delta_key]['memory_get_real_usage'])){

                        if(!isset($this->memory_performance_delta_history_ARRAY[$delta_key]['memory_get_real_usage'])){

                            $tmp_cnt = 0;

                        }else{

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Get index for 
                             * delta array 
                             * alignment. 
                             *
                             */
                            $tmp_cnt = count($this->memory_performance_delta_history_ARRAY[$delta_key]['memory_get_real_usage']);

                        }

                        $this->memory_performance_index_ARRAY[]             = $lookup_key;
                        $this->memory_performance_time_ARRAY['wall_time'][] = $this->wall_time();
                        $this->memory_performance_time_ARRAY['time'][]      = \time();

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Memory performance 
                         * snapshot indexed 
                         * with provided key. 
                         *
                         */
                        $this->memory_performance_history_ARRAY[$delta_key]['memory_get_script_usage'][] = $tmp_memusage;
                        $this->memory_performance_history_ARRAY[$delta_key]['memory_get_real_usage'][]   = $tmp_memusage_real;
                        $this->memory_performance_history_ARRAY[$delta_key]['sys_getloadavg'][]          = $tmp_sysloadavg;

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Add to history...current 
                         * performance delta against 
                         * state of historical 
                         * performance snapshot 
                         * that is also indexed 
                         * with the same 
                         * provided key.
                         *
                         */
                        $this->memory_performance_delta_history_ARRAY[$delta_key]['memory_get_script_usage'][] = $tmp_memusage - $this->memory_performance_history_ARRAY[$delta_key]['memory_get_script_usage'][$tmp_cnt];
                        $this->memory_performance_delta_history_ARRAY[$delta_key]['memory_get_real_usage'][]   = $tmp_memusage_real - $this->memory_performance_history_ARRAY[$delta_key]['memory_get_real_usage'][$tmp_cnt];

                        $tmp_load_init_ARRAY = $this->memory_performance_history_ARRAY[$delta_key]['sys_getloadavg'][$tmp_cnt];
