    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function rrs_map_cache_return(
             $channel = NULL, 
             $source = NULL)
    {

        $tmp_channel_ARRAY = array();

        if(isset($channel)){

            if($source == self::$R_data['int_flag']['R_fs_map']){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * This will check for 
                 * $_GET data and return 
                 * the sauce if it 
                 * is available. 
                 *
                 * This check runs early 
                 * (low level) to 
                 * efficiently support 
                 * image asset return 
                 * from a mapped URI. 
                 *
                 */
                if($this->isset_param($_GET, $this->session_salt()) == true){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return active 
                     * cache channels.
                     *
                     */
                    $tmp_channel_ARRAY = $this->return_cache_channels();

                    error_log(__LINE__ . ' ' . 
                        __METHOD__ . 
                        ' SETTING tmp_channel_ARRAY[' . 
                        print_r($tmp_channel_ARRAY, true) . 
                        '] TO EXTRACT $_GET[] DATA.');

                }

            }

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This will check for
         * $_GET data and return
         * the sauce if it
         * is available.
         *
         * This check runs early
         * (low level) to
         * efficiently support
         * image asset return
         * from a mapped URI.
         *
         */
        if($this->isset_param($_GET, $this->session_salt()) == true){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Channel not provided.
             *
             * Check all active
             * channels.
             *
             * Order is determined
             * by global control
             * array...not
             * initialization sequence.
             *
             * Return the active
             * cache channels.
             *
             * $this->return_isactive_channels();
             *
             */
            $tmp_channel_ARRAY = $this->return_cache_channels();
            error_log(__LINE__ . ' ' . 
                __METHOD__ . 
                ' SETTING tmp_channel_ARRAY[' . 
                print_r($tmp_channel_ARRAY, true) . 
                '] TO EXTRACT $_GET[] DATA.');
            error_log(__LINE__ . ' ' . 
                __METHOD__ . 
                ' ATTEMPTING TO EXTRACT $_GET[] DATA [' . 
                \strval($_GET[$this->session_salt()]) . 
                '] FROM tmp_channel_ARRAY[' . 
                print_r($tmp_channel_ARRAY, true) . 
                '].');

        }

        foreach($tmp_channel_ARRAY as 
            $index => $channel)
        {

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Fastest path to
             * $_GET resource
             * return fulfillment.
             *
             */
            $tmp_return = self::$_R['kivotos']->R['rrs_map']->rrs_map_execute($channel . '_cache_accelerated_return');
            \error_log(__LINE__ . ' ' . 
                __METHOD__ . 
                ' ATTEMPTING TO EXTRACT $_GET[] DATA(LEN=' . 
                \strlen($tmp_return) . ') [' . 
                \strval($_GET[$this->session_salt()]) . 
                '] FROM $channel[' . print_r($channel, true) . 
                '].');

            if(\strlen($tmp_return) > 0){

                \error_log(__LINE__ . ' ' . 
                    __METHOD__ . 
                    ' ATTEMPTING TO EXTRACT $_GET[] DATA(LEN=' . 
                    \strlen($tmp_return) . ') [' . 
                    \strval($_GET[$this->session_salt()]) . 
                    '] FROM $channel[' . 
                    \print_r($channel, true) . 
                    '].');

                return $tmp_return;

            }

        }

        return NULL;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
