     */
    function gone_to_plaid(
             $data_key = NULL, 
             $system = 'R_fs_map', 
             $channel = 'R_channel_RUNTIME')
    {

        if(is_string($channel))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Convert CLR-SSL channel 
             * data to integer. 
             *
             *
             * 5 :: Monday, July 13, 2026 @ 0350 hrs.
             *
             */
            $channel = (int) self::$R_data['int_flag'][$channel];

        if(is_string($system))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Convert CLR-SSL file system 
             * mapping architecture to integer. 
             *
             *
             * 5 :: Tuesday, July 14, 2026 @ 0247 hrs.
             *
             */
            $system = (int) self::$R_data['int_flag'][$system];

        return self::$_R['kivotos']->R['rrs_map']->gone_to_plaid(
                                                   $data_key,
                                                   $system,
                                                   $channel);

    }

