     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function generate_420_timestamp_echo_output(
             $secs = 4, 
             $lnum = '', 
             $methd = '')
    {

        for($i = 0; $i < ((1000 * 10) * $secs); $i++){

            echo '[' . $this->return_micro_time() . 
            '][' . $this->wall_time() . 
            '][lnum ' . $lnum . '][' . $methd . ']<br> 
    ';

        }

    }

    /**
