     */
    function err($lnum = NULL)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Throw a simple error to 
         * expose stack trace in the 
         * error logs.
         *
         */
        if(isset($lnum)){

            error_log($lnum . ' Stack trace out; ' . 
                __METHOD__ . 
                ' Triggering a PHP warning now.');

        }else{

            error_log('Stack trace out; ' . 
                __METHOD__ . 
                ' Triggering a PHP warning now.');

        }

        $tmp = array();
        if(\strlen($tmp)){

            $tmp = 1;

        }

    }

