             $salt_ugc_override = NULL, 
             $serial_profile_ARRAY = NULL, 
             $raw_output_mode = NULL, 
             $output_mode = NULL)
    {

        $tmp_session_salt = $this->session_salt();
        $tmp_ugc = $tmp_asset_data_key = $tmp_source_id = NULL;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Support for asset mapping 
         * raw image return, raw JS/CSS 
         * return, maybe even deep link 
         * processing,...etc. 
         *
         */
        if(($this->isset_param($_GET, $tmp_session_salt) == true) || 
            $salt_ugc_override !== NULL)
        {

            if(isset($_GET[$tmp_session_salt])){

                $tmp_salt_ugc = $_GET[$tmp_session_salt];

                if($tmp_salt_ugc != ''){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Note: Only set if 
                     *       $_GET[] has 
                     *       salt UGC. 
                     *
                     */
                    $tmp_ugc = $tmp_salt_ugc;

