                            $tmp_salt_ugc . '].');

                    }else{

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Establish 
                         * RAW_OUTPUT_MODE. 
                         *
                         */
                        if(!is_int($raw_output_mode)){

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Extracted meta from 
                             * the asset manager  
                             * will handle images. 
                             *
                             */
                            $serial_profile_ARRAY = $this->asset_data_meta(
                                                           $tmp_salt_ugc, 
                                                           'module_key');
                            $raw_output_mode = $serial_profile_ARRAY['raw_output_mode'];

                        }

                        if(isset($output_mode)){

                            if($output_mode == ''){

                                $output_mode = $raw_output_mode;

                            }

                        }else{

                            $output_mode = $raw_output_mode;

                        }

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * CRNRSTN :: Lightsaber 
                     * RoCEv2 SOAP Services 
                     * Layer (CLR-SSL) Response 
                     * Return Serialization Map. 
                     *
                     */
                    return $this->initialize_request(
                                  $tmp_salt_ugc, 
                                  'module_key', 
                                  $tmp_salt_ugc, 
                                  NULL, 
                                  $serial_profile_ARRAY, 
                                  $raw_output_mode, 
                                  $output_mode);

                }

            }

        }

        return false;

    }

