    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function html_version_burn(
             $name, 
             $state = 'BEGIN', 
             $format = 'HTML_COMMENT')
    {

        $tmp_str = '';

        switch($state){
            case 'END':

                switch($format){
                    case 'TEXT':

                        $tmp_str = 'End CRNRSTN :: Lightsaber v' . 
                                   self::$R_data['version_crnrstn'] . 
                                   ' :: ' . 
                                   $name . ' Output';

                    break;
                    case 'HTML_COMMENT':

                        $tmp_str = '<!-- End CRNRSTN :: Lightsaber v' . 
                                   self::$R_data['version_crnrstn'] . 
                                   ' :: ' . 
                                   $name . ' Output -->';

                    break;

                }

            break;
            case 'BEGIN':
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Tuesday, September 5, 2023 @ 1903 hrs.
                 *
                 * CRNRSTN :: CDN HTML Stability Control
                 *
                 * When CRNRSTN :: CDN HTML 
                 * Stability Control is enabled, 
                 * timestamps are removed from the 
                 * HTML code comments that accompany 
                 * CRNRSTN :: HTML content injections. 
                 *
                 * CRNRSTN :: CDN HTML Stability 
                 * Control supports building cleaner 
                 * HTML that is more or less...and 
                 * simply put...timeless. And this is 
                 * not even the end yet; with stability 
                 * control enabled, CRNRSTN :: will 
                 * still build the same HTML that will 
                 * be having the same configured 
                 * analytics, engagement, meta, and 
                 * framework integration components 
                 * that the world (wide web) has 
                 * come to know and love so well. 
                 *
                 */
                if($this->is_serialized_bit_set(
                          'crnrstn_html_comments_mode', 
                          self::$R_data['int_flag']['CRNRSTN_HTML_COMMENTS_CDN_STABILITY_CONTROL_ENABLED']) == true)
                {

                    switch($format){
                        case 'TEXT':

                            $tmp_str = 'Begin CRNRSTN :: Lightsaber v' . 
                                       self::$R_data['version_crnrstn'] . ' ' . 
                                       $name . ' Output';

                        break;
                        case 'HTML_COMMENT':

                            $tmp_str = '<!-- Begin CRNRSTN :: Lightsaber v' . 
                                       self::$R_data['version_crnrstn'] . ' ' . 
                                       $name . ' Output -->';

                        break;

                    }

                    return $tmp_str;

                }

                switch($format){
                    case 'TEXT':

                        $tmp_str = 'Begin CRNRSTN :: Lightsaber v' . 
                                   self::$R_data['version_crnrstn'] . ' ' . 
                                   $name . ' Output :: ' . 
                                   $this->return_micro_time();

                    break;
                    case 'HTML_COMMENT':

                        $tmp_str = '<!-- Begin CRNRSTN :: Lightsaber v' . 
                                   self::$R_data['version_crnrstn'] . ' ' . 
                                   $name . ' Output :: ' . 
                                   $this->return_micro_time() . ' -->';

                    break;

                }

            break;

        }

        return $tmp_str;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function header_signature_options_return()
    {

        if(isset(self::$_R['kivotos']->R['env']))
            return self::$_R['kivotos']->R['env']->header_signature_options_return();

        $opt_array = array();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Asset mapping fires 
         * before instantiaton 
         * of oHTTP_MGR, the 
         * CRNRSTN :: HTTP 
         * Manager Class Object. 
         *
         * So we need to handle 
         * the header signature 
         * here too...for 
         * asset mapping. 
         *
         */
        $content_date         = \date('D, M j Y G:i:s T');
        $content_date_expire  = \date('D, M j Y G:i:s T', \strtotime('+ 7 days'));
        $content_date_lastmod = \date('D, j M Y G:i:s T');

        if(!isset(self::$R_data['response_header']['isset']['content-language']))
            $opt_array[] = 'Content-Language: ' . $this->iso_language_profile();

        if(!isset(self::$R_data['response_header']['isset']['content-type']))
            $opt_array[] = 'Content-Type: text/html; charset=UTF-8';

        if(!isset(self::$R_data['response_header']['isset']['cache-control']))
            $opt_array[] = 'Cache-Control: max-age=604800';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Keep-Alive header
         * -----
         * Connection-specific header fields 
         * such as Connection and Keep-Alive 
         * are prohibited in HTTP/2 and HTTP/3. 
         * 
         * Chrome and Firefox ignore them in 
         * HTTP/2 responses, but Safari 
         * conforms to the HTTP/2 specification 
         * requirements and does not load any 
         * response that contains them. 
         *
         * SOURCE :: https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Keep-Alive
         *
         *
         * 5 :: Tuesday, August 4, 2026 @ 0852 hrs.
         *
         */
        //$tmp_array[] = 'Keep-Alive: timeout=7, max=1000';

        if(!isset(self::$R_data['response_header']['isset']['date'])) 
            $opt_array[] = 'Date: ' . 
                           $content_date;

        if(!isset(self::$R_data['response_header']['isset']['expires'])) 
            $opt_array[] = 'Expires: ' . 
                           $content_date_expire;

        if(!isset(self::$R_data['response_header']['isset']['last-modified'])) 
            $opt_array[] = 'Last-Modified: ' . 
                           $content_date_lastmod;

        //if(!isset(self::$R_data['response_header']['isset']['x-powered-by'])) 
            $opt_array[] = 'X-Powered-By: PHP v' . 
                           $this->version_php() . 
                           ', CRNRSTN :: Lightsaber v' . 
                           self::$R_data['version_crnrstn'];

        return $opt_array;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function set_response_headers(
             $header_options = NULL, 
             $content_length = NULL, 
             $filepath = NULL, 
             $filename = NULL, 
             $file_extension = NULL)
    {
        // 5 :: Case of the Monday's, August 3, 2026 @ 0644 hrs.

        $content_length_flag      = NULL;
        $assembled_header_options = array();

        if(isset($filepath)){

            $filepath_clean = \str_replace(
                                   self::$R_data['operating_system']['R_path_patterns'][0], 
                                   self::$R_data['operating_system']['R_path_replacements'][0], 
                                   $filepath);

            if($this->is_file($filepath_clean)){

                if(!isset($file_extension)){

                    if(!isset($filename)){
                                    
                        $pos_ext = \strpos('.', $filepath_clean);
                        if(!($pos_ext === false)){

                            $pos_ext  = \explode('.', $filepath_clean);
                            $file_ext = \array_pop($pos_ext);

                        }else{

                            $file_ext = '';

                        }

                    }else{

                        $pos_ext = \strpos('.', $filename);
                        if(!($pos_ext === false)){

                            $pos_ext  = \explode('.', $filename);
                            $file_ext = \array_pop($pos_ext);

                        }else{

                            $file_ext = '';

                        }

                    }

                }else{

                    $file_ext = $file_extension;

                }

                $pos_separator = \strpos(self::$R_data['operating_system']['os_path_dir_separator_char'], $filepath_clean);

                // Do we have a path and need a filename?
                if(!isset($filename) && 
                    !($pos_separator === false))
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * SOURCE  :: https://www.php.net/manual/en/function.basename.php
                     * COMMENT :: https://www.php.net/manual/en/function.basename.php#85369
                     * AUTHOR  :: (remove) dot nasretdinov at (remove) dot gmail dot com
                     */
                    $filename_clean = \basename(\end(\explode(self::$R_data['operating_system']['os_path_dir_separator_char'], $filepath)), $file_extension);
                else
                    if(!isset($filename))
                        $filename_clean = \basename($filepath, $file_ext);
                    else
                        $filename_clean = \basename($filename, $file_ext);

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE  :: https://stackoverflow.com/questions/9728269/content-length-and-other-http-headers
                 * COMMENT :: https://stackoverflow.com/a/9728576
                 * AUTHOR  :: Neysor :: https://stackoverflow.com/users/1219121/neysor
                 *
                 */
                $assembled_header_options[] = 'Content-Type: ' . \mime_content_type($filepath);
                $filesize                   = \filesize($filepath);
                $assembled_header_options[] = 'Content-length: ' . $filesize;
                $content_length_flag        = 1;

                if(\function_exists('filemtime')){

                    $date_lastmod               = \filemtime($filepath);
                    $date_lastmod               = \date('D, j M Y G:i:s T', $date_lastmod);
                    $assembled_header_options[] = 'Last-Modified: ' . $date_lastmod;

                }

            }

        }

        if(!isset($filename_clean) && 
            (isset($filename) && 
                !isset($filepath)))
        {
            $pos_ext = \strpos('.', $filename);
            if(!($pos_ext === false)){

                $pos_ext  = \explode('.', $filename);
                $file_ext = \array_pop($pos_ext);

            }else{

                $file_ext = '';

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Use $file_ext from the 
             * file itself to clean 
             * the file name. 
             *
             *
             * 5 :: Case of the Monday's, August 3, 2026 @ 1039 hrs.
             *
             */
            $filename_clean = \basename($filename, $file_ext);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Apply the override if the 
             * data is present for the 
             * response header. 
             *
             *
             * 5 :: Case of the Monday's, August 3, 2026 @ 1040 hrs.
             *
             */
            if(isset($file_extension)) 
                $file_ext = $file_extension;

        }

        if(isset($file_ext) && 
            isset($filename_clean))
            $assembled_header_options[] = 'Content-Disposition: inline; filename="' . 
                                          $filename_clean . 
                                          '.' . 
                                          $file_ext . 
                                          '"';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize the content length 
         * header option if it has not 
         * yet been initialized here, 
         * and we have received the data. 
         *
         *
         * 5 :: Case of the Monday's, August 3, 2026 @ 1047 hrs.
         *
         */
        if(\is_numeric($content_length) &&
            !isset($content_length_flag)) 
            $assembled_header_options[] = 'Content-length: ' . 
                                          (int) $content_length;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Ensure all CLR-SSL framework 
         * header signatures are in 
         * place, and then add any 
         * header options that were 
         * received as input data to 
         * this method. 
         *
         *
         * 5 :: Case of the Monday's, August 3, 2026 @ 0754 hrs.
         *
         */
        $this->header_options_add(\headers_list());
        $this->header_options_add($assembled_header_options);

        if(isset($header_options)){

            switch($this->gettype($header_options, self::$R_data['int_flag']['R_integer'])){
                case self::$R_data['int_flag']['R_array']:

                    $this->header_options_add($header_options);

                break;
                case self::$R_data['int_flag']['R_string']:

                    $assembled_header_options   = array();
                    $assembled_header_options[] = $header_options;

                    $this->header_options_add($assembled_header_options);

                break;
                default:

                    $clr_ssl_msg = 'Invalid header data provided. ' . 
                                   '(' . 
                                   $this->gettype($header_options) . 
                                   ') header option data supplied. Expecting ' . 
                                   'string or array data.';
                    // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                    $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                 'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token = array(
                             'token'                   => $msg_token, 
                             'token_generation_date'   => $token_generation_date, 
                             'request_type'            => __METHOD__, 
                             'code'                    => 200, 
                             'clr_ssl_msg'             => $clr_ssl_msg);
                    $this->error_log(
                           $clr_ssl_msg, 
                           \LOG_WARNING, 
                           \E_WARNING, 
                           __LINE__, 
                           __METHOD__, 
                           __FILE__, 
                           $token);

                break;

            }

        }

        // Add CLR-SSL signature response header options.
        $this->header_options_add($this->header_signature_options_return());

        // Apply all header options. 
        $this->header_options_apply();

    }

