    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function get_config_cache_count(
             $data_key, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $data_authorization_profile = 'R_authorize & R_channel_RUNTIME')
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added input initialization 
         *       for ($data_authorization_profile = 
         *       CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_RUNTIME) and 
         *       with pizza and beer! 
         *       5 :: Tuesday, February 10, 2026 @ 0054 hrs.
         *
         */

        /* //
         * // Multi-Channel data extract loop logic.
         * // Convert an integer into an array of n+1
         * // channel designations where the limit is
         * // n = 0 to n = count(active channels).
         * // 
         * // 
         * // 5 :: Saturday, November 4, 2023 @ 1846 hrs.
         * switch($data_authorization_profile){
         *     case self::$R_data['int_flag']['R_authorize_all']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_GET']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_POST']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_COOKIE']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_SESSION']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_DATABASE']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_SSDTLA']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_PSSDTLA']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_RUNTIME']:
         *     case self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_SOAP']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_GET']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_POST']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_COOKIE']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_SESSION']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_DATABASE']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_SSDTLA']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_PSSDTLA']:
         *     case self::$R_data['int_flag']['R_authorize_all'] & ~self::$R_data['int_flag']['R_authorize'] & self::$R_data['int_flag']['R_channel_SOAP']:
         *
         *     break;
         *
         * }
         *
         */

        if(\is_string($data_authorization_profile) ||
            !isset($data_authorization_profile))
        {

            switch($data_authorization_profile){
                case 'R_authorize & R_channel_RUNTIME':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Convert CLR-SSL channel 
                     * data to integer. 
                     *
                     *
                     * 5 :: Monday, July 13, 2026 @ 0357 hrs.
                     *
                     */
                    $data_authorization_profile = self::$R_data['int_flag']['R_authorize'] & 
                                                  self::$R_data['int_flag']['R_channel_RUNTIME'];

                break;

            }

        }

        return self::$_R['kivotos']->R['rrs_map']->get_config_cache_count(
                                                   $data_key,
                                                   $data_type_family,
                                                   $data_authorization_profile);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function is_resource_serialization_active(
             $data_type, 
             $channel = 'R_channel_RUNTIME')
    {

        if(is_string($channel))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Convert CLR-SSL channel data 
             * to integer. 
             *
             *
             * 5 :: Monday, July 13, 2026 @ 0358 hrs.
             *
             */
            $channel = self::$R_data['int_flag'][$channel];

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CRNRSTN :: Lightsaber RoCEv2 
         * SOAP Services Layer (CLR-SSL) 
         * Multi-Channel Decoupled Data 
         * Object (MC-DDO) Data Input 
         * Serialization Layer. 
         *
         *
         * 5 :: Sunday, October 8, 2023 @ 0539 hrs.
         *
         */
        if(isset(self::$ddo_serializable_data_types_ARRAY[$data_type])){

            if(isset(self::$object_serializable_channels_ARRAY[$channel])){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Activate the Data 
                 * Serialization Layer 
                 * for the CRNRSTN :: 
                 * Lightsaber Multi-
                 * Channel Decoupled 
                 * Data Object (MC-DDO). 
                 *
                 * This layer provides 
                 * multi-channel data 
                 * serialization on 
                 * all supported data 
                 * types for reads and 
                 * writes. 
                 *
                 * PHP serialize() and 
                 * unserialize() are 
                 * built into the 
                 * CLR-SSL architecture 
                 * for data in/out. 
                 *
                 */
                return true;

            }

        }

        return NULL;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function isset_resource(
             $attribute, 
             $data_key, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $channel = NULL, 
             $index = NULL, 
             $ddo_memory_pointer = NULL)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This is used by the CLR-SSL 
         * internally if the DDO memory 
         * pointer is already available 
         * to save from having to 
         * generate yet another hash. 
         *
         */
        if(isset($ddo_memory_pointer))
            return self::$_R['kivotos']->R['rrs_map']->isset_config_cache(
                                                       $attribute,
                                                       $ddo_memory_pointer,
                                                       $channel,
                                                       $channel,
                                                       $index);

        return self::$_R['kivotos']->R['rrs_map']->isset_config_cache(
                                                   $attribute,
                                                   $this->hash_ddo_memory_pointer(
                                                          $data_key,
                                                          $data_type_family),
                                                   $channel,
                                                   $index);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function config_cache_data_write(
             $attribute, 
             $data, 
             $ddo_memory_pointer, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $index = NULL, 
             $data_authorization_profile = 'R_authorize & R_channel_RUNTIME', 
             $channel_override = NULL)
    {

        if(is_string($data_authorization_profile) || 
            !isset($data_authorization_profile))
        {

            switch($data_authorization_profile){
                case 'R_authorize & R_channel_RUNTIME':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Convert CLR-SSL channel 
                     * data to integer. 
                     *
                     *
                     * 5 :: Monday, July 13, 2026 @ 0359 hrs.
                     *
                     */
                    $data_authorization_profile = self::$R_data['int_flag']['R_authorize'] & 
                                                  self::$R_data['int_flag']['R_channel_RUNTIME'];

                break;

            }

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Push to CRNRSTN :: 
         * PLAID. 
         *
         */
        return self::$_R['kivotos']->R['rrs_map']->config_cache_data_write(
                                                   $attribute,
                                                   $data,
                                                   $ddo_memory_pointer,
                                                   $data_type_family,
                                                   $index,
                                                   $data_authorization_profile,
                                                   $channel_override);

    }

