    {

        switch($crnrstn_asset_family){
            case 'mime_type':

                if(isset($this->asset_routing_data_key_lookup_ARRAY[$crnrstn_asset_family][$salt_ugc])){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return the integer 
                     * constant for the 
                     * system profile 
                     * assigned to the 
                     * provided mime type. 
                     *
