                if(($this->is_bit_set((int) self::$R_data['int_flag']['R_fs_map_favicon']) == true) || 
                    (\strlen($this->return_crnrstn_asset_family() > 0)))
                {

                    if(isset($this->asset_routing_data_key_lookup_ARRAY[$crnrstn_asset_family][$salt_ugc])){

