                        $this->initialize_bit((int) self::$R_data['int_flag']['R_channel_GET']);

                        $tmp_data_key = $this->asset_routing_data_key_lookup_ARRAY[$crnrstn_asset_family][$salt_ugc];

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
