     * @access public
     *
     */
    function form_integrations_data_index(
             $crnrstn_form_handle_hash, 
             $output_type = 'string')
    {

        $tmp_str_out = '';
        $tmp_ARRAY = array();

        /*$this->print_r($this->form_integrations_data_index_ARRAY, 
         *       $crnrstn_form_handle_hash, 
         *       NULL, 
         *       __LINE__, 
         *       __METHOD__, 
         *       __FILE__);
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This should be form 
         * serialized...Ok for 
         * now...I guess. Trying 
         * to get to documentation. 
         *
         *
         * 5 :: Sunday, September 11, 2022 @ 2233 hrs.
         *
         *foreach($this->form_integrations_data_index_ARRAY[$crnrstn_form_handle_hash] as 
         *         $index => $data_key)
         *{
         *
         *error_log(__LINE__ . 
         *    ' crnrstn [' . 
         *    print_r($this->form_integrations_data_index_ARRAY, true) . 
         *    '].');
         *
         */
        if(isset($this->form_integrations_data_index_ARRAY[self::$R_data['int_flag']['CRNRSTN_PSSDTLA_PACKET']])){

            foreach($this->form_integrations_data_index_ARRAY[self::$R_data['int_flag']['CRNRSTN_PSSDTLA_PACKET']] as 
                $index => $data_key)
            {

                $tmp_str_out .= $data_key . '|::|';
                $tmp_ARRAY[] = $data_key;

            }

            $tmp_str_out = $this->strrtrim($tmp_str_out, '|::|');

            if($output_type == 'string'){

                return $tmp_str_out;

            }

            return $tmp_ARRAY;

        }

        return false;

    }

