    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function isset_http_param(
             $param, 
             $transport_protocol = 'POST')
    {

        if(is_array($transport_protocol)){

            if(self::$_R['kivotos']->R['env']->oHTTP_MGR->issetParam($transport_protocol, $param) == true)
                return true;
            else
                return false;

        }

        $http_protocol = strtoupper($transport_protocol);
        $http_protocol = $this->str_sanitize(
                                $http_protocol, 
                                'http_protocol_simple');

        try{

            switch($http_protocol){
                case 'POST':

                    if(self::$_R['kivotos']->R['env']->oHTTP_MGR->issetParam(
                                                                  $_POST,
                                                                  $param) == true)
                        return true;
                    else
                        return false;

                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * $_GET
                     *
                     */
                    if(self::$_R['kivotos']->R['env']->oHTTP_MGR->issetParam(
                                                                  $_GET,
                                                                  $param) == true)
                        return true;
                    else
                        return false;

            }

        }catch(\Exception $e){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Exception handling performed 
             * by the Logging Services Layer 
             * of the CRNRSTN :: Lightsaber 
             * RoCEv2 SOAP Services 
             * Layer (CLR-SSL). 
             *
             * Allow the CLR-SSL to handle 
             * this exception per the 
             * configured logging profile of 
             * the running application on 
             * this server. 
             *
             *
             * 5
             *
             * Sunday, June 30, 2024 @ 1518 hrs.
             * Last Modified: Friday, February 27, 2026 @ 0233 hrs.
             *
             */
            $this->catch_exception(
                   $e, 
                   \LOG_ERR, 
                   __METHOD__, 
                   __NAMESPACE__);

            return false;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function isset_http_superglobal($transport_protocol = 'POST')
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * We will still take $_POST, 
         * $_GET, etc. We only need 
         * this for HTTP/S at the moment.
         *
         * If sending string, only things 
         * like $transport_protocol='POST', 
         * $transport_protocol='$_POST', or 
         * $transport_protocol='GET'...etc, 
         * will work here.
         *
         * Not $transport_protocol='FILE'. 
         * Not $transport_protocol='SESSION'. 
         *
         */
        if(is_array($transport_protocol)){

            return self::$_R['kivotos']->R['env']->issetHTTP($transport_protocol);

        }

        $http_protocol = strtoupper($transport_protocol);
        $http_protocol = $this->str_sanitize(
                                $http_protocol, 
                                'http_protocol_simple');

        return self::$_R['kivotos']->R['env']->issetHTTP($http_protocol);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function extract_data_http(
             $param, 
             $transport_protocol = 'GET', 
             $tunnel_encrypted = false)
    {

        if(is_array($transport_protocol))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Camel-Cased Method  
             * names, e.g. extractData(), 
             * are OG CRNRSTN :: v1.0.0.
             *
             * https://crnrstn.evifweb.com/
             * documentation/classes/http_manager/extractdata/
             *
             */
            return self::$_R['kivotos']->R['env']->oHTTP_MGR->extractData(
                                                              $transport_protocol,
                                                              $param,
                                                              $tunnel_encrypted);

        $http_protocol = \strtoupper($transport_protocol);
        $http_protocol = $this->str_sanitize(
                                $http_protocol, 
                                'http_protocol_simple');

        try{

            switch($http_protocol){
                case 'POST':

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Camel-Cased Method  
                     * names, e.g. issetParam(), 
                     * are OG CRNRSTN :: v1.0.0.
                     *
                     * https://crnrstn.evifweb.com/
                     * documentation/classes/http_manager/issetparam/
                     *
                     */
                    if(self::$_R['kivotos']->R['env']->oHTTP_MGR->issetParam(
                                                                  $_POST,
                                                                  $param) == true)
                        return self::$_R['kivotos']->R['env']->oHTTP_MGR->extractData(
                                                                          $_POST,
                                                                          $param,
                                                                          $tunnel_encrypted);
                    else
                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * HOOOSTON, VE HAFF PROBLEM!
                         * https://www.wired.com/2011/04/alt-text-spacecraft/
                         *
                         *
                        throw new \Exception('The desired HTTP _' . 
                            $http_protocol . 
                            ' parameter, 
                            ' . $param . 
                            ', is not available.');
                         */
                        $this->error_log('The desired HTTP _' . 
                        $http_protocol . 
                        ' parameter, 
                        ' . $param . 
                        ', is not available.');

                break;
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * $_GET
                     *
                     */
                    if(self::$_R['kivotos']->R['env']->oHTTP_MGR->issetParam(
                                                                  $_GET,
                                                                  $param) == true)
                    {

                        return self::$_R['kivotos']->R['env']->oHTTP_MGR->extractData(
                                                                          $_GET,
                                                                          $param,
                                                                          $tunnel_encrypted);

                    }else{

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * HOOOSTON, VE HAFF PROBLEM!
                         * https://www.wired.com/2011/04/alt-text-spacecraft/
                         *
                         */
                        $clr_ssl_msg = 'The desired HTTP $_' . 
