                        $this->error_log(
                               $clr_ssl_msg, 
                               \LOG_NOTICE, 
                               \E_NOTICE, 
                               __LINE__, 
                               __METHOD__, 
                               __FILE__, 
                               $token);

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
