    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function set_crnrstn(
             $name, 
             $value = NULL, 
             $R_index_000 = NULL, 
             $R_index_001 = NULL, 
             $R_index_002 = NULL, 
             $R_index_003 = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed the crnrstn->set_crnrstn() 
         *       input parameters $index_0, 
         *       $index_1, $index_2, and 
         *       $index_3 to: 
         *       $R_index_000, 
         *       $R_index_001, 
         *       $R_index_002, and 
         *       $R_index_003. 
         *       5 :: Saturday, June 27, 2026 @ 0344 hrs.
         *       Last Modified: Saturday, June 27, 2026 @ 0403 hrs.
         *
         */

        switch($name){
            case 'system_openssl_cipher':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * The Lightbox Helper 
                 * by eVifweb® will update 
                 * this setting during 
                 * its own construction. 
                 *
                 *
                 * 5 :: Thursday, July 4, 2024 @ 1036 hrs.
                 *
                 */
                self::$openssl_cipher = $value;

            break;
            case 'byte_units_ARRAY':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * The Lightbox Helper 
                 * by eVifweb® will update 
                 * this setting during
                 * its own construction. 
                 *
                 *
                 * 5 :: Thursday, July 4, 2024 @ 1036 hrs.
                 *
                 */
                self::$R_data['R_byte_units'] = $value;

            break;
            case 'R_debug_mode':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Set after validation. 
                 *
                 */

                self::$R_data['R_debug_mode'] = $value;

            break;
            case 'phpmailer_debug_mode':

                self::$R_data['phpmailer_debug_mode'] = $value;

            break;
            case 'wordpress_debug_mode':

                self::$R_data['wordpress_debug_mode'] = $value;

            break;
            case 'env_err_reporting_profile_ARRAY':

                $this->env_err_reporting_profile_ARRAY[self::$R_data['R_cluster_id']][self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']]] = $value;

            break;
            case 'env_html_comments_mode_ARRAY':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * E.g.: 
                 * - CRNRSTN_HTML_COMMENTS_FULL, 
                 * - CRNRSTN_HTML_COMMENTS_NONE, and 
                 * - CRNRSTN_HTML_COMMENTS_CDN_STABILITY_CONTROL_ENABLED <-- *
                 *   * Timestamps are omitted 
                 *     from HTML comments. 
                 *
                 */

                $this->env_html_comments_mode_ARRAY[self::$R_data['R_cluster_id']][self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']]] = $value;

            break;
            case 'max_disk_storage_utilization_warning':

                self::$R_data['max_disk_storage_utilization_warning'] = $value;

            break;
            case 'max_disk_storage_utilization':

                self::$R_data['max_disk_storage_utilization'] = $value;

            break;
            case 'system_resource_profile_ARRAY':

                self::$system_resource_profile_ARRAY = $value;

            break;
            case 'object_serializable_channels_ARRAY':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * The CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services Layer 
                 * (CLR-SSL) Multi-Channel 
                 * Decoupled Data Object 
                 * (MC-DDO) Data Storage 
                 * Services Layer. 
                 *
                 *
                 * 5
                 *
                 * DDO settings and 
                 * configuration override. 
                 *
                 */
                self::$object_serializable_channels_ARRAY = $value;

            break;
            case 'ddo_serializable_data_types_ARRAY':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * The CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services Layer 
                 * (CLR-SSL) Multi-Channel 
                 * Decoupled Data Object 
                 * (MC-DDO) Data Storage 
                 * Services Layer. 
                 *
                 *
                 * 5
                 *
                 * DDO settings and 
                 * configuration override. 
                 *
                 */
                self::$ddo_serializable_data_types_ARRAY = $value;

            break;
            case 'permissions_chmod':

                self::$permissions_chmod = $value;

            break;
            case 'openssl_ARRAY':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * As an indication that 
                 * this is a request for 
                 * initialization, we will 
                 * leave $R_index_001 null. 
                 *
                 */
                if(!isset($R_index_001)){

                    switch($R_index_000){
                        case 'digest_method':
                        case 'cipher':

                            self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000]['options']['server'] = $value;

                        break;

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return an output 
                     * array to support 
                     * CLR-SSL configuration 
                     * initialization. 
                     *
                     */
                    return $value;

                }

                if(isset($R_index_000) && 
                    isset($R_index_001) && 
                    isset($R_index_002) && 
                    isset($R_index_003))
                {

                    self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000][$R_index_001][$R_index_002][$R_index_003] = $value;

                }else{

                    if(isset($R_index_000) && 
                        isset($R_index_001) && 
                        isset($R_index_002))
                    {

                        if($this->gettype(
                                  $value, 
                                  self::$R_data['int_flag']['R_integer']) == self::$R_data['int_flag']['R_array'])
                        {

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Load available 
                             * (on the server) 
                             * OpenSSL ciphers. 
                             *
                             */
                            self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000][$R_index_001][$R_index_002] = $value;

                        }else{

                            if($R_index_000 == 'cipher' && 
                                $R_index_001 == 'ISACTIVE')
                            {
                                // $data_key = $R_index_002, $data_type_family = $R_index_003

                                $tmp_cipher = strtolower(trim($value));

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * Update the internal 
                                 * reference data structure 
                                 * per the server's 
                                 * available OpenSSL ciphers 
                                 * and the input data. 
                                 *
                                 * 
                                 * CLR-SSL UGC data 
                                 * validation [_openssl_cipher_lib]
                                 *
                                 */
                                foreach((array) self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['cipher']['options']['server'] as 
                                    $cipher_index => $cipher_name)
                                {
                                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                     * TODO :: Is it a guarantee 
                                     *         that the server hash 
                                     *         name will always 
                                     *         be lowercase? 
                                     *
                                     */

                                    /*error_log(__LINE__ . 
                                     *    ' crnrstn [\'OPTIONS\'][\'SERVER\'] openssl_cipher $cipher_name[' . 
                                     *    $cipher_name . 
                                     *    '].');
                                     *
                                     */

                                    $tmp_lower_hash = \strtolower($cipher_name);
                                    self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['cipher']['options']['ISACTIVE'][$tmp_lower_hash] = $cipher_index;

                                    if($tmp_lower_hash == $tmp_cipher){

                                        self::$openssl_cipher_int = $cipher_index;
                                        self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['digest_method']['cipher']['default'][self::$R_data['int_flag']['R_integer']] = $cipher_index;
                                        self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['digest_method']['cipher']['default']['name']          = $tmp_cipher = $cipher_name;

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * Set environment OpenSSL 
                                         * cipher profile. 
                                         *
                                         */
                                        self::$_R['kivotos']->R['env']->set_openssl_cipher_profile(
                                                                        $cipher_name,
                                                                        $R_index_002,
                                                                        $R_index_003);

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * The CRNRSTN :: Lightsaber 
                                         * RoCEv2 SOAP Services Layer 
                                         * (CLR-SSL) Multi-Channel 
                                         * Decoupled Data Object 
                                         * (MC-DDO) Data Storage 
                                         * Services Layer. 
                                         *
                                         *
                                         * 5
                                         *
                                         * CRNRSTN :: UGC data 
                                         * input [_openssl_cipher_lib]
                                         *
                                         */
                                        $tmp_output = $this->add_resource(
