    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function isset_crnrstn(
             $name, 
             $R_index_000 = NULL, 
             $R_index_001 = NULL, 
             $R_index_002 = NULL, 
             $R_index_003 = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed the crnrstn->isset_crnrstn() 
         *       input parameters $index_0, 
         *       $index_1, $index_2, and 
         *       $index_3 to: 
         *       $R_index_000, 
         *       $R_index_001, 
         *       $R_index_002, and 
         *       $R_index_003. 
         *       5 :: Saturday, June 27, 2026 @ 0348 hrs.
         *       Last Modified: Saturday, June 27, 2026 @ 0404 hrs.
         *
         */

        switch($name){
            case 'R_debug_mode':
                // Set after validation.

                if(isset(self::$R_data['R_debug_mode'])){

                    return true;

                }

                return false;

            break;
            case 'env_err_reporting_profile_ARRAY':

                if(isset(self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']])){

                    if(isset($this->env_err_reporting_profile_ARRAY[self::$R_data['R_cluster_id']][self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']]])){

                        return true;

                    }

                    return true;

                }

                return false;

            break;
            case 'env_html_comments_mode_ARRAY':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * E.g.: 
                 * - CRNRSTN_HTML_COMMENTS_FULL, 
                 * - CRNRSTN_HTML_COMMENTS_NONE, and 
                 * - CRNRSTN_HTML_COMMENTS_CDN_STABILITY_CONTROL_ENABLED <-- *
                 *   * Timestamps are omitted 
                 *     from HTML comments. 
                 *
                 */

                if(isset(self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']])){

                    if(isset($this->env_html_comments_mode_ARRAY[self::$R_data['R_cluster_id']][self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']]])){

                        return true;

                    }

                    return true;

                }

                return false;

            break;
            case 'max_disk_storage_utilization_warning':

                if(isset(self::$R_data['max_disk_storage_utilization_warning'])){

                    return true;

                }

                return false;

            break;
            case 'max_disk_storage_utilization':

                if(isset(self::$R_data['max_disk_storage_utilization'])){

                    return true;

                }

                return false;

            break;
            case 'system_resource_profile_ARRAY':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * We will check 
                 * for any value 
                 * in the array. 
                 *
                 */
                if(isset(self::$system_resource_profile_ARRAY['max_disk_storage_utilization'])){

                    return true;

                }

                return false;

            break;
            case 'ddo_serializable_data_types_ARRAY':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * The CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services Layer 
                 * (CLR-SSL) Multi-Channel 
                 * Decoupled Data Object 
                 * (MC-DDO) Data Storage 
                 * Services Layer. 
                 *
                 *
                 * 5
                 *
                 * DDO settings and 
                 * configuration override. 
                 *
                 * We will check for any 
                 * value in the array. 
                 *
                 */
                if(count(self::$ddo_serializable_data_types_ARRAY) > 0){

                    return true;

                }

                return false;

            break;
            case 'permissions_chmod':

                if(isset(self::$permissions_chmod)){

                    return true;

                }

                return false;

            break;
            case 'openssl_ARRAY':

                if(isset($R_index_000) && 
                    isset($R_index_001) && 
                    isset($R_index_002) && 
                    isset($R_index_003))
                {

                    if(isset(self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000][$R_index_001][$R_index_002][$R_index_003])){

                        return self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000][$R_index_001][$R_index_002][$R_index_003];

                    }else{

                        return NULL;

                    }

                }else{

                    if(isset($R_index_000) && 
                        isset($R_index_001) && 
                        isset($R_index_002))
                    {

                        if(isset(self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000][$R_index_001][$R_index_002])){

                            return self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000][$R_index_001][$R_index_002];

                        }else{

                            return NULL;

                        }

                    }else{

                        switch($R_index_000){
                            case 'cipher':

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * Note: Inverted initialization 
                                 *       check. this is not a 
                                 *       vanilla "is_set()" return. 
                                 *
                                 *       [DO NOT COPY]
                                 *
                                 * 5 :: Thursday, November 30, 2023 @ 0549 hrs.
                                 *
                                 */
                                if(self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000]['default'][self::$R_data['int_flag']['R_integer']] == -1){

                                    return false;

                                }

                            break;
                            case 'digest_method':

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * Note: Inverted initialization 
                                 *       check. this is not a 
                                 *       vanilla "is_set()" return. 
                                 *
                                 *       [DO NOT COPY]
                                 *
                                 * 5 :: Thursday, November 30, 2023 @ 0549 hrs.
                                 *
                                 */
                                if(self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config'][$R_index_000]['default'][self::$R_data['int_flag']['R_integer']] == -1){

                                    return false;

                                }

                            break;

                        }

                        return true;

                    }

                }

            break;
            case 'log_silo_profile':
            case 'CRNRSTN_log_silo_profile':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Is CRNRSTN :: Log 
                 * Silo profile set? 
                 *
                 */
                if(isset(self::$log_silo_profile_ARRAY)){

                    //if(count(self::$log_silo_profile_ARRAY) > 0){
                    if(!!self::$log_silo_profile_ARRAY){

                        return true;

                    }

                }

                return false;

            break;
            case 'openssl_cipher_int':

                if(isset(self::$openssl_cipher_int)){

                    return true;

                }

                return false;

            break;
            case 'openssl_digest_preferred_ARRAY':

                if(isset(self::$openssl_digest_preferred_ARRAY[0])){

                    return true;

                }

                return false;

            break;
            case 'R_hmac_hash_config':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Edit: Changed R_hmac_hash_algorithm 
                 *       to R_hmac_hash_config. 
                 *       5 :: Saturday, June 27, 2026 @ 0542 hrs.
                 *
                 */

                if(!(self::$R_data['R_hmac']['default'][self::$R_data['int_flag']['R_integer']]) == -1){

                    return true;

                }

                return false;

            break;
            case 'R_hmac_algorithm_preferred':

                //if(!(self::$hmac_algorithm_preferred_ARRAY['DEFAULT'][self::$R_data['int_flag']['R_integer']] == -1)){
                if(!(self::$R_data['R_hmac_hash_config']['default'][self::$R_data['int_flag']['R_integer']] == -1)){

                    return true;

                }

                return false;

            break;
            case 'R_salt_default_length':

                if(isset(self::$R_data['R_salt_default_length'])){

                    return true;

                }

                return false;

            break;
            case 'byte_reporting_units':

                if(isset(self::$byte_reporting_system)){

                    return true;

                }

                return false;

            break;
            case 'byte_reporting_precision':

                if(isset(self::$byte_reporting_precision)){

                    return true;

                }

                return false;

            break;
            case 'data_channel_init_sequence':

                if(isset(self::$data_channel_init_sequence)){

                    return true;

                }

                return false;

            break;
            case 'static_css_length_unit':

                if(isset(self::$static_css_length_unit)){

                    return true;

                }

                return false;

            break;
            case 'css_length_units_ARRAY':

                return self::$_R['kivotos']->R['ui_html_mgr']->isset_crnrstn_interact_ui_html_mgr('css_length_units_ARRAY');

            break;
            case 'system_file_attributes_master_ARRAY':

                if(isset(self::$system_file_attributes_master_ARRAY)){

                    if(count(self::$system_file_attributes_master_ARRAY) > 0){

                        return true;

                    }

                }

                return false;

            break;
            case 'timezone_syntax_ARRAY':

                if(isset(self::$timezone_syntax_ARRAY[$R_index_000])){

                    return true;

                }

                return false;

            break;
            case 'system_theme_style_constants_ARRAY':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Edit: Replaced use of Icy Digital ITCC
                 *       Bitwise Svc Layer supported 
                 *       architecture behind
                 *       'system_theme_style_constants_ARRAY' 
                 *       with 
                 *       self::$R_data['interact_ui_theme_options'].
                 *       5 :: Thursday, May 28, 2026 @ 0728 hrs.
                 *
                 */
                if(isset($R_index_000)){

                    if(isset(self::$R_data['R_interact_ui_theme_options']['isset_options'][$R_index_000])){

                        return true;

                    }

                }

                return false;

            break;
            case 'system_log_output_profile_constants_ARRAY':

                if(isset($R_index_000)){

                    if(isset(self::$system_log_output_profile_constants_ARRAY[$R_index_000])){

                        return true;

                    }

                }

                return false;

            break;
            default:

                $clr_ssl_msg = 'Unknown switch case received, [' . 
                                \strval($name) . '].';
                // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                             'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token = array(
                         'token'                   => $msg_token, 
                         'token_generation_date'   => $token_generation_date, 
                         'request_type'            => __METHOD__, 
                         'code'                    => 200, 
                         'clr_ssl_msg'             => $clr_ssl_msg);
                $this->error_log(
                       $clr_ssl_msg, 
                       \LOG_ERR, 
                       \E_ERROR, 
                       __LINE__, 
                       __METHOD__, 
                       __FILE__, 
                       $token);

            break;

        }

        return false;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function soap_data_initialization_cache_output(
             $iso_lang_code = 'en', 
             $multi_lang_resource_key = NULL, 
             $attribute = '', 
             $R_resp = NULL, 
             $output_mode = 'TEXT', 
             $generate_version_synchronization_hash = false, 
             $generate_search_algorithm_data = false, 
             $css_style_ARRAY = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * 5 :: Wednesday, August 21, 2024 @ 0638 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: This 3Q 2024 method, 
         *       soap_data_cache_output_initialization(), 
         *       was copied from the CLR-SSL System 
         *       Link Library global function definition. 
         *       5 :: Thursday, November 6, 2025 @ 0420 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Refactored the crnrstn method 
         *       soap_data_cache_output_initialization() 
         *       to a new method name, 
         *       soap_data_initialization_cache_output 
         *       and removed all HTML DOM tag 
         *       input parameters. 
         *       5 :: Thursday, November 6, 2025 @ 0424 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added an input parameter, 
         *       $R_resp = NULL 
         *       to the crnrstn method 
         *       soap_data_cache_output_initialization() 
         *       and removed: 
         *       - $HTML_data = '', and 
         *       - $TEXT_data = ''. 
         *       5 :: Saturday, April 11, 2026 @ 1907 hrs.
         *
         */

        switch($output_mode){
            case 'MULTI-PART':

                $tmp_content_hash_html = '';
                $tmp_content_hash_text = '';
                $tmp_search_content    = '';

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: Lightsaber RoCEv2 
                 * SOAP Services Layer (CLR-SSL) 
                 * Multi-Language Services Layer 
                 * HTML and TEXT Content 
                 * ISO Language Control. 
                 *
                 *
                 * 5
                 *
                 * Sunday, August 25, 2024 @ 0759 hrs.
                 *
                 */
                $HTML_data = $this->multi_lang_content_return(
                                    $iso_lang_code,
                                    $multi_lang_resource_key,
                                    $attribute,
                                    $HTML_data,
                                    $css_style_ARRAY);

                $TEXT_data = $this->multi_lang_content_return(
                                    $iso_lang_code,
                                    $multi_lang_resource_key,
                                    $attribute,
                                    $TEXT_data,
                                    $css_style_ARRAY);

                if($generate_version_synchronization_hash !== false){

                    $tmp_content_hash_html = $this->hash($HTML_data);
                    $tmp_content_hash_text = $this->hash($TEXT_data);

                }

                if($generate_search_algorithm_data !== false){

                    $tmp_search_content = $this->str_sanitize(
                                                 $TEXT_data, 
                                                 'search');

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Return the multi-part 
                 * content string data from 
                 * the CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services Layer 
                 * (CLR-SSL) document object 
                 * model (DOM) HTML resource 
                 * type output control 
                 * services layer. 
                 *
                 *
                 * 5
                 *
                 * Sunday, August 25, 2024 @ 0723 hrs.
                 *
                 */
                return array(
                    'CONTENT_ID'             => $this->generate_new_key(
                                                       26, 
                                                       -1, 
                                                       true),
                    'ISO_LANG_CODE'          => $iso_lang_code,
                    'CONTENT_HTML'           => $HTML_data,
                    'LENGTH_HTML'            => \strlen($HTML_data),
                    'HTML_VERSION_SYNC_HASH' => $tmp_content_hash_html,
                    'CONTENT_TEXT'           => $TEXT_data,
                    'LENGTH_TEXT'            => \strlen($TEXT_data),
                    'TEXT_VERSION_SYNC_HASH' => $tmp_content_hash_text,
                    'SEARCH_ALGORITHM_DATA'  => $tmp_search_content
                );

            break;
            case 'HTML':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: Lightsaber RoCEv2 
                 * SOAP Services Layer (CLR-SSL) 
                 * Multi-Language Services Layer 
                 * HTML and TEXT Content 
                 * ISO Language Control. 
                 *
                 *
                 * 5
                 *
                 * Sunday, August 25, 2024 @ 0759 hrs.
                 *
                 */
                $HTML_data = $this->multi_lang_content_return(
                                    $iso_lang_code,
                                    $multi_lang_resource_key,
                                    $attribute,
                                    $HTML_data,
                                    $css_style_ARRAY);

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Return the HTML content 
                 * string data from the 
                 * CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services Layer 
                 * (CLR-SSL) Document Object 
                 * Model (DOM) HTML/Text 
                 * Resource Type Output 
                 * Control Services Layer. 
                 *
                 *
                 * 5
                 *
                 * Thursday, November 6, 2025 @ 0455 hrs.
                 *
                 */
                return $HTML_data;

            break;
            case 'TEXT':
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: Lightsaber RoCEv2 
                 * SOAP Services Layer (CLR-SSL) 
                 * Multi-Language Services Layer 
                 * HTML and TEXT Content 
                 * ISO Language Control. 
                 *
                 *
                 * 5
                 *
                 * Sunday, August 25, 2024 @ 0759 hrs.
                 *
                 */
                $TEXT_data = $this->multi_lang_content_return(
                                    $iso_lang_code, 
                                    $multi_lang_resource_key, 
                                    $attribute, 
                                    $TEXT_data, 
                                    $css_style_ARRAY);

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Return the Text content 
                 * string data from the 
                 * CRNRSTN :: Lightsaber 
                 * RoCEv2 SOAP Services Layer 
                 * (CLR-SSL) Document Object 
                 * Model (DOM) HTML/Text 
                 * Resource Type Output 
                 * Control Services Layer. 
                 *
                 *
                 * 5
                 *
