    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function hash_ddo_memory_pointer(
             $data_key, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $env_key = NULL)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * If $this->env_key(&NULL), 
         * this will perform the 
         * following update 
         * by reference:
         *
         * $env_key = (int) self::$R_data['int_flag']['CRNRSTN_RESOURCE_ALL'];
         *
         * See, 
         * https://www.php.net/manual/en/language.references.pass.php
         *
         * Passing by Reference
         * -----
         * You can pass a variable 
         * by reference to a function 
         * so the function can modify 
         * the variable. 
         *
         *
         * 5 :: Monday, July 15, 2024 @ 0044 hrs.
         *
         */
        $this->env_key($env_key);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * More than likely, this method will be 
         * called the most in vanilla CRNRSTN :: 
         * or any product that leaves the default 
         * image on maps resources to 
         * $_GET[] requests. 
         *
         * Here is some runtime optimization.
         *
         */
        $tmp_memory_pointer = self::$_R['kivotos']->R['rrs_map']->cache_rw_acceleration(
                                                                  $data_key,
                                                                  $data_type_family,
                                                                  $env_key);
        if(\strlen($tmp_memory_pointer) > 0)
            return $tmp_memory_pointer;

/*        //
 *        // This method 
 *        // is costly. 
 *        $tmp_dataset_prefix_str = $this->return_dataset_nomination_prefix(
 *                                         'string', 
 *                                         self::$R_data['R_cluster_id'], 
 *                                         $env_key, 
 *                                         $data_type_family);
 *
 *        self::$data_key_cache_rw_acceleration_ARRAY[$data_type_family][$data_key] = $tmp_dataset_prefix_str . '::' . $data_key;
 *
 *        return self::$data_key_cache_rw_acceleration_ARRAY[$data_type_family][$data_key];
 *
 */

        error_log('[lnum ' . 
            __LINE__ . 
            '] [' . 
            __METHOD__ .
            '] crnrstn Unable to ' . 
            'return or produce any ' . 
            'results here. ' . 
            'cache_rw_acceleration ' . 
            'data_key output [' .
            \strval($tmp_memory_pointer) . 
            '][len=' . 
            \strlen($tmp_memory_pointer) . 
            '].');

        return NULL;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function generate_weighted_elements_keys($cnt)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * self::$system_creative_element_keys_ARRAY =
         * array('CRNRSTN ::', 
         *       'LINUX_PENGUIN_SMALL', 
         *       'REDHAT_LOGO', 
         *       'APACHE_POWER_VERSION', 
         *       'APACHE_FEATHER',
         *       'CRNRSTN_R', 
         *       '5', 
         *       'MYSQL_DOLPHIN', 
         *       'PHP_ELLIPSE', 
         *       'POWER_BY_PHP', 
         *       'ZEND_LOGO', 
         *       'ZEND_FRAMEWORK', 
         *       'ZEND_FRAMEWORK_3', 
         *       'REDHAT_HAT_LOGO');
         *
         */
        $output_ratio_ARRAY = array(8, 
                                    6, 
                                    10, 
                                    6, 
                                    8, 
                                    5, 
                                    3, 
                                    1, 
                                    7, 
                                    7, 
                                    7, 
                                    5, 
                                    5, 
                                    5, 
                                    3);

        for ($i = 0; $i < $cnt; $i++){

            if(!isset($output_ratio_ARRAY[$i])){

                $output_ratio_ARRAY[$i] = 1;

            }

            for ($ii = 0; $ii < $output_ratio_ARRAY[$i]; $ii++){

                $this->weighted_elements_keys_ARRAY[] = self::$system_creative_element_keys_ARRAY[$i];

            }

        }

    }


