     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function clear_all_bits_set_one(
             $int_const_the_one, 
             $is_bit_set = true, 
             $integer_clear_ARRAY = array())
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CLEAR ALL
         *
         */
        foreach($integer_clear_ARRAY as 
            $index => $integer_constant)
        {

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * If the condition of this 
             * integer in Icy Digital ITCC 
             * Bitmask Technology is as it 
             * is flipped in its state, 
             * we will turn it off. 
             *
             */
            if($this->is_bit_set($integer_constant) == true){

                $this->initialize_bit($integer_constant, false);

            }

        }

        $this->initialize_bit($int_const_the_one, $is_bit_set);

        return true;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * CRNRSTN :: Lightsaber Icy 
     * Digital ITCC Bitmask 
     * Integer State (Bit Flip) 
     * Management Services Layer. 
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_set_bits(
             $integer_constants_ARRAY, 
             $first_match = false)
    {

        /* $this->oCRNRSTN_BITWISE->set($integer_constant);
         * $this->oCRNRSTN_BITWISE->toggle($integer_constant);
         * $this->oCRNRSTN_BITWISE->read($integer_constant);
         * $this->oCRNRSTN_BITWISE->remove($integer_constant);
         * $this->oCRNRSTN_BITWISE->stringout();
         * self::$_R['kivotos']->R['bitflip_mgr']->set($integer_constant, true);
         */

        $tmp_array = array();

        foreach($integer_constants_ARRAY as 
            $index => $int_constant)
        {

            if(is_string($int_constant))
                $int_constant = $index;

            if($this->is_bit_set($int_constant) == true){

                $tmp_array[] = $int_constant;

                if($first_match == true)
                    return $tmp_array;

            }

        }

        return $tmp_array;

    }

    /**
     * R :: Content pending. 
