     */
    function return_system_info($property)
    {
        if(isset(self::$_R['kivotos']->R['bitflip_mgr'])){

            return self::$_R['kivotos']->R['bitflip_mgr']->return_system_info($property);

        }else{

            switch($property){
                case 'os_bit_size':

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * 5 :: Thursday, October 10, 2024 @ 1005 hrs.
                     *
                     * error_log('[lnum ' . 
                     *     __LINE__ . '] [' . 
                     *     __METHOD__ . 
                     *     '] TODO :: Simplify the ' . 
                     *     'initialization of the operating ' . 
                     *     'system integer size to ' . 
                     *     'use "PHP_INT_SIZE" [' . 
                     *     PHP_INT_SIZE . 
                     *     '].');
                     *
                     * # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return OS integer size (bit size) 
                     * using the system provided 
                     * PHP_INT_SIZE global constant. 
                     *
                     *
                     * 5 :: Friday, October 24, 2025 @ 0533 hrs.
                     *
                     */
                    switch(\PHP_INT_SIZE){
                        case 4:

                            return (int) 32;

                        break;
                        case 8:
                        default:

                            return (int) 64;

                        break;

                    }

                break;

            }

            return '';

        }

    }

