    /**
     * R :: Content pending. 
     *
     * @return
     * @access private
     *
     */
    private function initialize_os()
    {

        self::$R_data['operating_system']['process_id']             = \getmypid();
        self::$R_data['operating_system']['mbstring_func_overload'] = false;

        if(\stripos(PHP_OS, 'WIN') === 0) 
            self::$R_data['operating_system']['os_path_dir_separator_char'] = '\\';
        else
            self::$R_data['operating_system']['os_path_dir_separator_char'] = '/';

        $R_path_patterns = $R_path_replacements = array();
        switch(self::$R_data['operating_system']['os_path_dir_separator_char']){
            case '\\':
                // Windows® OS

                self::$R_data['operating_system']['name']                   = 'Windows®';
                self::$R_data['operating_system']['R_path_patterns'][0]     = '/';
                self::$R_data['operating_system']['R_path_replacements'][0] = self::$R_data['operating_system']['os_path_dir_separator_char'];

            break;
            case '/':
            default:
                // Linux OS

                self::$R_data['operating_system']['name']                   = 'Linux';
                self::$R_data['operating_system']['R_path_patterns'][0]     = '\\';
                self::$R_data['operating_system']['R_path_replacements'][0] = self::$R_data['operating_system']['os_path_dir_separator_char'];

            break;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize the server 
         * L.A.M.P. profile meta 
         * here within the 
         * CRNRSTN :: Lightsaber 
         * RoCEv2 SOAP Services 
         * Layer (CLS-SSL). 
         *
         *
