    /**
     * R :: Return the CLR-SSL framework path root.
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_root(
             $system_path = NULL,
             $application_directory_override = NULL,
             $R_framework_directory_override = NULL)
    {
        // 5 :: Saturday, August 1, 2026 @ 1631 hrs.

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Variable Initialization.
         *
         */
        $root              =
        $crnrstn_file_path = NULL;

        if(!isset($application_directory_override)) 
            $application_directory = self::$R_data['application_directory'];
        else
            $application_directory = $application_directory_override;

        if(!isset($R_framework_directory_override)) 
            $R_framework_directory= self::$R_data['R_framework_directory'];
        else
            $R_framework_directory = $R_framework_directory_override;

        $directory_shift  =
        $path_chunk       = array();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Evaluate $application_directory for 
         * any change directory input commands. 
         *
         * Happy birthday to you, J5, my boy! 
         * 11/11/2005 - 08/16/2021 @ 0345 hrs. 
         *
         *
         * 5 :: Tuesday, November 11, 2025 @ 2111 hrs.
         *
         */
        if((\strpos($application_directory, '../') !== false) || 
            ($application_directory == ''))
        {

            if(isset($system_path)) 
                $script_filename = \str_replace(
                                        self::$R_data['operating_system']['R_path_patterns'][0], 
                                        self::$R_data['operating_system']['R_path_replacements'][0], 
                                        $system_path);
            else
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Standardize the use of
                 * directory separator based
                 * on path replacement
                 * patterns specific to the
                 * server operating system.
                 *
                 *
                 * 5
                 *
                 */
                $script_filename = \str_replace(
                                        self::$R_data['operating_system']['R_path_patterns'][0], 
                                        self::$R_data['operating_system']['R_path_replacements'][0], 
                                        $_SERVER['SCRIPT_FILENAME']);
            $script_filepath_ARRAY  = \explode(self::$R_data['operating_system']['os_path_dir_separator_char'], $script_filename);
            $app_directory          = \explode('../', $application_directory);
            $change_directory_depth = \sizeof($app_directory);

            for($i = 0; $i < $change_directory_depth; $i++){

                $tmp_data          = \array_pop($script_filepath_ARRAY);
                $app_dir_chunk     = \array_pop($app_directory);
                $directory_shift[] =  '../';

                if(($app_dir_chunk != '..') && 
                    ($app_dir_chunk != '.')) 
                    $path_chunk[] = $app_dir_chunk;

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Remove one "../" directory shift, 
             * and then convert (implode) the 
             * $directory_shift array into 
             * string data. 
             *
             *
             * 5 :: Case of the Monday's, August 3, 2026 @ 0545 hrs.
             *
             * Lights off a surpassingly 
             * righteous rip on the bong 
             * with fire from the kitchen 
             * stove gas range. 
             * Sips coffee. 
             *
             */
            $tmp_data                        = \array_pop($directory_shift);
            self::$R_data['directory_shift'] = \implode('', $directory_shift);

            if(\strlen($path_chunk[0]) > 0) 
                self::$R_data['directory_shift'] .= $path_chunk[0];

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of HTTP 
             * forward slashes by removing 
             * any trailing slash. 
             *
             *
             * 5
             *
             */
            self::$R_data['directory_shift'] = \rtrim(self::$R_data['directory_shift'], '/');

            if(\strlen($path_chunk[0]) > 0)
                $root = \implode(self::$R_data['operating_system']['os_path_dir_separator_char'], $script_filepath_ARRAY) . 
                        self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                        $path_chunk[0] . 
                        self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                        $R_framework_directory;
            else
                $root = \implode(self::$R_data['operating_system']['os_path_dir_separator_char'], $script_filepath_ARRAY) . 
                        self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                        $R_framework_directory;

            $root = \str_replace(
                         self::$R_data['operating_system']['R_path_patterns'][0], 
                         self::$R_data['operating_system']['R_path_replacements'][0], 
                         $root);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of the 
             * operating system specific 
             * directory separator by 
             * reducing all double slashes 
             * to single. 
             *
             *
             * 5
             *
             */
            while(\strpos($root, 
                          self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                          self::$R_data['operating_system']['os_path_dir_separator_char']) !== false)
                $root = \str_replace(self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                                     self::$R_data['operating_system']['os_path_dir_separator_char'],
                                     self::$R_data['operating_system']['os_path_dir_separator_char'], 
                                     $root);

        }

        if(!isset($root)){

            $root = $_SERVER['DOCUMENT_ROOT'] .
                    \DIRECTORY_SEPARATOR . 
                    $application_directory . 
                    \DIRECTORY_SEPARATOR . 
                    $R_framework_directory . 
                    \DIRECTORY_SEPARATOR;

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of
             * directory separator based
             * on path replacement
             * patterns specific to the
             * server operating system.
             *
             *
             * 5
             *
             */
            $root = \str_replace(
                         self::$R_data['operating_system']['R_path_patterns'][0], 
                         self::$R_data['operating_system']['R_path_replacements'][0], 
                         $root);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of the
             * operating system specific
             * directory separator by
             * reducing all double slashes
             * to single.
             *
             *
             * 5
             *
             */
            while(\strpos($root, 
                          self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                          self::$R_data['operating_system']['os_path_dir_separator_char']) !== false)
                $root = \str_replace(
                             self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                             self::$R_data['operating_system']['os_path_dir_separator_char'],
                             self::$R_data['operating_system']['os_path_dir_separator_char'], 
                             $root);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Remove trailing 
             * slash. 
             *
             */
            $root = $this->strrtrim(
                           $root, 
                           self::$R_data['operating_system']['os_path_dir_separator_char']);

        }

        return $root;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * @param OpenSSL version identifier as 
     * hex value $openssl_version_number
     * 
     * OPENSSL_VERSION_NUMBER parser, works 
     * from OpenSSL v.0.9.5b+ (e.g. for use 
     * with version_compare())
     *
     * OPENSSL_VERSION_NUMBER is a numeric 
     * release version identifier for OpenSSL 
     * Syntax: MNNFFPPS: major minor fix 
     * patch status (HEX) 
     *
     * The status nibble meaning: 
     * 0         => development, 
     * 1 to e    => betas, 
     * f         => release
     *
     * Examples:
     * - 0x000906023 => 0.9.6b beta 3
     * - 0x00090605f => 0.9.6e release
     * - 0x1000103f  => 1.0.1c
     * 
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function get_openssl_version_number(
                     $patch_as_number = false, 
                     $openssl_version_number = null)
    {

        if(isset(self::$R_data['operating_system']['openssl_version']))
            return self::$R_data['operating_system']['openssl_version'];

        if(\is_null($openssl_version_number)) 
            $openssl_version_number = \OPENSSL_VERSION_NUMBER;

        $openssl_numeric_identifier = \str_pad(
                                      (string) \dechex($openssl_version_number), 
                                      8, 
                                      '0', 
                                      \STR_PAD_LEFT);

        $openssl_version_parsed = array();
        $preg = '/(?<major>[[:xdigit:]])(?<minor>[[:xdigit:]][[:xdigit:]])(?<fix>[[:xdigit:]][[:xdigit:]])';
        $preg .= '(?<patch>[[:xdigit:]][[:xdigit:]])(?<type>[[:xdigit:]])/';

        \preg_match_all(
            $preg, 
            $openssl_numeric_identifier, 
            $openssl_version_parsed);

        $openssl_version = false;
        if(!empty($openssl_version_parsed)){

            $alphabet = array(1 => 'a', 2 => 'b', 
                              3 => 'c', 4 => 'd', 
                              5 => 'e', 6 => 'f', 
                              7 => 'g', 8 => 'h', 
                              9 => 'i', 10 => 'j', 
                              11 => 'k', 12 => 'l', 
                              13 => 'm', 14 => 'n', 
                              15 => 'o', 16 => 'p', 
                              17 => 'q', 18 => 'r', 
                              19 => 's', 20 => 't', 
                              21 => 'u', 22 => 'v', 
                              23 => 'w', 24 => 'x', 
                              25 => 'y', 26 => 'z');

            $openssl_version = \intval($openssl_version_parsed['major'][0]) . '.';
            $openssl_version .= \intval($openssl_version_parsed['minor'][0]) . '.';
            $openssl_version .= \intval($openssl_version_parsed['fix'][0]);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Ideal for 
             * text comparison. 
             *
             */
            $openssl_version_int_val = \intval($openssl_version_parsed['patch'][0]);

            if(!$patch_as_number && 
                \array_key_exists($openssl_version_int_val, $alphabet))
                $openssl_version .= $alphabet[$openssl_version_int_val];
            else
                if($openssl_version_int_val != 0)
                    $openssl_version .= '.' . $openssl_version_int_val; 

        }

        return $openssl_version;

    }

