    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_encoder_wheel_output(
             $code_controller, 
             $background_noise = NULL, 
             $output_length = 25)
    {

        $output_str = '';
        $output_str_len = 0;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Build string of 0/1 
         * using $code_controller. 
         *
         */
        $code_controller_char_ARRAY = \str_split($code_controller);

        foreach($code_controller_char_ARRAY as 
            $index => $controller_char)
        {

            $output_str_len++;
            $output_str              .= self::$wheel_encoder_character[$controller_char];
            $encoder_position_ARRAY[] = self::$wheel_encoder_character_index[$controller_char];

            if($output_str_len >= $output_length)
                return $output_str;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Do we have 
         * the length?
         *
         */
        $delta = $output_length - \strlen($output_str);
        if($delta > 0){

            if(!isset($background_noise))
                $background_noise = $this->salt(40 + \count(self::$wheel_encoder_character));

        }

        $noise_ARRAY = \str_split($background_noise);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Guarantee overflow of 
         * output length by repetition 
         * of noise fill pattern. 
         *
         */
        for($i = \strlen($output_str); $i < $output_length; $i++){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Using code controller 
             * character index positions 
             * as key, concatenate matches 
             * with background noise to 
             * fill any remaining length. 
             *
             */
            foreach($encoder_position_ARRAY as 
                $index => $position)
            {

                $output_str .= self::$wheel_encoder_character[$noise_ARRAY[$position]];

                $i++;

                if($i > $output_length) break 1;

            }

        }

        return $output_str;

    }

    /**
     * R :: Content pending. 
     *
     * @return
     * @access private
     *
     */
    private function encoder_wheel_integrations()
    {

        $salt_tail = $this->return_encoder_wheel_output(
                            self::$wheel_encoder_salt, 
                            $this->hash(self::$R_data['R_cluster_id'] . 
                                        self::$R_data['R_node_id']),  
                            10);

        self::$crnrstn_session_salt = 'crnrstn_' . 
                                      $salt_tail;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function initialize_alpha_shift_crypt($salt)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * J5, my boy!
         *
         * Initialize the
         * alpha shift key.
         *
         *
         * 5 :: Tuesday, July 23, 2024 @ 1715 hrs.
         *
         */
        self::$wheel_encoder_salt = $salt;
        $int_str_01               = 0;
        $char_count               = 0;
        $int_str_01               = 1;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Load the alphabet.
         *
         * SOURCE   :: https://www.php.net/manual/en/function.range.php
         * SOURCE   :: https://stackoverflow.com/questions/431912/way-to-get-all-alphabetic-chars-in-an-array-in-php
         * COMMENT  :: https://stackoverflow.com/a/431930
         * COMMENT  :: https://stackoverflow.com/a/433119
         * AUTHOR   :: https://stackoverflow.com/users/44639/pez
         *
         *
         * PEZ
         *
         */
        $alphas = \array_merge(\range('A', 'Z'), \range('a', 'z'));

        // $alpha = range('A', 'Z')
        foreach($alphas as 
            $letter)
        {

            self::$wheel_encoder_character[$letter]       = $int_str_01;
            self::$wheel_encoder_character_index[$letter] = $char_count;

            $char_count++;

            if($int_str_01 == 0)
                $int_str_01 = 1;
            else
                $int_str_01 = 0;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Load some numbers. 
         *
         */
        foreach(\range(0, 9) as 
            $letter)
        {

            self::$wheel_encoder_character[$letter]       = $int_str_01;
            self::$wheel_encoder_character_index[$letter] = $char_count;

            $char_count++;

            if($int_str_01 == 0)
                $int_str_01 = 1;
            else
                $int_str_01 = 0;

        }

    }

