    function config_is_valid_detected_env(
             $env_key, 
             $force_detection = true)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Is the environment 
         * detected? 
         *
         */
        if(!isset(self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']]) && 
            ($force_detection == true))
            return false;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Does the detected 
         * environment align 
         * with the method 
         * input key? 
         *
         */
        if($env_key == self::$R_data['int_flag']['CRNRSTN_RESOURCE_ALL'] || 
            (self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']] == $this->hash($env_key)))
            return true;

        return false;

    }

