    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_module_deep_link_token(
             $module_key, 
             $token_override = NULL, 
             $html_encapsulate = true)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Is this the 
         * first token? 
         *
         */
        if(!isset($this->content_token_index)){

            $this->content_token_index = -1;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Generate next 
         * token. 
         *
         */
        $this->content_token_index++;

        if(!isset($token_override)){

            $tmp_token_seed = $this->hash(
                                     $module_key . 
                                     '_' . 
                                     $this->content_token_index);
            /*error_log(__LINE__ . ' [' . 
             *    $module_key . 
             *    ']. $this->content_token_index[' . 
             *    $this->content_token_index . 
             *    ']. $tmp_token_seed[' . 
             *    $tmp_token_seed . 
             *    '].');
             *
             */

        }else{

            $tmp_token_seed = $this->hash(
                                     $module_key . 
                                     '_' . 
                                     $token_override . 
                                     '_' . 
                                     $this->content_token_index);
            /*error_log(__LINE__ . 
             *    ' [' . $module_key . 
             *    ']. $this->content_token_index[' . 
             *    $this->content_token_index . 
             *    ']. $tmp_token_seed[' . 
             *    $tmp_token_seed . 
             *    '].');
             *
             */

        }

        $tmp_token_seed = $this->return_encoder_wheel_output(
                                 $tmp_token_seed, 
                                 NULL, 
                                 \strlen($tmp_token_seed));

        if(!($html_encapsulate == true)){

            return $tmp_token_seed;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This will salt the content 
         * to support string comparison 
         * checks during JS driven 
         * styling at the client and 
         * for use in (search result, 
         * docs). This is so that deep 
         * links will have an anchor 
         * to which to auto-scroll to 
         * after the page loads. 
         * 
         * "Crawling" the meta to 
         * build content versioning 
         * hash tokens and search 
         * indexes will strip these 
         * links out automatically, 
         * and then we will use the 
         * data to build the 
         * deep link. 
         *
         */
        $tmp_out_html = '<span class="crnrstn_hidden">' . 
                        '<a name="crnrstn_tokenized_top_' . 
                        $tmp_token_seed . 
                        '"> ' . 
                        $tmp_token_seed . 
                        '</a></span>';

        return $tmp_out_html;

    }

