    private function apply_CRNRSTN_asErrorHandler($err_reporting_profile = NULL)
    {

        if(isset($err_reporting_profile)){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * SOURCE :: https://stackoverflow.com/questions/1241728/can-i-try-catch-a-warning
             * COMMENT :: https://stackoverflow.com/a/1241751
             * AUTHOR :: Philippe Gerber :: https://stackoverflow.com/users/117260/philippe-gerber
             *
             * Set to the user 
             * defined error handler. 
             *
             */
            $old_error_handler = set_error_handler(function ($errno, $errstr, $errfile, $errline, $errcontext){

                try{

                    // error was suppressed with the @-operator
                    if(0 === error_reporting())
                        return false;

                    if(is_array($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                        self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID']))
                    {

                        $errstr = '';

                        foreach($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                            self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'] as 
                            $log_index => $log_data)
                            $errstr .= $log_data;

                    }else{

                        $errstr = $_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                                  self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'] . 
                                  $errstr;

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Clear the session of 
                     * system message data.
                     *
                     */
                    array_splice($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                        self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'], 0);

                    throw new ErrorException(
                              $errstr, 
                              0, 
                              $errno, 
                              $errfile, 
                              $errline);

                }catch(\Exception $e){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Exception handling performed 
                     * by the Logging Services Layer 
                     * of the CRNRSTN :: Lightsaber 
                     * RoCEv2 SOAP Services 
                     * Layer (CLR-SSL). 
                     *
                     * Allow the CLR-SSL to handle 
                     * this exception per the 
                     * configured logging profile of 
                     * the running application on 
                     * this server. 
                     *
                     *
                     * 5
                     *
                     * Sunday, June 30, 2024 @ 1530 hrs.
                     * Last Modified: Friday, February 27, 2026 @ 0233 hrs.
                     *
                     */
                    $this->catch_exception(
                           $e, 
                           \LOG_ERR, 
                           __METHOD__, 
                           __NAMESPACE__);

                    return false;

                }

            }, (int)$err_reporting_profile);

        }else{

            $old_error_handler = set_error_handler(function ($errno, $errstr, $errfile, $errline, $errcontext){

                try{

                    // error was suppressed with the @-operator
                    if(0 === error_reporting())
                        return false;

                    if(is_array($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                        self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID']))
                    {

                        $errstr = '';

                        foreach($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                            self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'] as 
                            $log_index => $log_data)
                            $errstr .= $log_data;

                    }else{

                        $errstr = $_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                                  self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'] . 
                                  $errstr;

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Clear the session 
                     * of system message data. 
                     *
                     */
                    array_splice($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                        self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'], 0);

                    throw new ErrorException(
                        $errstr, 
                        0, 
                        $errno, 
                        $errfile, 
                        $errline);

                }catch(\Exception $e){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Exception handling performed 
                     * by the Logging Services Layer 
                     * of the CRNRSTN :: Lightsaber 
