    function error_log_clear($message_token = NULL){
        // 5 :: Tuesday, May 12, 2026 @ 0845 hrs.

        if(isset(self::$_R['kivotos']->R['logging']))
            // 5 :: Friday, May 22, 2026 @ 1107 hrs.
            return self::$_R['kivotos']->R['logging']->error_log_clear($message_token);

        if(isset($message_token)){

            if(isset(self::$R_data['spool']['err_message_queue_push'][$message_token])){

                //array_splice(self::$R_data['spool']['err_message_queue_push']['message_token'], 0); // Clear all tokens?
                \array_splice(self::$R_data['spool']['err_message_queue_push'][$message_token]['message'], 0);
                \array_splice(self::$R_data['spool']['err_message_queue_push'][$message_token]['data_authorization_profile'], 0);

            }

        }

        if(isset(self::$R_data['R_cluster_id'])){

            if(isset($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'])){

                \array_splice($_SESSION['CRNRSTN_ERROR_PREFIX_' .
                    self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'], 
                    0);

            }

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function clr_ssl_syslog_prefix(
             $line_num, 
             $file, 
             $method = '', 
             $prefix_override = NULL,
             $syslog_prefix_passthrough = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Added the method, clr_ssl_syslog_prefix(), 
         * to the CLR-SSL. 
         * 5 :: Wednesday, May 20, 2026 @ 1539 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added $syslog_prefix_passthrough 
         *       input parameter to 
         *       clr_ssl_syslog_prefix to support 
         *       white label system (syslog) message 
         *       prefix passthrough. 
         *       5 :: Friday, May 22, 2026 @ 0423 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Do we apply a syslog 
         * prefix white labeling 
         * overwrite? 
         *
         *
         * 5 :: Friday, May 22, 2026 @ 0655 hrs.
         *
         */

        if(isset(self::$_R['kivotos']->R['logging']))
            // 5 :: Friday, May 22, 2026 @ 1109 hrs.
            return self::$_R['kivotos']->R['logging']->clr_ssl_syslog_prefix(
                                                       $line_num,
                                                       $file,
                                                       $method,
                                                       $prefix_override,
                                                       $syslog_prefix_passthrough);

        if(\strlen(\trim($syslog_prefix_passthrough)) < 1){

            $syslog_prefix = 'R :: ';
            if(isset($prefix_override))
                $syslog_prefix = $prefix_override;

            $syslog_prefix .= '[' . $this->return_micro_time() . 
                              '] ';

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * String concat __METHOD__ 
             * only if data exists. 
             *
             *
             * 5 :: Wednesday, May 20, 2026 @ 1540 hrs.
             *
             */
            if($method != '')
                $syslog_prefix .= '[mthd ' . 
                                  $method . '] ';
            else
                if($file != '')
                    $syslog_prefix .= '[file ' . 
                                      $file . '] ';

            $syslog_prefix .= '[lnum ' . 
                              $line_num . '] [rtime ' . 
                              $this->wall_time() . 
                              '] ';

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Apply a syslog prefix 
             * white labeling overwrite. 
             *
             *
             * 5 :: Friday, May 22, 2026 @ 0655 hrs.
             *
             */
            $syslog_prefix = $syslog_prefix_passthrough;

        }

        return $syslog_prefix;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function session_runtime(
             $reporting_mode = 'R_float', 
             $finite_express_mode = 'ELAPSED', 
             $decimal = 8)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, session_runtime(), 
         * to crnrstn from R_session_mgr, and 
         * we cranked on the input parameters. 
         * 5 :: Wednesday, May 20, 2026 @ 2310 hrs.
         */

        if(\is_string($reporting_mode)) 
            $reporting_mode = self::$R_data['int_flag'][$reporting_mode];

        if(isset(self::$_R['kivotos']->R['session_mgr']))
            return self::$_R['kivotos']->R['session_mgr']->session_runtime(
                                                           $reporting_mode,
                                                           $finite_express_mode,
                                                           $decimal);

        if(!isset($_SESSION['R_cluster_id_starttime']))
            $_SESSION['R_cluster_id_starttime'] = $this->microtime_float();

        $tmp_mirco_time_float = $this->microtime_float();
        $timediff             = $tmp_mirco_time_float - $_SESSION['R_cluster_id_starttime'];
        $len                  = $decimal * -1;

        switch($reporting_mode){
            case self::$R_data['int_flag']['R_string']:

                return $this->incarnate($finite_express_mode, $timediff, true);

            break;
            case self::$R_data['int_flag']['R_float']:
            case self::$R_data['int_flag']['R_double']:

                if(self::$R_data['operating_system']['name'] == 'Windows®')
                    return (double) $timediff;

                return \substr($timediff, 0, $len);

            break;
            case self::$R_data['int_flag']['R_int']:
            case self::$R_data['int_flag']['R_integer']:
            default:

                if(self::$R_data['operating_system']['name'] == 'Windows®')
                    return (int) $timediff;

                return \substr($timediff, 0, $len);

            break;

        }

    }

