            self::$R_data['spool']['err_message_queue_push']['message'][]                    = $message;
            self::$R_data['spool']['err_message_queue_push']['data_authorization_profile'][] = $data_authorization_profile;

            return true;

        }

        return self::$_R['kivotos']->R['logging']->err_message_queue_push(
                                                   $message_serial,
