    private function ____initialize_file_system_constant(
                     $mime_type = NULL, 
                     $ext = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This was just a test for 
         * the programmatic initialization 
         * of bit flippable integers.
         * there are some nice data 
         * structures in here...so 
         * keeping this method around.
         *
         * Prioritize mime type over 
         * file extension for
         * profiling appropriate 
         * file options. 
         *
         */
        if(isset($mime_type)){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * MIME
             *
             */

            /*
            'CRNRSTN_HTM', 'CRNRSTN_PHP', 
            'CRNRSTN_SQL', 'CRNRSTN_XML', 
            'CRNRSTN_XSLT', 'CRNRSTN_TXT', 
            'CRNRSTN_RTF', 'CRNRSTN_CSV', 
            'CRNRSTN_TIF', 'CRNRSTN_BMP', 
            'CRNRSTN_SVG', 'CRNRSTN_PIC', 
            'CRNRSTN_ZIP', 'CRNRSTN_EXE', 
            'CRNRSTN_BAT', 'CRNRSTN_TAR', 
            'CRNRSTN_PSD', 'CRNRSTN_AI',
