    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function detectServerEnv(
                     $env_key_hash, 
                     $data_key, 
                     $value, 
                     $required_server_matches)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Check the environmental 
         * detection keys for matches 
         * against the server 
         * configuration. 
         *
         */
        if(array_key_exists($data_key, $_SERVER)){

            $clr_ssl_msg = 'We have a SERVER param [' . 
                           \strval($data_key) . 
                           '] to check value [' . 
                           \strval($value) . 
                           '] for match against ' . 
                           'actual SERVER[].';
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_DEBUG, 
                   \E_NOTICE, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token);

            return $this->isServerKeyMatch(
                          $env_key_hash, 
                          $data_key, 
                          $value, 
                          $required_server_matches);

        }else{

            return false;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function isServerKeyMatch(
                     $env_key_hash, 
                     $data_key, 
                     $value, 
                     $required_server_matches)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Run value comparison 
         * for incoming value and 
         * data from the server's 
         * super global 
         * variable array. 
         *
         */
        if($value == $_SERVER[$data_key]){

            $clr_ssl_msg = 'SERVER match found ' . 
                           'for key [' . 
                           \strval($data_key) . 
                           '] with value [' . 
                           \strval($value) . 
                           '] Increment detection count [' . 
                           self::$env_detect_ARRAY[self::$R_data['R_cluster_id']][$env_key_hash] . 
                           '] for environment [' . \strval($env_key_hash) . 
                           ']. Need [' . \strval($required_server_matches) . 
                           '] matches to detect ' . 
                           'environment (if 0, then ' . 
                           'must process all ' . 
                           'config data).';
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_DEBUG, 
                   \E_NOTICE, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Increment for 
             * each match. 
             *
             */
            self::$env_detect_ARRAY[self::$R_data['R_cluster_id']][$env_key_hash]++;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * First $env to reach 
         * $envDetectRequiredCnt...you 
         * know you have a 
         * qualified match. 
         *
         */
        if(self::$env_detect_ARRAY[self::$R_data['R_cluster_id']][$env_key_hash] >= $required_server_matches){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * We have an environmental 
             * definition with a 
             * sufficient number of 
             * successful matches
             * to the running 
             * environment as defined 
             * by the CLR-SSL 
             * config file. 
             *
             */
            self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']] = $env_key_hash;

            $clr_ssl_msg = 'Environmental detection ' . 
                           'complete. CRNRSTN :: ' . 
                           'selected environmental ' . 
                           'profile [' . 
                           \strval($env_key_hash) . 
                           '] running with CRNRSTN :: ' . 
                           'serialization of [' . 
                           self::$R_data['R_cluster_id'] . 
                           '] and phpsession[' . 
                           session_id() . 
                           '].';
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_DEBUG, 
                   \E_NOTICE, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * CLR-SSL HTML 
             * comments mode. 
             *
             */
            switch($this->env_html_comments_mode_ARRAY[self::$R_data['R_cluster_id']][$env_key_hash]){
                /*switch($this->get_resource(
                 *              'system_html_comments_mode', 
                 *              0, 
                 *              'CRNRSTN::RESOURCE::CONFIGURATION'))
                 *{
                 *
                 */
                case CRNRSTN_HTML_COMMENTS_NONE:
                case CRNRSTN_HTML_COMMENTS_SILENT_GOLD:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * No CLR-SSL HTML 
                     * code comments should 
                     * be written. 
                     *
                     * TODO :: Remove this TODO 
                     *         when CRNRSTN :: HTML 
                     *         code comments modes 
                     *         are all implemented.
                     *
                     */
                    $this->initialize_serialized_bit(
                           'crnrstn_html_comments_mode', 
                           CRNRSTN_HTML_COMMENTS_SILENT_GOLD);

                break;
                case CRNRSTN_HTML_COMMENTS_CDN_STABILITY_CONTROL_ENABLED:
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * CLR-SSL CDN HTML 
                     * Stability Control. 
                     *
                     *
                     * When CLR-SSL CDN 
                     * HTML Stability Control 
                     * is enabled, timestamps 
                     * are removed from the 
                     * HTML code comments that
                     * accompany CLR-SSL 
                     * HTML content injections. 
                     *
                     */
                    $this->initialize_serialized_bit(
                           'crnrstn_html_comments_mode', 
                           CRNRSTN_HTML_COMMENTS_CDN_STABILITY_CONTROL_ENABLED);

                break;
                case CRNRSTN_HTML_COMMENTS_FULL:
                case CRNRSTN_HTML_COMMENTS_ENLARGED_PHYLACTERIES:
                default:
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * SILENCE IS GOLDEN.
                     *
                     *$this->initialize_serialized_bit(
                     *       'crnrstn_html_comments_mode', 
                     *       CRNRSTN_HTML_COMMENTS_ENLARGED_PHYLACTERIES);
                     *
                     */

                break;

            }

            return true;

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Evidence of a match...still 
             * not sufficient.
             *
             */
            return false;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function auth_data_input($auth_type)
    {

        switch($auth_type){
            case 'config_detection_error_help':

                if(isset($this->terminate_configuration_error_ARRAY)){

                    foreach($this->terminate_configuration_error_ARRAY as 
                        $key => $msg)
                    {

                        if(\strlen($key) > 0){

                            $this->system_terminate($auth_type);

                            exit();

                        }

                    }

                }

            break;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function is_resource(
             $data_key, 
             $data_type_family)
    {

        if(isset(self::$system_resource_profile_ARRAY[$data_key]['data_type_family'])){

            if(self::$system_resource_profile_ARRAY[$data_key]['data_type_family'] == $data_type_family){

                return self::$system_resource_profile_ARRAY[$data_key]['validation_profile'];

            }

        }

        return NULL;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function get_resource(
             $data_key, 
             $index = NULL, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $data_authorization_profile = 'R_authorize & R_channel_RUNTIME')
    {

        $env_key = NULL;

        if(is_string($data_authorization_profile) || 
            !isset($data_authorization_profile))
        {

            switch($data_authorization_profile){
                case 'R_authorize & R_channel_RUNTIME':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Convert CLR-SSL channel 
                     * data to integer. 
                     *
                     *
                     * 5 :: Monday, July 13, 2026 @ 0403 hrs.
                     *
                     */
                    $data_authorization_profile = self::$R_data['int_flag']['R_authorize'] & 
                                                  self::$R_data['int_flag']['R_channel_RUNTIME'];

                break;

            }

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Evaluate and 
         * update env_key. 
         *
         */
        $this->env_key($env_key);

        if(\strlen($env_key) > 0){

            error_log(__LINE__  . 
                ' crnrstn $data_key[' . 
                $data_key . 
                ']. $data_type_family[' . 
                $data_type_family . 
                ']. $index[' . 
                $index . 
                ']. $env_key[' . 
                $env_key . 
                ']. $data_authorization_profile[' . 
                $data_authorization_profile . 
                '].');
            $tmp_return = self::$_R['kivotos']->R['config_mgr']->retrieve_data_value(
                                                                 $data_key,
                                                                 $data_type_family,
                                                                 $index,
                                                                 $env_key,
                                                                 $data_authorization_profile);

            if($tmp_return != $this->session_salt())
                return $tmp_return;

        }

        return '';

    }

