    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function ddo_translate($channel_profile_ARRAY)
    {

        /*
        CHANNEL PROFILE ARRAY[Array
        (
            [SOURCEID] => Array
                (
                    [INTEGER] => 8070
                    [STRING] => R_channel_SOAP
                )

            [ENCRYPTION] => Array
                (
                    [PROFILE] => Array
                        (
                            [INTEGER] => 8191
                            [STRING] => R_encrypt_SOAP
                        )

                )

            [CHAR] => O
            [NAME] => soap
            [DESCRIPTION] => O :: SIMPLE OBJECT ACCESS PROTOCOL (NuSOAP 0.9.5, SOAP 1.1)
            [AUTHORIZATION] => Array
                (
                    [PROFILE] => Array
                        (
                            [PRIMARY] => Array
                                (
                                    [INTEGER] => Array
                                        (
                                            [8083] => 8083
                                        )

                                    [STRING] => Array
                                        (
                                            [R_channel_GET] => 8083
                                        )

                                )

                            [AUTHORIZED] => Array
                                (
                                    [INTEGER] => Array
                                        (
                                            [8076] => 8076
                                            [8082] => 8082
                                            [8080] => 8080
                                            [8064] => 8064
                                            [8066] => 8066
                                            [12] => 12
                                            [8] => 8
                                            [0] => 0
                                        )

                                    [STRING] => Array
                                        (
                                            [CRNRSTN_AUTHORIZE_ALL] => 8076
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP] => 8082
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_GET] => 8082
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_POST] => 8080
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_COOKIE] => 8080
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SESSION] => 8080
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_DATABASE] => 8064
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SSDTLA] => 8066
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_PSSDTLA] => 8066
                                            [CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SOAP & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_RUNTIME] => 8080
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_GET] => 12
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_POST] => 8
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_POST & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_GET] => 8
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_COOKIE] => 12
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SESSION] => 12
                                            [0] => 0
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_DATABASE] => 0
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SSDTLA] => 0
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_PSSDTLA] => 0
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_PSSDTLA & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_COOKIE] => 0
                                            [CRNRSTN_AUTHORIZE_ALL & ~CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_RUNTIME] => 8
                                        )

                                )

                        )

                )

        )
        ].

        */

        error_log('[' . 
            $this->return_micro_time() . 
            '] [lnum ' . __LINE__ . 
            '] [rtime ' . $this->wall_time() . 
            '] [mthd ' . __METHOD__ . 
            '] Starting ' . $channel_profile_ARRAY['NAME'] . 
            ' [' . $channel_profile_ARRAY['CHAR'] . 
            '] channel data translation into the ' . 
            'CRNRSTN :: DDO.');
        die();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CRNRSTN :: Lightsaber RoCEv2 
         * SOAP Services Layer (CLR-SSL) 
         * Multi-Channel Decoupled Data 
         * Object (MC-DDO) Data 
         * Translation Services Layer. 
         *
         */
        $this->destruct_output .= '<pre><code>[' . 
                                  $this->return_micro_time() . 
                                  '] [lnum ' . __LINE__ . 
                                  '] [rtime ' . $this->wall_time() . 
                                  '] [class ' . __CLASS__ . 
                                  '] Starting ' . $channel_profile_ARRAY['NAME'] . 
                                  ' [' . $channel_profile_ARRAY['CHAR'] . 
                                  '] channel data translation into the ' . 
                                  'C<span style="color:#F90000;">R</span>' . 
                                  'NRSTN :: DDO.</code></pre>';

        switch($channel_profile_ARRAY['SOURCEID'][self::$R_data['int_flag']['R_integer']]){
            case self::$R_data['int_flag']['R_channel_GET']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * G :: HTTP $_GET request.
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation.
                 *
                 * G :: HTTP $_GET request.
                 *
                 * $_GET[] data.
                 *
                 */

                $tmp_str = '';

                foreach($_GET as 
                    $attribute => $get_data)
                {

                    $tmp_str .= $get_data;
                    $this->input_data_value(
                           $get_data, 
                           $attribute, 
                           'CRNRSTN::RESOURCE::GET_CHANNEL_DATA', 
                           0, 
                           self::$R_data['int_flag']['R_channel_GET']);

                }

                /*error_log(__LINE__ . 
                 *    ' rrs map [' . $channel . 
                 *    '] ' . 
                 *    $this->get_channel_config($channel, 'NAME') . 
                 *    ' channel data initialized $channel_bytes=0.');
                 *
                 */
                self::$cache_ARRAY[self::$R_data['R_request_id']]['channel_bytes'][$channel] = $this->return_cache_bytes_size($tmp_str);

            break;
            case self::$R_data['int_flag']['R_channel_POST']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * P :: HTTP $_POST REQUEST.
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation. 
                 *
                 * $_POST[] DATA.
                 *
                 */
                $tmp_str = '';

                foreach($_POST as 
                    $attribute => $post_data)
                {

                    $tmp_str .= $post_data;

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * TODO :: Consider consuming 
                     *         post data here. 
                     *
                     *         $this->input_data_value(
                     *                $post_data, 
                     *                $attribute, 
                     *                'CRNRSTN::RESOURCE::GET_CHANNEL_DATA', 
                     *                0, 
                     *                self::$R_data['int_flag']['R_channel_POST']);
                     *
                     */

                }

                /*error_log(__LINE__ . 
                 *    ' rrs map [' . 
                 *    $channel . 
                 *    '] ' . 
                 *    $this->get_channel_config($channel, 'NAME') . 
                 *    ' channel data initialized $channel_bytes=0.');
                 *
                 */
                self::$cache_ARRAY[self::$R_data['R_request_id']]['channel_bytes'][$channel] = $this->return_cache_bytes_size($tmp_str);

            break;
            case self::$R_data['int_flag']['R_channel_COOKIE']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * C :: CARRIER PIGEON (Avian 
                 *      of Homing Variant)...or 
                 *      even a browser 
                 *      cookie...equally 
                 *      as reliable to CRNRSTN ::
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation. 
                 *
                 * $_COOKIE[] data.
                 *
                 */

                /*error_log(__LINE__ . 
                 *    ' rrs map [' . 
                 *    $channel . 
                 *    '] ' . 
                 *    $this->get_channel_config($channel, 'NAME') . 
                 *    ' channel data initialized $channel_bytes=0.');
                 *
                 */
                self::$cache_ARRAY[self::$R_data['R_request_id']]['channel_bytes'][$channel] = 0;

            break;
            case self::$R_data['int_flag']['R_channel_SESSION']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * H :: PHP SERVER SESSION 
                 *      ($_SESSION SUPER 
                 *      GLOBAL ARRAY). 
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation. 
                 *
                 * $_SESSION[] data.
                 *
                 */

                /*error_log(__LINE__ . 
                 *    ' rrs map [' . 
                 *    $channel . 
                 *    '] ' . 
                 *    $this->get_channel_config($channel, 'NAME') . 
                 *    ' channel data initialized $channel_bytes=0.');
                 *
                 */
                $_SESSION['CRNRSTN_' . self::$R_data['R_cluster_id']]['channel_bytes'][$channel] = 0;

            break;
            case self::$R_data['int_flag']['R_channel_DATABASE']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * D :: DATABASE (MySQLi 
                 *      CONNECTION). 
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation. 
                 *
                 * Database data.
                 *
                 */
            case self::$R_data['int_flag']['R_channel_SSDTLA']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * S :: CRNRSTN :: SSDTLA 
                 *      PACKET (SOAP WRAPPED 
                 *      ENCRYPTED PSSDTLA PACKET. 
                 *      THE BROWSER WILL TALK 
                 *      LIKE A SERVER).
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation. 
                 *
                 */
            case self::$R_data['int_flag']['R_channel_PSSDTLA']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * J :: CRNRSTN :: PSSDTLA 
                 *      PACKET (OPENSSL 
                 *      ENCRYPTED JSON OBJECT).
                 *
                 * CLR-SSL Multi-Channel 
                 * Decoupled Data Object (MC-DDO) 
                 * Data Translation. 
                 *
                 */
            case self::$R_data['int_flag']['R_channel_RUNTIME']:
                // R :: RUNTIME.
            case self::$R_data['int_flag']['R_channel_SOAP']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * O :: SIMPLE OBJECT 
                 *      ACCESS PROTOCOL 
                 *      (NuSOAP 0.9.5, SOAP 1.1).
                 *
                 */
            case self::$R_data['int_flag']['R_channel_FILE']:
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * F :: SERVER LOCAL 
                 *      FILE SYSTEM.
                 *
                 */

                /*error_log(__LINE__ . 
                 *    ' rrs map [' . 
                 *    $channel . '] ' . 
                 *    $this->get_channel_config($channel, 'NAME') . 
                 *    ' channel data initialized $channel_bytes=0.');
                 *
                 */
                self::$cache_ARRAY[self::$R_data['R_request_id']]['channel_bytes'][$channel] = 0;

            break;

        }

        $this->destruct_output .= '<pre><code>[' . 
                                  $this->return_micro_time() . 
                                  '] [lnum ' . __LINE__ . 
                                  '] [rtime ' . 
                                  $this->wall_time() . 
                                  '] [class ' . 
                                  __CLASS__ . 
                                  '] Completed ' . 
                                  $channel_profile_ARRAY['NAME'] . 
                                  ' [' . 
                                  $channel_profile_ARRAY['CHAR'] . 
                                  '] channel data translation.</code></pre>';

        return true;

    }

