    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function is_valid_hmac_algorithm(
             $data, 
             $data_key, 
             $data_type_family)
    {

        $tmp_is_valid = false;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Quick runtime check.
         *
         */
        if(self::$_R['kivotos']->R['env']->isset_hmac_algorithm_profile(
                                           $data_key,
                                           $data_type_family) == true)
            return true;

        $tmp_hmac_algorithm = strtolower(trim($data));

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Persist the results 
         * of this costly 
         * decision in session. 
         *
         */
        if(!$this->isset_resource(
                   'data_value', 
                   $data_key, 
                   $data_type_family, 
                   self::$R_data['int_flag']['R_channel_SESSION']) == true)
        {

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Do we need to 
             * [runtime] load 
             * the server HMAC 
             * library? 
             *
             */
            if(self::$R_data['hmac']['default'][self::$R_data['int_flag']['R_integer']] == -1){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Load available 
                 * (on the server) 
                 * HMAC hash 
                 * algorithms. 
                 *
                 */
                self::$R_data['hmac']['options']['server'] = hash_algos();

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Update the internal 
             * reference data structure 
             * per the server's available 
             * HMAC algorithms and the 
             * input data. 
             *
             * CLR-SSL UGC data 
             * validation [_hmac_lib] 
             *
             */
            foreach((array) self::$R_data['hmac']['options']['server'] as 
                $hash_index => $hash_name)
            {
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * TODO :: Is it a guarantee 
                 *         that the server hash 
                 *         name will always be 
                 *         lowercase? 
                 *
                 */

                $tmp_lower_hash = strtolower($hash_name);
                self::$R_data['hmac']['options']['ISACTIVE'][$tmp_lower_hash] = $hash_index;

                if($tmp_lower_hash == $tmp_hmac_algorithm){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Set the environment 
                     * OpenSSL HMAC 
                     * algorithm profile. 
                     *
                     */
                    self::$_R['kivotos']->R['env']->set_hmac_algorithm_profile(
                                                    $hash_name,
                                                    $data_key,
                                                    $data_type_family);

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * CRNRSTN :: Lightsaber RoCEv2 
                     * SOAP Services Layer (CLR-SSL) 
                     * Decoupled Data Object 
                     * Multi-Channel Data Storage 
                     * Services Layer. 
                     *
                     * CLR-SSL UGC data 
                     * input [_hmac_lib]
                     *
                     */
                    $tmp_output = $this->add_resource(
                                         $data_key, 
                                         $tmp_hmac_algorithm, 
                                         $data_type_family, 
                                         self::$R_data['int_flag']['R_channel_SESSION'], 
                                         0);
                    $this->add_resource(
                           $data_key . 
                           '_index', 
                           $hash_index, 
                           $data_type_family, 
                           self::$R_data['int_flag']['R_channel_SESSION'], 
                           0);

                    $tmp_is_valid = true;

                }

            }

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Session is set for this 
             * cipher by key and family, 
             * so we are valid. 
             *
             */
            return true;

        }

        return $tmp_is_valid;

    }

