    function is_valid_openssl_cipher(
             $data, 
             $data_key, 
             $data_type_family)
    {

        $tmp_is_valid = false;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Quick runtime check. 
         *
         */
        if(self::$_R['kivotos']->R['env']->isset_openssl_cipher_profile($data_key, $data_type_family) == true)
            return true;

        $tmp_cipher = strtolower(trim($data));

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Persist the results 
         * of this costly 
         * decision in session. 
         *
         */
        if(!$this->isset_resource(
                   'data_value', 
                   $data_key, 
                   $data_type_family, 
                   self::$R_data['int_flag']['R_channel_SESSION']) == true)
        {

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Do we need to 
             * [runtime] load 
             * the server OpenSSL 
             * ciphers? 
             *
             */
            if(self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['digest_method']['cipher']['default'][self::$R_data['int_flag']['R_integer']] == -1){

                if(!isset(self::$_R['kivotos']->R['env'])){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return an instantiation of
                     * The CRNRSTN :: Lightsaber 
                     * RoCEv2 SOAP Services Layer 
                     * (CLR-SSL) Server 
                     * Environment's objectification. 
                     *
                     *
                     * 5 :: Monday, July 8, 2024 @ 0611 hrs.
                     *
                     * $this->oCRNRSTN_ENV = new crnrstn_environment($this);
                     *
                     *
                    self::$_R['kivotos']->R['env'] = $this->return_registered_resource(
                                                            'new',
                                                            'crnrstn_environment');
                     */

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Initialization of the 
                     * CLR-SSL USER class object. 
                     *
                     *
                    self::$_R['kivotos']->R['usr'] = self::$_R['kivotos']->R['env']->return_ENV_oCRNRSTN_USR();
                     */

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Load available (on the server) 
                 * OpenSSL ciphers. 
                 *
                 */
                self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['cipher']['options']['server'] = self::$_R['kivotos']->R['env']->openssl_get_cipher_methods(false, false);

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Update the internal 
             * reference data structure 
             * per the server's 
             * available OpenSSL 
             * ciphers and the 
             * input data. 
             * 
             * CLR-SSL UGC data 
             * validation [_openssl_cipher_lib]
             *
             */
            foreach((array) self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['cipher']['options']['server'] 
                as $cipher_index => $cipher_name)
            {
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * TODO :: Is it a guarantee 
                 *         that the server 
                 *         hash name will 
                 *         always be lowercase? 
                 *
                 */

                $tmp_lower_hash = \strtolower($cipher_name);
                self::$R_data[self::$R_data['R_cluster_id']][self::$R_data['R_node_id']]['R_OpenSSL_config']['cipher']['options']['ISACTIVE'][$tmp_lower_hash] = $cipher_index;

                if($tmp_lower_hash == $tmp_cipher){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Set environment 
                     * OpenSSL cipher profile. 
                     *
                     */
                    self::$_R['kivotos']->R['env']->set_openssl_cipher_profile(
                                                    $cipher_name,
                                                    $data_key,
                                                    $data_type_family);

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * The CRNRSTN :: Lightsaber RoCEv2 
                     * SOAP Services Layer (CLR-SSL) 
                     * Multi-Channel Decoupled Data 
                     * Object (MC-DDO) Data Storage 
                     * Services Layer. 
                     *
                     *
                     * 5
                     *
                     * CLR-SSL UGC data 
                     * input [_openssl_cipher_lib]
                     *
                     */
                    $tmp_output = $this->add_resource(
                                         $data_key, 
                                         $cipher_name, 
                                         $data_type_family, 
                                         self::$R_data['int_flag']['R_channel_SESSION'], 
                                         0);
                    $this->add_resource(
                           $data_key . 
                           '_index', 
                           $cipher_index, 
                           $data_type_family, 
                           self::$R_data['int_flag']['R_channel_SESSION'], 
                           0);

                    $tmp_is_valid = true;

                }

            }

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Session is set for 
             * this cipher by key 
             * and family, so we 
             * are valid. 
             *
             */
            return true;

        }

        return $tmp_is_valid;

    }

