    function return_encryption_data_type_family($encryption_channel)
    {

        switch($encryption_channel){
            case 'R_encrypt_GET':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'GET_ENCRYPTION';

            break;
            case 'R_encrypt_POST':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'POST_ENCRYPTION';

            break;
            case 'R_encrypt_TUNNEL':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'TUNNEL_ENCRYPTION';

            break;
            case 'R_encrypt_DATABASE':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'DATABASE_ENCRYPTION';

            break;
            case 'R_encrypt_SESSION':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'SESSION_ENCRYPTION';

            break;
            case 'R_encrypt_COOKIE':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'COOKIE_ENCRYPTION';

            break;
            case 'R_encrypt_SOAP':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'SOAP_ENCRYPTION';

            break;
            case 'R_encrypt_OERSL':

                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'OERSL_ENCRYPTION';

            break;
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * If done consistently, 
                 * this should be ok for 
                 * graceful degredation. 
                 *
                 */
                $data_type_family = 'CRNRSTN::RESOURCE::' . 
                                    'TUNNEL_ENCRYPTION';

                $clr_ssl_msg = 'An unknown encryption ' . 
                               'channel constant has ' . 
                               'been provided to ' . 
                               __METHOD__ . 
                               '. The tunnel encryption data ' . 
                               'type family will be returned.';
                // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                             'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token = array(
                         'token'                   => $msg_token, 
                         'token_generation_date'   => $token_generation_date, 
                         'request_type'            => __METHOD__, 
                         'code'                    => 200, 
                         'clr_ssl_msg'             => $clr_ssl_msg);
                $this->error_log(
                       $clr_ssl_msg, 
                       \LOG_NOTICE, 
                       \E_NOTICE, 
                       __LINE__, 
                       __METHOD__, 
                       __FILE__, 
                       $token);

            break;

        }

        return $data_type_family;

    }

