    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function output_ssdtla_data_object($type)
    {

        switch($type){
            case 'theme_profile_data':

                $tmp_str = '';
                $tmp_cnt = 0;
                $tmp_min_mode_active = $this->is_bit_set((int) self::$R_data['int_flag']['R_js_css_min_mode']);

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * For array data 
                 * and structure, 
                 * please see:
                 * /_R/_config
                 * /_config.defaults
                 * /load_static_cache
                 * /interact_ui_theme_init
                 * /crnrstn.interact_ui_theme_init.runtime_exe.php.
                 *
                 */
                foreach($this->theme_attributes_ARRAY as 
                    $theme_constant => $theme_const_ARRAY)
                {

                    foreach($theme_const_ARRAY as 
                        $param_name => $param_value)
                    {

                        $tmp_value = $param_value;

                        if(is_array($param_value)){

                            $tmp_value = $param_value[0];

                        }

                        if($tmp_min_mode_active == true){

                            $tmp_str .= '<theme_profile_attribute><theme_position>' . 
                                        $tmp_cnt . 
                                        '</theme_position><theme_nom is_active="' . 
                                        $theme_const_ARRAY['ISACTIVE'] . 
                                        '" display_position="' . 
                                        $theme_const_ARRAY['queue_sequence'] . 
                                        '" const_str="' . 
                                        $theme_const_ARRAY[self::$R_data['int_flag']['R_string']] . 
                                        '">' . $theme_const_ARRAY['title'] . 
                                        '</theme_nom><theme_integer>' . 
                                        $theme_constant . 
                                        '</theme_integer><attribute_name><![CDATA[' . 
                                        $param_name . ']]></attribute_name>' . 
                                        '<attribute_value><![CDATA[' . 
                                        $tmp_value . ']]></attribute_value>' . 
                                        '<description><![CDATA[' . 
                                        $theme_const_ARRAY['description'] . 
                                        ']]></description></theme_profile_attribute>';

                        }else{

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Don't forget to replicate 
                             * any updates to the above. 
                             *
                             * If I get burned by this 
                             * again, we can implement 
                             * a (dev mode only) string 
                             * comparison check to apply 
                             * to all of these dev/min 
                             * versions. 
                             *
                             */
                            $tmp_str .= '<theme_profile_attribute>
                    <theme_position>' . $tmp_cnt . 
                    '</theme_position>
