    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function system_terminate($interstitial_mode = 'config_enter_config_serial_help')
    {

        $tmp_html_str_ARRAY = array();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize system 
         * defaults. 
         *
         */
        if(!isset($this->theme_attributes_ARRAY[self::$R_data['int_flag']['CRNRSTN_UI_DARKNIGHT']])){

            $this->config_load_defaults_terminal(
                   self::$R_data['int_flag']['CRNRSTN_RESOURCE_ALL'], 
                   self::$R_data['CRNRSTN_ROOT'] . 
                   '/' . 
                   self::$R_data['R_framework_directory'] .
                   '/_config/_config.defaults' . 
                   '/_crnrstn.load.inc.php');

        }

        if(!isset(self::$system_termination_flag_ARRAY[$interstitial_mode])){

            error_log(__LINE__ . 
                ' crnrstn $interstitial_mode[' . 
                $interstitial_mode . 
                ']. terminate_configuration_error_ARRAY[' . 
                print_r($this->terminate_configuration_error_ARRAY, true) . 
                '].');

            self::$system_termination_flag_ARRAY[$interstitial_mode] = 1;

            if(isset($this->terminate_configuration_error_ARRAY)){

                foreach($this->terminate_configuration_error_ARRAY as 
                    $key => $msg)
                {

                    switch($key){
                        case 'EMPTY_CONFIG_SERIAL':

                            $interstitial_mode = 'config_enter_config_serial_help';

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * $CRNRSTN_config_salt = '[n2X0@F2=?C8[-8ij5X6k*4k8XT}' . 
                             *                        'uuDQ{ZHkCr*KK5!sT%Z~cdGylAx(' . 
                             *                        '8WVYPb@N';
                             *
                             */
                            $tmp_serial = $this->salt(NULL, -2);
                            $tmp_str_in = '$CRNRSTN_config_salt = \'' . 
                                          $tmp_serial . '\';';

                            $tmp_html_str_ARRAY[] = $this->print_r_str(
                                                           $tmp_str_in, 
                                                           NULL, 
                                                           self::$R_data['int_flag']['CRNRSTN_UI_RANDOM'], 
                                                           __LINE__, 
                                                           __METHOD__, 
                                                           __FILE__);
                            $theme_profile = $this->random_theme_constant;

                            $clr_ssl_msg = 'Please specify a ' . 
                                           'configuration serial (such as ' . 
                                           '[$CRNRSTN_config_salt=\'' . 
                                           $tmp_serial . '\']) ' . 
                                           'in the CRNRSTN :: config file.';
                            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                            $token = array(
                                     'token'                   => $msg_token, 
                                     'token_generation_date'   => $token_generation_date, 
                                     'request_type'            => __METHOD__, 
                                     'code'                    => 200, 
                                     'clr_ssl_msg'             => $clr_ssl_msg);
                            $this->error_log(
                                   $clr_ssl_msg, 
                                   \LOG_ERR, 
                                   \E_ERROR, 
                                   __LINE__, 
                                   __METHOD__, 
                                   __FILE__, 
                                   $token);

                        break 2;
                        case 'FAILED_ENVIRONMENTAL_DETECTION':

                            $interstitial_mode = 'config_detection_error_help';

                            $tmp_str_in = '$oCRNRSTN->config_add_environment' . 
                                          '(\'APACHE_WOLF_PUP\', E_ALL & ' . 
                                          '~E_NOTICE & ~E_STRICT);
$oCRNRSTN->config_detect_environment(\'APACHE_WOLF_PUP\', \'SERVER_' . 
                                          'NAME\', \'' . $_SERVER['SERVER_NAME'] . '\');';

                            $tmp_html_str_ARRAY[] = $this->print_r_str(
                                                           $tmp_str_in, 
                                                           NULL, 
                                                           self::$R_data['int_flag']['CRNRSTN_UI_RANDOM'], 
                                                           __LINE__, 
                                                           __METHOD__, 
                                                           __FILE__);
                            $theme_profile = $this->random_theme_constant;

                            $clr_ssl_msg = 'To enable server ' . 
                                           'detection, please configure CRNRSTN :: ' . 
                                           'for this environment within the ' . 
                                           'configuration file.';
                            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                            $token = array(
                                     'token'                   => $msg_token, 
                                     'token_generation_date'   => $token_generation_date, 
                                     'request_type'            => __METHOD__, 
                                     'code'                    => 200, 
                                     'clr_ssl_msg'             => $clr_ssl_msg);
                            $this->error_log(
                                   $clr_ssl_msg, 
                                   \LOG_ERR, 
                                   \E_ERROR, 
                                   __LINE__, 
                                   __METHOD__, 
                                   __FILE__, 
                                   $token);

                        break 2;

                    }

                }

            }

            $INTERSTITIAL_PAGE_HTML_OUTPUT = $this->return_interstitial_page_html(
                                                    $interstitial_mode, 
                                                    $tmp_html_str_ARRAY, 
                                                    $theme_profile);
            if(\strlen($INTERSTITIAL_PAGE_HTML_OUTPUT) > 0){

                echo $INTERSTITIAL_PAGE_HTML_OUTPUT;

                if(ob_get_level() > 0){ob_flush();}
                flush();
                exit();

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Throw application 
             * error. 
             *
             */
            $this->return_server_response_code(
                   503, 
                   $this->return_CRNRSTN_ASCII_ART());

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function return_interstitial_page_html(
                     $interstitial_mode, 
                     $html_str_ARRAY = NULL, 
                     $theme_profile = 'CRNRSTN_UI_DARKNIGHT')
    {

        $tmp_str_out = '';

        if(\is_string($theme_profile)) 
            $theme_profile = self::$R_data['int_flag'][$theme_profile];

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Load interstitial 
         * HTML page string 
         * content. 
         *
         */
        switch($interstitial_mode){
            case 'config_enter_config_serial_help':

                $this->initialize_asset_management();

                include_once(self::$R_data['CRNRSTN_ROOT'] . 
                    '/' . 
                    self::$R_data['R_framework_directory'] .
                    '/ui/docs/interstitials' . 
                    '/_config_config_enter_configuration_serial_help.php');

            break;
            case 'config_detection_error_help':

                $this->initialize_asset_management();

                include_once(self::$R_data['CRNRSTN_ROOT'] . 
                    '/' . 
                    self::$R_data['R_framework_directory'] .
                    '/ui/docs/interstitials' . 
                    '/_config_config_detection_error_help.php');

            break;

        }

        return $tmp_str_out;

    }

