    {

        if(isset(self::$encryptable_data_types_ARRAY[$this->gettype($data)]))
            $this->total_bytes_encrypted += \strlen((\strval($data)));

        if(\is_string($encryption_channel)) 
            // 5 :: Sunday, July 26, 2026 @ 2155 hrs.
            $encryption_channel = self::$R_data['int_flag'][$encryption_channel];

        return self::$_R['kivotos']->R['env']->data_encrypt(
                                               $data,
