    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function get_resource_submitted(
             $input_field_name, 
             $http_transport_protocol = 'POST')
    {

        if(\is_array($http_transport_protocol))
            return '';

        $http_channel_upper = \strtoupper($http_transport_protocol);

        if($http_transport_protocol != 'POST'){

            $http_transport_protocol = $this->str_sanitize($http_channel_upper, 'http_protocol_simple');

            if($http_transport_protocol != 'GET' && 
                $http_transport_protocol != 'POST')
            {

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * HOOOSTON, VE HAFF PROBLEM!
                 * https://www.wired.com/2011/04/alt-text-spacecraft/
                 *
                 */
                throw new \Exception('CRNRSTN :: Form handling ' . 
                    'configuration error :: ' . 
                    'unable to detect ' . 
                    'transport_protocol[POST/GET] ' . 
                    'from the provided value of ' . 
                    $http_transport_protocol . '.');

            }

        }

    }

