    private function return_R_message_token_generation_XML()
    {
        // 5 :: Saturday, August 1, 2026 @ 0109 hrs.

        $msg_token = $this->generate_key('system_message_token');
        $ts        = $this->return_query_date_time_stamp();
        header('Content-Type: application/xml');

        echo '<?xml version="1.0" encoding="iso-8859-1" ?>
        <token>
            <data>' . $msg_token . '</data>
            <timestamp>[' . $ts . '] [rtime ' .
            $this->wall_time() .
            ' secs] [session_rtime ' .
                $this->session_runtime(self::$R_data['int_flag']['R_string']) .
                ' secs]</timestamp>
        </token>';

        $clr_ssl_msg = 'CLR-SSL Advanced Logging ' .
                       'Services Layer system message token: ' .
                       \strval($msg_token) . ' [len=' .
                       \strlen($msg_token) . '].';
        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' .
                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token = array(
                 'token'                   => $msg_token,
                 'token_generation_date'   => $token_generation_date,
                 'request_type'            => __METHOD__,
                 'code'                    => 200,
                 'clr_ssl_msg'             => $clr_ssl_msg);
        $this->error_log(
            $clr_ssl_msg,
            \LOG_DEBUG,
            \E_NOTICE,
            __LINE__,
            __METHOD__,
            __FILE__,
            $token);

        $clr_ssl_msg = 'CLR-SSL Advanced Logging ' .
                       'Services Layer message ' .
                       'token generation date: [' .
                       $ts .
                       '].';
        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' .
                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token = array(
                 'token'                   => $msg_token,
                 'token_generation_date'   => $token_generation_date,
                 'request_type'            => __METHOD__,
                 'code'                    => 200,
                 'clr_ssl_msg'             => $clr_ssl_msg);
        $this->error_log(
            $clr_ssl_msg,
            \LOG_DEBUG,
            \E_NOTICE,
            __LINE__,
            __METHOD__,
            __FILE__,
