             */

            $tmp_footer_html_output .= $this->ui_content_module_out(self::$R_data['int_flag']['CRNRSTN_WEB_ANALYTICS']);

            /*error_log(__LINE__ . 
             *    ' crnrstn LOAD ' . 
             *    'FOOTER CRNRSTN_WEB_ANALYTICS[' . 
             *    $tmp_footer_html_output . 
             *    '].');
             *
             */

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * CRNRSTN :: 3rd Party 
             * Engagement Integrations. 
             *
             * Load any DOM <HTML> 
             * content injections from 
             * CLR-SSL configuration.
             *
             * See, /_R/_config
             * /config.seo_engagement.secure
             * /_crnrstn.engagement.inc.php
             *
             *if($this->is_bit_set(CRNRSTN_WEB_ENGAGEMENT)){
             *
             */

            /*error_log(__LINE__ . 
             *    ' crnrstn LOAD ' . 
             *    'FOOTER CRNRSTN_WEB_ENGAGEMENT.');
             *
             */
            $tmp_footer_html_output .= $this->ui_content_module_out(self::$R_data['int_flag']['CRNRSTN_WEB_ENGAGEMENT']);

            //}

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Process CRNRSTN_JS_MAIN 
             * dependencies CRNRSTN :: 
             * INTERACT UI :: JS 
             *
             */
            if(isset($this->html_head_build_flag_ARRAY[self::$R_data['int_flag']['CRNRSTN_JS_MAIN']])){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: INTERACT 
                 * UI :: CSS
                 *
                 */
                if(!isset($this->html_head_build_flag_ARRAY[self::$R_data['int_flag']['CRNRSTN_CSS_MAIN_DESKTOP']]) && 
                    !isset($this->html_head_build_flag_ARRAY[self::$R_data['int_flag']['CRNRSTN_CSS_MAIN_TABLET']]) && 
                    !isset($this->html_head_build_flag_ARRAY[self::$R_data['int_flag']['CRNRSTN_CSS_MAIN_MOBILE']]))
                {

                    $tmp_device_bit = $this->device_type_bit();
                    $this->html_head_build_flag_ARRAY[$tmp_device_bit] = 1;
                    $tmp_footer_html_output .= self::$_R['kivotos']->R['asset_mgr']->return_html_head_asset(
                                                                                     $tmp_device_bit,
                                                                                     false,
                                                                                     $tmp_framework_is_dev_mode);

                }

                if(!isset($this->html_footer_build_flag_ARRAY[self::$R_data['int_flag']['R_soap_tunnel']])){

                    $this->html_footer_build_flag_ARRAY[self::$R_data['int_flag']['R_soap_tunnel']] = 1;
                    $tmp_footer_html_output .= $this->ui_content_module_out(self::$R_data['int_flag']['R_soap_tunnel']);

                }

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Deep link 
             * support. 
             *
             */
            if($this->is_bit_set(self::$R_data['int_flag']['CRNRSTN_RESOURCE_DEEP_LINK']) == true){

                $tmp_footer_html_output .= $this->ui_content_module_out(self::$R_data['int_flag']['CRNRSTN_RESOURCE_DEEP_LINK']);

            }

            if(isset($this->html_footer_build_flag_ARRAY[self::$R_data['int_flag']['CRNRSTN_RESPONSE_REPORT']])){

                $tmp_footer_html_output .= '
<!-- ' . $this->ui_content_module_out(self::$R_data['int_flag']['CRNRSTN_RESPONSE_REPORT'], 'TEXT') . 
'-->
';

            }

            return $tmp_footer_html_output;

        }catch(\Exception $e){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Exception handling performed 
             * by the Logging Services Layer 
             * of the CRNRSTN :: Lightsaber 
             * RoCEv2 SOAP Services 
             * Layer (CLR-SSL). 
             *
             * Allow the CLR-SSL to handle 
             * this exception per the 
             * configured logging profile of 
             * the running application on 
             * this server. 
             *
             *
             * 5
             *
             * Sunday, June 30, 2024 @ 1534 hrs.
             * Last Modified: Friday, February 27, 2026 @ 0233 hrs.
             *
             */
            $this->catch_exception(
                   $e, 
                   \LOG_ERR, 
                   __METHOD__, 
                   __NAMESPACE__);

            return false;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    private function return_html_meta()
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * TODO :: Make this weak <meta> 
         *         "use-case toggle" between 
         *         html_head_meta & 
         *         html_head_crnrstn_meta 
         *         stronger.
         *
         */
        $tmp_str    = '';
        $tmp_source = 'CRNRSTN';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Get system default 
         * data auth profile. 
         * priority #1.
         *
         */
        $index        = 0;
        $tmp_meta_cnt = $this->get_resource_count(
                               'HTML_HEAD_META', 
                               'CRNRSTN::RESOURCE::GENERAL_SETTINGS::META');

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Check for non-crnrstn :: 
         * meta. [HTML_HEAD_META]
         *
         */
        if($tmp_meta_cnt > 0){

            $tmp_source = 'CUSTOM';

        }

        $tmp_str = '
    ' . $this->html_version_burn('HTML META MODULE');

        //$tmp_module_page_key = self::$_R['kivotos']->R['dtsm']->return_received_data('crnrstn_interact_ui_link_text_click');

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Only load 
         * CRNRSTN meta 
         * for CRNRSTN :: 
         *
         *if(strlen($tmp_module_page_key) > 0 || 
         *  $this->crnrstn_asset_family == 'module_key')
         *{
         *
         */
        $tmp_request_family = $this->return_crnrstn_asset_family();

        if($tmp_request_family == 'module_key' || 
            $tmp_request_family == 'meta')
        {

            $tmp_source = 'CRNRSTN';

        }

        /*error_log(__LINE__ . 
         *    ' crnrstn crnrstn_asset_family[' . 
         *    $this->crnrstn_asset_family . 
         *    ']. $tmp_source[' . 
         *    $tmp_source . 
         *    ']. ssdtla_enabled[' . 
         *    print_r($this->ssdtla_enabled,true) . 
         *    '].');
         *
         */

        switch($tmp_source){
            case 'CRNRSTN':

                $tmp_meta_cnt = $this->get_resource_count(
                                       'HTML_HEAD_CRNRSTN_META', 
                                       'CRNRSTN::RESOURCE::GENERAL_SETTINGS::META');
                $tmp_meta_cnt_last = $tmp_meta_cnt - 1;

                /*error_log(__LINE__ . 
                 *    ' crnrstn $tmp_meta_cnt[' . 
                 *    $tmp_meta_cnt . 
                 *    ']. crnrstn_request_ugc_val[' . 
                 *    $this->crnrstn_request_ugc_val . 
                 *    ']. crnrstn_asset_meta_key[' . 
                 *    $this->crnrstn_asset_meta_key . 
                 *    '].');
                 *
                 */
                $tmp_str .= '
    ';
                for($i = 0; $i < $tmp_meta_cnt; $i++){

                    $tmp_data = $this->get_resource(
                                       'HTML_HEAD_CRNRSTN_META', 
                                       $i, 
                                       'CRNRSTN::RESOURCE::GENERAL_SETTINGS::META');
                    if(is_array($tmp_data)){

                        $tmp_cnt = sizeof($tmp_data);
                        for($ii = 0; $ii < $tmp_cnt; $ii++){

                            if($ii == 0){

                                $tmp_str .= $tmp_data[$ii] . '
    ';

                            }else{

                                $tmp_str .= $tmp_data[$ii] . '
    ';

                            }

                        }

                    }else{

                        if($i == 0){

                            $tmp_str .= $tmp_data . '
    ';

                        }else{

                            if($i == $tmp_meta_cnt_last){

                                $tmp_str .= $tmp_data;

                            }else{

                                $tmp_str .= $tmp_data . '
    ';

                            }

                        }

                    }

                }

                $tmp_str .= $this->html_version_burn(
                                   'HTML META MODULE', 
                                   'END') . '
';

            break;
            default:

                /*$tmp_meta_cnt = $this->get_resource_count(
                 *                       'HTML_HEAD_META', 
                 *                       'CRNRSTN::RESOURCE::GENERAL_SETTINGS::META');
                 *error_log(__LINE__ . 
                 *    ' crnrstn $tmp_meta_cnt[' . 
                 *    $tmp_meta_cnt . 
                 *    '].');
                 *
                 */
                $tmp_str .= '
    ';
                for($i = 0; $i < $tmp_meta_cnt; $i++){

                    /*error_log(__LINE__ . 
                     *    ' crnrstn $i[' . 
                     *    $i . 
                     *    ']. $tmp_meta_cnt[' . 
                     *    $tmp_meta_cnt . 
                     *    '].');
                     *
                     */

                    $tmp_data = $this->get_resource(
                                       'HTML_HEAD_META', 
                                       $i, 
                                       'CRNRSTN::RESOURCE::GENERAL_SETTINGS::META');

                    if(\is_array($tmp_data)){

                        $tmp_cnt = sizeof($tmp_data);
                        for($ii = 0; $ii < $tmp_cnt; $ii++)
                            /*error_log(__LINE__ . 
                             *    ' crnrstn ii[' . 
                             *    $ii . 
                             *    ']. $tmp_cnt[' . 
                             *    $tmp_cnt . 
                             *    ']. $tmp_data[' . 
                             *    $tmp_data[$ii] . 
                             *    ']');
                             *
                             */
                            $tmp_str .= $tmp_data[$ii] . '
    ';

                    }else{

                        /*error_log(__LINE__ . 
                         *    ' crnrstn HTML_HEAD_META i[' . 
                         *    $i . 
                         *    ']. $tmp_meta_cnt[' . 
                         *    $tmp_meta_cnt . 
                         *    ']. $tmp_data[' . 
                         *    $tmp_data . 
                         *    ']');
                         *
                         */
                        $tmp_str .= $tmp_data . '
    ';

                    }

                }

/*                    $tmp_str .= $this->html_version_burn('HTML META MODULE', 'END') . '
 *';
 *
 */

            break;

        }

        $tmp_str .= $this->html_version_burn('HTML META MODULE', 'END') . '
';
        $this->add_resource(
               'HTML_OUTPUT', 
               $tmp_str, 
               'CRNRSTN::RESOURCE::GENERAL_SETTINGS::META');

        return $tmp_str;

    }

