    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function dom_iframe_proxy()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Added return_dom_proxy_iframe() method 
         * to the CLR-SSL to hold index.php 
         * executing code, and removed 
         * _crnrstn_hash() and _crnrstn_generate_new_key() 
         * resource dependencies from the 
         * new method. 
         *
         *
         * 5
         *
         * Monday, March 9, 2026 @ 0042 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed the return_dom_proxy_iframe() 
         *       method to dom_iframe_proxy(). 
         *       5 :: Saturday, August 1, 2026 @ 0057 hrs.
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CRNRSTN :: Lightsaber RoCEv2
         * SOAP Services Layer (CLR-SSL) 
         * Boot-Up.
         *
         * Prepare all necessary
         * directory endpoints for
         * a full demonstration of
         * how to successfully
         * boot-up the framework.
         *
         *
         * 5
         *
         * Sunday, September 1, 2024 @ 0155 hrs.
         * 
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added same domain http URL 
         *       for CLR-SSL Iframe 
         *       proxy endpoint, $tmp_dom_iframe_http. 
         *       5 :: Thursday, February 12, 2026 @ "010101 split the atom" 2345 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed $tmp_dom_iframe_http.
         *       to
         *       $R_iframe_endpoint.
         *       5 :: Saturday, August 1, 2026 @ 0209 hrs.
         *
         */
        $R_iframe_endpoint = self::$R_data['R_paths']['HTTPS']['APPLICATION']['uri'] .
                             self::$R_data['R_framework_directory'] . '/' .
                             'ui' . '/' .
                             'iframe' . '/';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Generate a key or token 
         * for the CRNRSTN :: 
         * Lightsaber RoCEv2 SOAP 
         * Services Layer (CLR-SSL) 
         * DOM Proxy Iframe. 
         * 
         * 
         * 5 :: Thursday, February 12, 2026 @ 2305 hrs.
         * 
         */
        $dom_proxy_id = $this->generate_key('dom_proxy_id');

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Build an endpoint 
         * for the CRNRSTN :: 
         * Lightsaber RoCEv2 
         * SOAP Services Layer 
         * Iframe proxy
         * on this page.
         * 
         *
         * 5 :: Thursday, February 12, 2026 @ 2326 hrs.
         *
         */
        $R_iframe_endpoint = $R_iframe_endpoint .
                             '?crnrstn_iframe=' .
                             $dom_proxy_id;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize the 
         * CRNRSTN :: Lightsaber 
         * RoCEv2 SOAP Services 
         * Layer (CLR-SSL) DOM 
         * Iframe Framework 
         * Proxy. 
         *
         * When, 
         * $resource_name = 'crnrstn_dom_proxy_iframe'
         * 
         * _crnrstn_registry_boot 
         * returns IFRAME HTML like:
         *
         * <script>
         *  window.addEventListener('message', function(event) {
         *     alert("Message received from the child: " + event.data); // Message received from child
         *  });
         * </script>
         * <iframe 
         *   style="width: 0; height: 0; border: 0; 
         *          padding: 0; margin: 0; 
         *          overflow: hidden; 
         *          background-color: transparent;"
         *   id="crnrstn_dom_proxy_9bded98fdce9da88cf8da24cabcf91ed98c4402933c253cbdb0db9a6624a29a7"
         *   title="CRNRSTN :: Lightsaber RoCEv2 SOAP Services Layer (CLR-SSL)"
         *   width="0"
         *   height="0"
         *   src="./_R/ui/iframe/?crnrstn_iframe=9bded98fdce9da88cf8da24cabcf91ed98c4402933c253cbdb0db9a6624a29a7"
         * >
         * </iframe>
         *
         *
         * 5 ::
         *
         * Thursday, February 12, 2026 @ 2247 hrs.
         *
         *
         * echo _crnrstn_registry_boot($application_directory, '_crnrstn', 'crnrstn_dom_proxy_iframe');
         *
         */
        return '    <div id="crnrstn_ui_proxy_' . 
      $dom_proxy_id . '"></div><script>
      window.addEventListener(\'message\', function(event) {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Message received from child
         * alert("Message received from the child: " + 
         *    event.data); 
         *
         */

      });
    </script>
    <iframe 
      style="width: 0; height: 0; border: 0; 
             padding: 0; margin: 0; 
             overflow: hidden; 
             background-color: transparent;"
      id="crnrstn_dom_proxy_' . 
      $dom_proxy_id . '"
      title="CRNRSTN :: Lightsaber RoCEv2 SOAP Services Layer (CLR-SSL)"
      width="0"
      height="0"
      src="' . $R_iframe_endpoint . '">
    </iframe>';

    }

    /**
     * R :: SOAP Data Tunnel Layer form integrations packet generation with fresh content checksums.
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_crnrstn_data_packet($packet_type = 'R_channel_RUNTIME')
    {

        if(is_string($packet_type))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Convert CLR-SSL channel data to integer. 
             *
             *
             * 5 :: Monday, July 13, 2026 @ 0218 hrs.
             *
             */
            $packet_type = self::$R_data['int_flag'][$packet_type];

        switch($packet_type){
            case self::$R_data['int_flag']['R_channel_SSDTLA']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOAP encapsulation of 
                 * the PSSDTLP has not 
                 * yet been implemented.
                 *
                 */
                return $this->session_salt();

            break;
            case self::$R_data['int_flag']['R_channel_PSSDTLA']:
            default:

                return $this->data_encrypt(self::$_R['kivotos']->R['ui_trm']->return_crnrstn_data_packet_json($packet_type));

            break;

        }

    }

