    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_module_content_seo_analytics($data_key = NULL)
    {

        $tmp_str_out = '';
        $data_type_family = 'CRNRSTN::RESOURCE::SEO_ANALYTICS';

        if(isset($data_key)){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Return a 
             * specific profile. 
             *
             */
            return $this->get_resource($data_key, 0, $data_type_family);

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Return all 
         * enabled profiles.
         *
         */
        $tmp_profile_key = 'CRNRSTN::SYSTEM::ANALYTICS';
        $tmp_profile_cnt = self::$_R['kivotos']->R['config_mgr']->system_profile_return_count($tmp_profile_key);

        /*error_log(__LINE__ . 
         *    ' crnrstn ANALYTICS $tmp_profile_cnt=[' . 
         *    $tmp_profile_cnt . 
         *    '].');
         *
         */

        for($i = 0; $i < $tmp_profile_cnt; $i++){

            $tmp_data_key = self::$_R['kivotos']->R['config_mgr']->system_profile_return_data_key($tmp_profile_key, $i);

            $tmp_str_out .= $this->get_resource($tmp_data_key, 0, $data_type_family);
            /*error_log(__LINE__ . 
             *    ' crnrstn $tmp_str_out=[' . 
             *    $tmp_str_out . 
             *    '].');
             *
             */

        }

        return $tmp_str_out;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_module_content_seo_engagement($data_key = NULL)
    {

        $tmp_str_out      = '';
        $data_type_family = 'CRNRSTN::RESOURCE::SEO_ENGAGEMENT';

        if(isset($data_key))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Return a 
             * specific profile. 
             *
             */
            return $this->get_resource(
                          $data_key, 
                          0, 
                          $data_type_family);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Return all 
         * enabled profiles. 
         *
         */
        $tmp_profile_key = 'CRNRSTN::SYSTEM::ENGAGEMENT';
        $tmp_profile_cnt = self::$_R['kivotos']->R['config_mgr']->system_profile_return_count($tmp_profile_key);

        /*error_log(__LINE__ . 
         *    ' crnrstn PRE-EXISTING ARCH-> $tmp_profile_cnt=[' . 
         *    $tmp_profile_cnt . 
         *    '].');
         *
         */

        for($i = 0; $i < $tmp_profile_cnt; $i++){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * TODO :: Package this nifty 
             *         little section to return 
             *         grouped "families" of DDO 
             *         configuration data. 
             *
             * Lol! [This pre-lightsaber todo above^]
             * Like 20min ago, I was just 
             * sitting here and 
             * staring...thinking about 
             * doing this very thing
             * when having to reconnect 
             * engagement and analytics 
             * to Lightsaber.
             *
             *
             * 5 :: Sunday, Jun 14, 2023 @ 1649 hrs.
             *
             * $oCRNRSTN->return_family('CRNRSTN::SYSTEM::ENGAGEMENT');
             * $oCRNRSTN->return_family('CRNRSTN::SYSTEM::*');                  // Some kind of star notation.
             * $oCRNRSTN->return_family('"::ENGAGEMENT"', $search_algo = true); // ...or even more hip... w/ "case-sensitive literals"
             *
             *
             * 5 :: Tuesday, May 23, 2023 @ 2303 hrs.
             *
             */
            $tmp_data_key = self::$_R['kivotos']->R['config_mgr']->system_profile_return_data_key($tmp_profile_key, $i);

            /*error_log(__LINE__ . 
             *    ' crnrstn PRE-EXISTING ARCH-> $tmp_data_key[' . 
             *    $tmp_data_key . 
             *   ']. [' . 
             *   $i . 
             *   ']');
             *
             */

            $tmp_str_out .= $this->get_resource($tmp_data_key, 0, $data_type_family);
            /*error_log(__LINE__ . 
             *    ' crnrstn $tmp_str_out=[' . 
