    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function config_integrate_file_system(
             $env_key, 
             $http_path, 
             $dir_path = NULL, 
             $data_authorization_profile = 'R_authorize & R_channel_RUNTIME', 
             $ttl = 60, 
             $host = 'localhost', 
             $excluded_file_ext_ARRAY = NULL)
    {

        if(!isset($dir_path))
            $dir_path = self::$R_data['CRNRSTN_ROOT'];

        if(\is_string($data_authorization_profile)){

            switch($data_authorization_profile){
                case 'R_authorize & R_channel_RUNTIME':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Convert CLR-SSL channel 
                     * data to integer. 
                     *
                     *
                     * 5 :: Monday, July 13, 2026 @ 0219 hrs.
                     *
                     */
                    $data_authorization_profile = self::$R_data['int_flag']['R_authorize'] & 
                                                  self::$R_data['int_flag']['R_channel_RUNTIME'];

                break;

            }

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Did the CRNRSTN :: Lightsaber 
         * RoCEv2 SOAP Services Layer 
         * (CLR-SSL) receive UGC 
         * configuration input data that 
         * is assigned to the currently 
         * detected environment? 
         *
         * If not, run a bypass here in 
         * order to receive a minor 
         * performance acceleration boost. 
         *
         */
        if($this->config_is_valid_detected_env($env_key) == true){

            self::$_R['kivotos']->R['env']->config_integrate_file_system(
                                            $env_key,
                                            $http_path,
                                            $dir_path,
                                            $data_authorization_profile,
                                            $ttl,
                                            $host,
                                            $excluded_file_ext_ARRAY);

        }

    }

