    function return_env_key($output_hash = false)
    {
        // 5 :: Thursday, November 2, 2023 @ 0541 hrs.

        //if(isset(self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']])){
        if(isset(self::$env_key_config_ARRAY[self::$R_data['R_cluster_id']])){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Now low level for 
             * administrative support. 
             *
             *
             * 5 :: Tuesday, November 7, 2023 @ 0404 hrs.
             *
             */
            if($output_hash !== false){

                return self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']];

            }

            return self::$env_key_config_ARRAY[self::$R_data['R_cluster_id']][self::$env_key_hash_config_ARRAY[self::$R_data['R_cluster_id']]];

        }

        return '';

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_timezone_syntax_array($output_type = 'ARRAY')
    {

        $timezone_syntax_ARRAY = DateTimeZone::listIdentifiers();

        switch($output_type){
            case 'array_string':

                $tmp_str = '';
                foreach($timezone_syntax_ARRAY as 
                    $index => $timezone)
                {

                    $tmp_str .= '\'' . 
                                $timezone . '\' => \'' . 
                                $timezone . '\', ';

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Remove trailing 
                 * comma. 
                 *
                 */
                $tmp_str = $this->strrtrim($tmp_str, ',');

                return $tmp_str;

            break;
            case 'array_string_lower':

                $tmp_str = '';
                foreach($timezone_syntax_ARRAY as 
                    $index => $timezone)
                {

                    $timezone = strtolower($timezone);
                    $tmp_str .= '\'' . 
                                $timezone .'\' => \'' . 
                                $timezone . '\', ';

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Remove trailing 
                 * comma. 
                 *
                 */
                $tmp_str = $this->strrtrim($tmp_str, ',');

                return $tmp_str;

            break;
            case 'array_string_upper':

                $tmp_str = '';
                foreach($timezone_syntax_ARRAY as 
                    $index => $timezone)
                {

                    $timezone = strtoupper($timezone);
                    $tmp_str .= '\'' . 
                                $timezone . '\' => \'' . 
                                $timezone . '\', ';

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Remove trailing 
                 * comma. 
                 *
                 */
                $tmp_str = $this->strrtrim($tmp_str, ',');

                return $tmp_str;

            break;
            default:
                //ARRAY.

                return $timezone_syntax_ARRAY;

            break;

        }

    }

