    /**
     * R :: Returns the time in seconds with microseconds.
     * 
     * SOURCE :: NuSOAP.PHP - http://sourceforge.net/projects/nusoap/
     *
     * @return string The time in seconds
     *                with microseconds
     * @access public
     *
     */
    function microtime_float()
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * SOURCE :: http://www.php.net/manual/en/function.microtime.php
         * microtime_float(){
         * list($usec, $sec) = explode(' ', microtime());
         * return ((float) $usec + (float) $sec);
         * }
         *
         */

        if(function_exists('gettimeofday')){

            $tod = \gettimeofday();
            $sec = $tod['sec'];
            $usec = $tod['usec'];

        }else{

            $sec = time();
            $usec = 0;

        }

        return $sec . '.' . \sprintf('%06d', $usec);

    }

    /**
     * R :: Returns the time in ODBC canonical form with microseconds.
     *
     * @return string The time in 
     *                ODBC canonical 
     *                form with microseconds,  
     *                e.g., '2024-07-15 00:56:13.653016'.
     * @access public
     *
     * SOURCE :: NUSOAP.PHP - http://sourceforge.net/projects/nusoap/
     * This method ws copied 
     * from NuSOAP.PHP
     *
     */
    function return_micro_time()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * getmicrotime() method copied 
         * to crnrstn from crnrstn_logging
         * and renamed to return_micro_time().
         * 5 :: Tuesday, April 7, 2026 @ 1048 hrs.
         *
         */

        if(function_exists('gettimeofday')){

            $tod = \gettimeofday();
            $sec = $tod['sec'];
            $usec = $tod['usec'];

        }else{

            $sec = time();
            $usec = 0;

        }

        return \strftime('%Y-%m-%d %H:%M:%S', $sec) . '.' . 
               \sprintf('%06d', $usec);

    }

