     */
    function elapsed_from_current($secs)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Refactored 
         *       crnrstn->elapsed_from_current() 
         *       method visibility from private 
         *       to public. 
         *       5 :: Monday, May 25, 2026 @ 0411 hrs.
         */

        $clr_ssl_msg = 'DEPRECATED method call (' . 
                       __METHOD__ . ')' . 
                       'received. Put this ' . 
                       'behind the R_finite_expression ' . 
                       'unit measure of time services layer.';
        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token = array(
                 'token'                   => $msg_token, 
                 'token_generation_date'   => $token_generation_date, 
                 'request_type'            => __METHOD__, 
                 'code'                    => 200, 
                 'clr_ssl_msg'             => $clr_ssl_msg);
        $this->error_log(
               $clr_ssl_msg, 
               \LOG_NOTICE, 
               \E_NOTICE, 
               __LINE__, 
               __METHOD__, 
               __FILE__, 
               $token);

        $ts = time();
        $delta_secs = $ts - $secs;

        $bit = array(
            self::$lang_struct_time['Y'] => $delta_secs / 31556926 % 12,
            self::$lang_struct_time['W'] => $delta_secs / 604800 % 52,
            self::$lang_struct_time['D'] => $delta_secs / 86400 % 7,
            self::$lang_struct_time['H'] => $delta_secs / 3600 % 24,
            self::$lang_struct_time['M'] => $delta_secs / 60 % 60,
            self::$lang_struct_time['S'] => $delta_secs % 60
        );

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Let's drive this 
         * language operation 
         * via the CLR-SSL 
         * multi-language 
         * configuration. 
         *
         * error_log('(146) Y->' . 
         *     self::$lang_struct_time['Y']); // shows 1...not y...
         *
         */

        foreach($bit as 
            $k => $v)
        {

            if($v > 0){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Put in curfew 
                 * for time granularity. 
                 *
                 */
                if($k == self::$lang_struct_time['Y'] ||
                    $k == self::$lang_struct_time['W'] ||
                    ($k == self::$lang_struct_time['D'] &&
                        $v > 1))
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return the 
                     * default date format. 
                     *
                     */
                    if(isset($format_override))
                        return \date($format_override, $secs);
                    else
                        return \date('m.d.Y @ H:i:s', $secs);
                else
                    $ret[] = $v . $k;

            }

        }

        if(!isset($ret))
            $ret[] = 'just now.';
        else
            if(sizeof($ret) == 0)
                $ret[] = 'just now.';
            else
                $ret[] = self::$lang_struct_time['AGO'];

        return \join(' ', $ret);

    }

