                              -3);

            break;
            case 'resource_registry_request_serial':
                // 5 :: Thursday, April 30, 2026 @ 1451 hrs.

                return $this->generate_new_key(
                              64, 
                              -5);

            break;
            case 'cache_bust':
                // 5 :: Thursday, April 30, 2026 @ 1451 hrs.

                return $this->generate_new_key(
