    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function catch_exception(
             $exception_obj, 
             $syslog_level = \LOG_DEBUG, 
             $method = NULL, 
             $namespace = __NAMESPACE__, 
             $output_profile = NULL, 
             $output_profile_override_meta = NULL, 
             $wcr_override_pipe = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Changed crnrstn->catch_exception 
         *       $syslog_constant input parameter 
         *       to $syslog_level. 
         *       5 :: Friday, May 1, 2026 @ 0054 hrs.
         *
         */

        $tmp_err_trace_str = $this->return_PHP_exception_trace_pretty($exception_obj->getTraceAsString());

        if(\strlen($tmp_err_trace_str) > 0){

            /*
            $clr_ssl_msg = 'PHP native exception ' . 
                           'output log trace ' . 
                           'received ::' . 
                           $tmp_err_trace_str;
             */
            $clr_ssl_msg = $tmp_err_trace_str;
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_ALERT, 
                   \E_ERROR, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token);

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Exception handling performed 
         * by the Logging Services Layer 
         * of the CRNRSTN :: Lightsaber 
         * RoCEv2 SOAP Services 
         * Layer (CLR-SSL). 
         *
         * Allow the CLR-SSL to handle 
         * this exception per the 
         * configured logging profile of 
         * the running application on 
         * this server. 
         *
         *
         * 5
         *
         * Last Modified: Friday, February 27, 2026 @ 0233 hrs.
         *
         */
        self::$_R['kivotos']->R['logging']->catch_exception(
                                            $exception_obj,
                                            $syslog_level,
                                            $method,
                                            $namespace,
                                            $output_profile,
                                            $output_profile_override_meta,
                                            $wcr_override_pipe);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_clean_json_string($val)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * https://www.php.net/manual/en/json.constants.php
         *
         * JSON_OBJECT_AS_ARRAY (int)
         * Decodes JSON objects as PHP array. 
         * This option can be added 
         * automatically by calling
         * json_decode() with the second 
         * parameter equal to true.
         *
         * json_encode('', JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_NUMERIC_CHECK);
         *
         * JSON_UNESCAPED_UNICODE
         * Encode multibyte Unicode 
         * characters literally (default 
         * is to escape as \uXXXX).
         *
         * JSON_UNESCAPED_SLASHES
         * Don't escape /.
         *
         * JSON_NUMERIC_CHECK
         * Encodes numeric strings as numbers.
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * SOURCE :: https://www.php.net/manual/en/json.constants.php
         * AUTHOR :: majid4466 at gmail dot com :: https://www.php.net/manual/en/json.constants.php#119565
         *
         */
        $val = json_encode(
                     $val, 
                     \JSON_UNESCAPED_UNICODE | 
                     \JSON_UNESCAPED_SLASHES | 
                     \JSON_NUMERIC_CHECK);

        return $val;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_PHP_exception_trace_pretty(
             $exception_obj_trace_str, 
             $format = 'ERROR_LOG')
    {

        switch($format){
            case 'HTML':

                $exception_obj_trace_str = $this->proper_replace(
                                                  '\n', 
                                                  '<br>', 
                                                  $exception_obj_trace_str);
                $exception_obj_trace_str = $this->proper_replace('
', '<br>', $exception_obj_trace_str);

            break;
            case 'TEXT':

                $exception_obj_trace_str = $this->proper_replace('\n', '
', $exception_obj_trace_str);

            break;
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Do nothing.
                 *
                 * Straight unprocessed 
                 * PHP native out. 
                 *
                 */

            break;

        }

        return $exception_obj_trace_str;

    }

