    {

        $tmp_output_format = trim(strtoupper($format));

        if($tmp_output_format == 'HTML'){

            //<span>LOG_EMERG</span><span>:: system is unusable.</span>

            /*
            Each message Priority also has a decimal Severity level indicator.
            These are described in the following table along with their numerical
            values.

            Numerical         Severity
              Code

               0       Emergency: system is unusable
               1       Alert: action must be taken immediately
               2       Critical: critical conditions
               3       Error: error conditions
               4       Warning: warning conditions
               5       Notice: normal but significant condition
               6       Informational: informational messages
               7       Debug: debug-level messages

               Table 2. syslog Message Severities


            Source: https://www.php.net/manual/en/function.syslog.php
            Source: https://datatracker.ietf.org/doc/html/rfc3164
            5 :: Thursday, April 30, 2026 @ 1539 hrs.

             */
            switch($log_priority){
                case 0:
                case \LOG_EMERG:

                    $tmp_priority_const = 'LOG_EMERG';
                    $tmp_priority_msg   = ':: Emergency. System ' . 
                                          'is unusable.';

                break;
                case 1:
                case \LOG_ALERT:

                    $tmp_priority_const = 'LOG_ALERT';
                    $tmp_priority_msg   = ':: Alert. Action must be ' . 
                                          'taken immediately.';

                break;
                case 2:
                case \LOG_CRIT:

                    $tmp_priority_const = 'LOG_CRIT';
                    $tmp_priority_msg   = ':: Critical ' . 
                                          'conditions encountered.';

                break;
                case 3:
                case \LOG_ERR:

                    $tmp_priority_const = 'LOG_ERR';
                    $tmp_priority_msg   = ':: Error ' . 
                                          'conditions encountered.';

                break;
                case 4:
                case \LOG_WARNING:

                    $tmp_priority_const = 'LOG_WARNING';
                    $tmp_priority_msg   = ':: Warning ' . 
                                          'conditions encountered.';

                break;
                case 5:
                case \LOG_NOTICE:

                    $tmp_priority_const = 'LOG_NOTICE';
                    $tmp_priority_msg   = ':: Notice. Normal, ' . 
                                          'but significant, ' . 
                                          'condition encountered.';

                break;
                case 6:
                case \LOG_INFO:

                    $tmp_priority_const = 'LOG_INFO';
                    $tmp_priority_msg   = ':: Informational ' . 
                                          'message. ';

                break;
                case 7:
                case \LOG_DEBUG:

                    $tmp_priority_const = 'LOG_DEBUG';
                    $tmp_priority_msg   = ':: Debug-level ' . 
                                          'message. ';

                break;
                default:

                    $tmp_priority_const = 'UNKNOWN';
                    $tmp_priority_msg   = '';

                break;

            }

            $tmp_priority = '<span style="font-family:Arial, ' . 
                            'Helvetica, sans-serif; font-size:15px; ' . 
                            'text-align:left; color:#F90000; ' . 
                            'font-weight: bold;">' . 
                            $tmp_priority_const . 
                            '</span>&nbsp;<span style="' . 
                            'font-family:Arial, Helvetica, ' . 
                            'sans-serif; font-size:15px; ' . 
                            'text-align:left; color:#000; ' . 
                            'font-weight: bold;">' . 
                            $tmp_priority_msg . 
                            '</span>';

        }else{

            switch($log_priority){
                case 0:
                case \LOG_EMERG:

                    $tmp_priority = 'LOG_EMERG :: Emergency. System ' . 
                                    'is unusable.';

                break;
                case 1:
                case \LOG_ALERT:

                    $tmp_priority = 'LOG_ALERT :: Alert. Action ' . 
                                    'must be taken immediately.';

                break;
                case 2:
                case \LOG_CRIT:

                    $tmp_priority = 'LOG_CRIT :: Critical ' . 
                                    'conditions encountered.';

                break;
                case 3:
                case \LOG_ERR:

                    $tmp_priority = 'LOG_ERR :: Error ' . 
                                    'conditions encountered.';

                break;
                case 4:
                case \LOG_WARNING:

                    $tmp_priority = 'LOG_WARNING :: Warning ' . 
                                    'conditions encountered.';

                break;
                case 5:
                case \LOG_NOTICE:

                    $tmp_priority = 'LOG_NOTICE :: Notice. Normal, but ' . 
                                    'significant, condition encountered.';

                break;
                case 6:
                case \LOG_INFO:

                    $tmp_priority = 'LOG_INFO :: Informational ' . 
                                    'message.';

                break;
                case 7:
                case \LOG_DEBUG:

                    $tmp_priority = 'LOG_DEBUG :: Debug-level ' . 
                                    'message.';

                break;
                default:

                    $tmp_priority = 'UNKNOWN';

                break;

            }

        }

        return $tmp_priority;

    }

