                break;
                case \E_ALL:

                    $tmp_priority_const = 'E_ALL';
                    $tmp_priority_msg   = 'All errors, warnings and notices.';

                    if($full_text_description !== false){

                        $tmp_priority_msg = 'All errors, warnings and notices.';
                        
                    }

                break;

            }

            $tmp_priority = '<span style="font-family:Arial, ' . 
                            'Helvetica, sans-serif; font-size:15px; ' . 
                            'text-align:left; color:#F90000; ' . 
                            'font-weight: bold;">' . 
