                            'font-family:Arial, Helvetica, ' . 
                            'sans-serif; font-size:15px; ' . 
                            'text-align:left; color:#000; ' . 
                            'font-weight: bold;">' . 
                            $tmp_priority_msg . 
                            '</span>';

        }else{

            switch($const){
                case \E_ERROR:

                    $tmp_priority_const = 'LOG_EMERG';
                    $tmp_priority_msg   = $tmp_priority_const . 
                                          ' :: Fatal run-time errors.';

                    if($full_text_description !== false){

