                    }

                break;
                case \E_COMPILE_WARNING:

                    $tmp_priority_const = 'E_COMPILE_WARNING';
                    $tmp_priority_msg   = $tmp_priority_const . 
                                          ' :: Compile-time warnings ' . 
                                          '(non-fatal errors).';

                    if($full_text_description !== false){

