    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function proper_replace(
             $pattern, 
             $replacement, 
             $original_str)
    {

        $pattern_array     = array();
        $replacement_array = array();

        $pattern_array[0]     = $pattern;
        $replacement_array[0] = $replacement;

        $original_str = str_replace(
                        $pattern_array, 
                        $replacement_array, 
                        $original_str);

        return $original_str;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function get_link_data(
             $data_type, 
             $url, 
             $unit_test = false, 
             $to_plaid = false)
    {

        return self::$_R['kivotos']->R['config_mgr']->get_link_data(
                                                      $data_type,
                                                      $url,
                                                      $unit_test,
                                                      $to_plaid);

    }

    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function return_random_theme_style()
    {
        /*

            Look out for: $this->theme_attributes_ARRAY  
            Replace all: $system_theme_style_constants_ARRAY 
            
            self::$R_data['interact_ui_theme_options']['int_index']
            self::$R_data['interact_ui_theme_options']['isset_options']

        */

        $tmp_index = 0;
        $tmp_selection = rand(0, count(self::$R_data['R_interact_ui_theme_options']['int_index']) - 1);

        /*error_log(__LINE__ . 
         *    ' crnrstn rand tmp_selection=[' . 
         *    $tmp_selection . '].');
         *
         */

        foreach(self::$R_data['R_interact_ui_theme_options']['int_index'] as 
            $index => $tmp_theme_style)
        {

            if(($tmp_selection == $tmp_index)){

                if($tmp_theme_style == self::$R_data['int_flag']['CRNRSTN_UI_RANDOM'])
                    $tmp_theme_style = self::$R_data['int_flag']['CRNRSTN_UI_DARKNIGHT'];

                $tmp_theme_style_ARRAY = $this->return_constant_profile_ARRAY($tmp_theme_style);
                //$tmp_theme_style_nom = $tmp_theme_style_ARRAY[self::$R_data['int_flag']['R_string']];
                $tmp_theme_style_int = $tmp_theme_style_ARRAY[self::$R_data['int_flag']['R_integer']];

                /*error_log(__LINE__ . 
                 *    ' crnrstn NOT RANDOM == [' . 
                 *    $tmp_theme_style_ARRAY[self::$R_data['int_flag']['R_string']] . 
                 *    '].');
                 *
                 */

                return $tmp_theme_style_int;

                break 1;

            }

            $tmp_index++;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Return CRNRSTN :: Theme 
         * (default) integer data 
         * on input data error. 
         *
         */
        return $this->get_resource(
                      'default_interact_ui_theme', 
                      0, 
                      'CRNRSTN::RESOURCE::DEFAULT_THEME');

    }

