    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_interact_ui_theme_profile($output_format = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Where $output_format = [self::$R_data['int_flag']['R_string'], 
         *                         self::$R_data['int_flag']['R_integer'],  
         *                         self::$R_data['int_flag']['R_array']]
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Take any value (garbage 
         * UGC data will quietly 
         * take the default 
         * theme)...or look for 
         * a flipped bit. 
         *
         */
        $theme_profile_ARRAY = $this->return_set_bits(self::$system_theme_style_constants_ARRAY);

        $tmp_cnt_set_bits = count($theme_profile_ARRAY);
        if($tmp_cnt_set_bits > 0)
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Take the last 
             * flipped bit. 
             *
             * There should 
             * only be one at [0]. 
             *
             */
            $theme_const = $theme_profile_ARRAY[$tmp_cnt_set_bits - 1];

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize profile 
         * with system settings 
         * default theme. 
         *
         */
        if(!isset($theme_const))
            $theme_const = $this->get_resource(
                                  'default_interact_ui_theme', 
                                  0, 
                                  'CRNRSTN::RESOURCE::DEFAULT_THEME');

        if(isset($output_format))
            return $this->return_int_const_profile(
                          $theme_const, 
                          $output_format);

        return $theme_const;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function print_r_str_skinny(
             $data = NULL, 
             $title = NULL, 
             $theme_profile = NULL, 
             $line_num = NULL, 
             $method = NULL, 
             $file = NULL)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Take any value (garbage 
         * UGC data will quietly 
         * take the default 
         * theme)...or look for 
         * a flipped bit. 
         *
         */
        if(!isset($theme_profile))
            $theme_profile = $this->return_interact_ui_theme_profile();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * For fun. 
         *
         */
        if($theme_profile == self::$R_data['int_flag']['CRNRSTN_UI_RANDOM']){

            $theme_profile = $this->return_random_theme_style();
            $this->random_theme_constant = $theme_profile;

        }

        $tmp_box_shadow_cnt = count($this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.offset-x']);
        $tmp_box_shadow_str = '';

        for($i = 0; $i < $tmp_box_shadow_cnt; $i++){

            $tmp_00 = $this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.inset'][$i];
            $tmp_01 = $this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.offset-x'][$i];
            $tmp_02 = $this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.offset-y'][$i];
            $tmp_03 = $this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.blur-radius'][$i];
            $tmp_04 = $this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.spread-radius'][$i];
            $tmp_05 = $this->theme_attributes_ARRAY[$theme_profile]['stage.canvas.box-shadow.color'][$i];

            $tmp_box_shadow_str .= $tmp_00 . ' ' . 
                                   $tmp_01 . ' ' . 
                                   $tmp_02 . ' ' . 
                                   $tmp_03 . ' ' . 
                                   $tmp_04 . ' ' . 
                                   $tmp_05 . ', ';

        }

        $tmp_box_shadow_str = $this->strrtrim($tmp_box_shadow_str, ', ');

        $tmp_meta = '[' . 
                    $this->return_micro_time() . ' ' . 
                    date('T') . '] [rtime ' . 
                    $this->wall_time() . ' secs]<br>';

        if(!isset($method) || 
            ($method == ''))
            if(isset($file))
                $tmp_meta .= ' [file ' . $file . ']';
        else
            $tmp_meta .= ' [mthd ' . $method . ']';

        if(isset($line_num))
            $tmp_meta .= ' [lnum ' . $line_num . ']';

        $tmp_print_r = print_r($data, true);

        $tmp_print_r = $this->proper_replace('\r\n', '\n', $tmp_print_r);
        $lines = preg_split('#\r?\n#', trim($tmp_print_r));
        $tmp_line_cnt = sizeof($lines);

        $lineHTML = implode('<br />', range(1, $tmp_line_cnt + 0));

        $tmp_hash = $this->salt(42, '01');

        $tmp_linecnt_html_out = '<div style="position: relative;">' . 
                                '<div style="line-height:20px; ' . 
                                'position:absolute; z-index: 2; ' . 
                                'padding-right:5px; font-size:14px; ' . 
                                'font-family: Verdana, Arial, ' . 
                                'Helvetica, sans-serif; color:' . 
                                $this->theme_attributes_ARRAY[$theme_profile]['stage.lnum.css.color'] . 
                                '; border-right:' . 
                                $this->theme_attributes_ARRAY[$theme_profile]['stage.lnum.css.right-border-width'] . 
                                ' ' . 
                                $this->theme_attributes_ARRAY[$theme_profile]['stage.lnum.css.right-border-style'] . 
                                ' ' . 
                                $this->theme_attributes_ARRAY[$theme_profile]['stage.lnum.css.right-border-color'] . 
                                '; background-color:' . 
                                $this->theme_attributes_ARRAY[$theme_profile]['stage.lnum.css.background-color'] . 
                                '; padding-top:25px; padding-' . 
                                'bottom:25px; padding-left:4px;">' . 
                                $lineHTML . 
                                '</div></div>';

        if(!isset($title)){

            $tmp_title = '<div style="display:block; ' . 
                         'clear:both; height:4px; line-height:' . 
                         '1px; overflow:hidden; width:100%; ' . 
                         'font-size:1px;"></div><div style="' . 
                         'float:left; padding:5px 0 0 8px; ' . 
                         'text-align:left; font-family: ' . 
                         'Courier New, Courier, monospace; ' . 
                         'font-size:11px;">';
            $tmp_title .= 'Begin ' . __FUNCTION__ . '() output ' . 
                          'by C<span style="color:#F00;">R' . 
                          '</span>NRSTN ::';
            $tmp_title .= '</div><div style="display:block; ' . 
                          'clear:both; height:0; line-height:1px; ' . 
                          'overflow:hidden; width:100%; ' . 
                          'font-size:1px;"></div>';
            $title = '';

        }else{

            if($title != ''){

                $tmp_title = '<div style="display:block; ' . 
                             'clear:both; height:4px; ' . 
                             'line-height:1px; overflow:' . 
                             'hidden; width:100%; font-size:' . 
                             '1px;"></div><div style="' . 
                             'float:left; padding:5px 0 0 ' . 
                             '8px; text-align:left; ' . 
                             'overflow-wrap: break-word; ' . 
                             'font-family: Courier New, ' . 
                             'Courier, monospace; ' . 
                             'font-size:11px;">';
                $tmp_title .= $title;
                $tmp_title .= '</div><div style="display:' . 
                              'block; clear:both; height:0px; ' . 
                              'line-height:1px; overflow:' . 
                              'hidden; width:100%; ' . 
                              'font-size:1px;"></div>';

            }else{

                $tmp_title = '<div style="display:block; ' . 
                             'clear:both; height:4px; ' . 
                             'line-height:1px; overflow:' . 
                             'hidden; width:100%; font-size:' . 
                             '1px;"></div><div style="float:' . 
                             'left; padding:5px 0 0 8px; ' . 
                             'text-align:left; font-family: ' . 
                             'Courier New, Courier, monospace; ' . 
                             'font-size:11px;">';
                $tmp_title .= 'Begin ' . 
                              __FUNCTION__ . 
                              '() output by C<span style="color:' . 
                              '#F00;">R</span>NRSTN ::';
                $tmp_title .= '</div><div style="display:block; ' . 
                              'clear:both; height:0; line-height:' . 
                              '1px; overflow:hidden; width:100%; ' . 
                              'font-size:1px;"></div>';

            }

        }

        $tmp_copy_clipboard_func_call_str = '&nbsp;&nbsp;&nbsp;<a href=' . 
                                             '"#" onclick="copy_output_' . 
                                             $tmp_hash . 
                                             '(); return false;" style="' . 
                                             'font-family: Courier New, ' . 
                                             'Courier, monospace; font-' . 
                                             'size:12px; color:#06C; text-' . 
                                             'align: right;">Copy to ' . 
                                             'clipboard</a>';
        $tmp_copy_clipboard_func_def_str = '<script>
        function copy_output_' . $tmp_hash . '(){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * SOURCE :: https://stackoverflow.com/questions/1173194/select-all-div-text-with-single-mouse-click
             * COMMENT :: https://stackoverflow.com/a/1173319
             * AUTHOR :: Denis Sadowski :: https://stackoverflow.com/users/136482/denis-sadowski
             *
             */
            if(document.selection){ // IE

                var range = document.body.createTextRange();
                range.moveToElementText(document.getElementById("crnrstn_print_r_source_' . 
                $tmp_hash . '"));
                range.select();

            }else if(window.getSelection){

                var range = document.createRange();
                range.selectNode(document.getElementById("crnrstn_print_r_source_' . 
                $tmp_hash . '"));
                window.getSelection().removeAllRanges();
                window.getSelection().addRange(range);

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * SOURCE :: https://www.w3schools.com/howto/howto_js_copy_clipboard.asp
             *
             * Copy the text 
             * inside the 
             * text field.
             *
             */
            document.execCommand(\'copy\');

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Alert the 
             * copied text.
             *
             * alert(\'Copied the text: \' + 
             *    document.getElementById(\'crnrstn_print_r_source_\' . 
             *    $tmp_hash . \'\').innerHTML);
             *
             */

            document.getElementById(\'crnrstn_print_r_display_\'' . 
            $tmp_hash . '\').style.backgroundColor = \'' . 
            $this->theme_attributes_ARRAY[$theme_profile]['stage.content.highlight-color'] . '\';

        }
        </script>';

        $tmp_top_link_str    = '';
        $tmp_module_page_key = self::$_R['kivotos']->R['dtsm']->return_received_data('crnrstn_interact_ui_link_text_click');
        if(\strlen($tmp_module_page_key) > 0){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Requires https for 
             * reliable use due to 
             * ajax injection. 
             *
             * $tmp_copy_clipboard_func_call_str = '&nbsp;&nbsp;&nbsp;' . 
             *                                     '<a href="#" onclick="oCRNRSTN_JS.' . 
             *                                     'copy_to_clipboard(\'' . $tmp_hash . '\'); ' . 
             *                                     'return false;" style="font-family: ' . 
             *                                     'Courier New, Courier, monospace; ' . 
             *                                     'font-size:12px; color:#06C; ' . 
             *                                     'text-align: right;">' . 
             *                                     'Copy to clipboard</a>';
             *
             */
            $tmp_copy_clipboard_func_call_str = '';
            $tmp_copy_clipboard_func_def_str = '';
            $tmp_top_link_str = '<a href="#" onclick="oCRNRSTN_JS.' . 
                                'crnrstn_interact_ui_ux(\'scrolltop\', ' . 
                                'this);" rel="crnrstn_top_' . 
                                $this->session_salt() . 
                                '">Top</a>';

        }

        $tmp_title_content = '';

        if(\strlen($tmp_module_page_key) < 1 || 
            (\strlen($title) > 0) || 
            (\strlen($title) < 1 && 
                __FUNCTION__ == 'print_r')){

            $tmp_title_content = '
                <div style="padding: 5px 0 0 0; ' . 
                'font-family: Courier New, Courier, ' . 
                'monospace; overflow-wrap: break-word; ' . 
                'font-size:12px; line-height: 20px; ' . 
                'float: left; width:74%;">
                    <span style="font-family: Courier ' . 
                    'New, Courier, monospace; font-' . 
                    'size:12px; color:#333; text-align: ' . 
                    'left;">' . $tmp_title . '</span>
                </div>';

        }

        $tmp_out = '<div style="display:block; ' . 
                   'clear:both; height:0; line-' . 
                   'height:0; overflow:hidden; ' . 
                   'width:100%; font-size:1px;">' . 
                   '</div>
        ' .  $tmp_copy_clipboard_func_def_str . '
        <div id="crnrstn_print_r_output_' . 
        $tmp_hash . 
