               $R_theme_data[self::$R_data['int_flag']['R_string']]  = (string) $resource_constant;
               $R_theme_data[self::$R_data['int_flag']['R_integer']] = (int) $resource_constant;
               $R_theme_data['title']['TEXT']       = 'Unknown Theme';
               $R_theme_data['description']['TEXT'] = 'This is an unknown theme';

            break;

        }

        // 5 :: Tuesday, June 16, 2026 @ 1718 hrs.
        return $R_theme_data;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_constant_profile_ARRAY(
             $constant, 
             $return_type = 'R_array')
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Note: $constant can be 
         *       an array of integer 
         *       constants for batching 
         *       meta requests. 
         *       where, $return_type = [self::$R_data['int_flag']['R_string'], 
         *                              self::$R_data['int_flag']['R_integer'], 
         *                              self::$R_data['int_flag']['R_array']].
         *
         */

        if(is_string($return_type))
            $return_type = self::$R_data['int_flag'][$return_type];

        $tmp_ARRAY = array();
        $return_data_type_int_const = $this->data_type_filter($return_type, $return_type);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Do we have an 
         * array of integers 
         * for which to 
         * get meta? 
         *
         */
        if(is_array($constant)){

            foreach($constant as 
                $const_index => $integer_const)
            {

                $tmp_data_type = $this->gettype($integer_const, self::$R_data['int_flag']['R_integer']);

                if(is_number($integer_const) || 
                    is_string($integer_const))
                {

                    switch($tmp_data_type){
                        //case CRNRSTN_STRING:
                        case self::$R_data['int_flag']['R_string']:

                            $tmp_workshop_ARRAY = $this->return_int_const_profile((string) $integer_const);

                        break;
                        default:
                            //A NUMBER.

                            $tmp_workshop_ARRAY = $this->return_int_const_profile((int) $integer_const);

                        break;

                    }

                    switch($return_data_type_int_const){
                        //case CRNRSTN_STRING:
                        //case CRNRSTN_INT:
                        //case CRNRSTN_INTEGER:
                        case self::$R_data['int_flag']['R_string']:
                        case self::$R_data['int_flag']['R_int']:
                        case self::$R_data['int_flag']['R_integer']:

                            $tmp_ARRAY[$tmp_workshop_ARRAY[self::$R_data['int_flag']['R_integer']]][$return_type] = $this->return_int_const_profile(
                                                                                                                    (int) $integer_const, 
                                                                                                                    $return_type);

                        break;
                        default:
                            //CRNRSTN_ARRAY

                            $tmp_ARRAY[$tmp_workshop_ARRAY[self::$R_data['int_flag']['R_integer']]]['ARRAY'] = $this->return_int_const_profile(
                                                                                                               (int) $integer_const, 
                                                                                                               self::$R_data['int_flag']['R_string']);

                        break;

                    }

                }

            }

            return $tmp_ARRAY;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Process non-array 
         * UGC input. 
         *
         */
        $tmp_workshop_ARRAY = $this->return_int_const_profile($constant);

        if($tmp_workshop_ARRAY['FAMILY'] == 'UNKNOWN'){

            return NULL;

        }

        switch($return_data_type_int_const){
            //case CRNRSTN_STRING:
            //case CRNRSTN_INT:
            //case CRNRSTN_INTEGER:
            case self::$R_data['int_flag']['R_string']:
            case self::$R_data['int_flag']['R_int']:
            case self::$R_data['int_flag']['R_integer']:

                return $this->return_int_const_profile(
                              (int) $tmp_workshop_ARRAY[self::$R_data['int_flag']['R_integer']], 
                              $return_type);

            break;
            case self::$R_data['int_flag']['R_array']:
            default:
                //CRNRSTN_ARRAY

                return $this->return_int_const_profile((int) $tmp_workshop_ARRAY[self::$R_data['int_flag']['R_integer']]);

            break;

        }

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE :: https://www.php.net/manual/en/function.base64-encode.php
