    function encode_image(
             $file_path, 
             $filetype = NULL)
    {

        if(!isset($filetype)){

            $filetype = pathinfo($file_path, PATHINFO_EXTENSION);

        }

        if(is_file($file_path) || 
            (is_string($file_path) && 
                (\strlen($file_path) > 0)))
        {

            $clr_ssl_msg = __METHOD__ . 
                           ' attempted to open ' . 
                           $file_path . '. ';
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Spool this CLR-SSL 
             * error log message. 
             *
             * First CLR-SSL framework 
             * implementation; we crack 
             * a beer. 
             *
             * Sweetwater® 420
             *
             *
             * 5 :: Monday, May 18, 2026 @ 1451 hrs.
             *
             */
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_WARNING, 
                   \E_ERROR, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token, 
                   true);

            $img_binary = fread(fopen($file_path, 'r'), $this->find_filesize($file_path));

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Clear the CLR-SSL message 
             * from the error log spool.
             *
             * First CLR-SSL framework 
             * implementation. Let's grab 
             * us a can of Sweetwater® 420!
             *
             *
             * 5 :: Monday, May 18, 2026 @ 1449 hrs.
             *
             */
            $this->error_log_clear($msg_token);

            $tmp_base64 = 'data:image/' . 
                          $filetype . 
                          ';base64,' . 
                          base64_encode($img_binary);

            return $tmp_base64;

        }else{

            if(!is_file($file_path)){

                $clr_ssl_msg = 'Error when attempting ' . 
                               'to encode an image ' . 
                               'of type [' . 
                               $filetype . 
                               ']. Not a file [' . 
                               \strval($file_path) . 
                               '].';
                // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                             'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token = array(
                         'token'                   => $msg_token, 
                         'token_generation_date'   => $token_generation_date, 
                         'request_type'            => __METHOD__, 
                         'code'                    => 200, 
                         'clr_ssl_msg'             => $clr_ssl_msg);
                $this->error_log(
                       $clr_ssl_msg, 
                       \LOG_ERR, 
                       \E_ERROR, 
                       __LINE__, 
                       __METHOD__, 
                       __FILE__, 
                       $token, 
                       true);

            }

            if(!is_string($file_path)){

                $clr_ssl_msg = 'Error when attempting ' . 
                               'to encode an image of type [' . 
                               $filetype . 
                               ']. Filepath is not string data [' . 
                               \strval($file_path) . '].';
                // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                             'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                $token = array(
                         'token'                   => $msg_token, 
                         'token_generation_date'   => $token_generation_date, 
                         'request_type'            => __METHOD__, 
                         'code'                    => 200, 
                         'clr_ssl_msg'             => $clr_ssl_msg);
                $this->error_log(
                       $clr_ssl_msg, 
                       \LOG_ERR, 
                       \E_ERROR, 
                       __LINE__, 
                       __METHOD__, 
                       __FILE__, 
                       $token, 
                       true);

            }

        }

        return NULL;

    }

