     * @param
     * @param
     * @return
     * @access public
     *
     */
    function get_http_resource(
             $param_name, 
             $transport_protocol = NULL)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This method has been 
         * replaced...right? 
         *
         *
         * 5 :: Thursday, December 8, 2022 @ 2011 hrs.
         *
         * error_log(__LINE__.' []. die();');
         * die();
         *
         */

        if(!isset($transport_protocol)){

            $tmp_variables_order = $this->ini_get('variables_order');
            $tmp_vo_ARRAY        = str_split($tmp_variables_order);

            foreach($tmp_vo_ARRAY as 
                $key => $value)
            {

                switch($value){
                    case 'G':

                        if(isset(self::$http_param_handle_ARRAY['GET'][$param_name])){

                            return self::$http_param_handle_ARRAY['GET'][$param_name];

                        }

                    break;
                    case 'P':

                        if(isset(self::$http_param_handle_ARRAY['POST'][$param_name])){

                            return self::$http_param_handle_ARRAY['POST'][$param_name];

                        }

                    break;

                }

            }

        }else{

            $http_protocol = strtoupper($transport_protocol);
            $http_protocol = $this->str_sanitize($http_protocol, 'http_protocol_simple');

            switch($http_protocol){
                case 'POST':
                case 'GET':

                    if(isset(self::$http_param_handle_ARRAY[$http_protocol][$param_name])){

                        return self::$http_param_handle_ARRAY[$http_protocol][$param_name];

                    }

                break;
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * HOOOSTON, VE HAFF PROBLEM!
                     * https://www.wired.com/2011/04/alt-text-spacecraft/
                     *
                     */
                    $clr_ssl_msg = 'Unable to determine ' . 
                                   'HTTP protocol from the ' . 
                                   'provided value of [' . 
                                   \strval($transport_protocol) . 
                                   '].';
                    // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                    $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                 'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token = array(
                             'token'                   => $msg_token, 
                             'token_generation_date'   => $token_generation_date, 
                             'request_type'            => __METHOD__, 
                             'code'                    => 200, 
                             'clr_ssl_msg'             => $clr_ssl_msg);
                    $this->error_log(
                           $clr_ssl_msg, 
                           \LOG_WARNING, 
                           \E_ERROR, 
                           __LINE__, 
                           __METHOD__, 
                           __FILE__, 
                           $token, 
                           true);

                break;

            }

        }

        return NULL;

    }

