    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function tidy_boolean(
             $data, 
             $return_data_type = 'R_boolean', 
             $architecture = 'DEFAULT', 
             $serialized_bit_name = NULL, 
             $return_raw_byte_read = false)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Where, $return_data_type = [self::$R_data['int_flag']['R_icy_bitmask'], 
         *                             self::$R_data['int_flag']['R_soap_tunnel'],
         *                             self::$R_data['int_flag']['R_string'], 
         *                             'R_string', 
         *                             'string', 
         *                             'str',
         *                             self::$R_data['int_flag']['R_int'], 
         *                             'R_int', 
         *                             'int', 
         *                             self::$R_data['int_flag']['R_integer'],
         *                             'R_integer', 
         *                             'integer', 
         *                             self::$R_data['int_flag']['R_bool'],
         *                             'R_bool', 
         *                             self::$R_data['int_flag']['R_boolean'], 
         *                             'R_boolean',
         *                             self::$R_data['int_flag']['R_bool_is_html'], 
         *                             self::$R_data['int_flag']['R_js_css_min_mode'],
         *                             self::$R_data['int_flag']['R_fs_map_css_lib']]
         *
         * Where, $architecture = ['DEFAULT', 
         *                          self::$R_data['int_flag']['R_bool_is_html'], 
         *                          self::$R_data['int_flag']['R_icy_bitmask'],
         *                          self::$R_data['int_flag']['R_soap_tunnel'], 
         *                          self::$R_data['int_flag']['R_js_css_min_mode'],
         *                          self::$R_data['int_flag']['R_fs_map_css_lib']]
         *
         *
         * 5 :: Tuesday, November 21, 2023 @ 0217 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Fixed tidy_boolean defect where 
         *       data value input = (bool) false, 
         *       but would always return true. 
         *       5 :: Saturday, April 25, 2026 @ 1049 hrs.
         *
         */
        if(\is_string($return_data_type))
            // 5 :: Tuesday, July 21, 2026 @ 0423 hrs.
            $return_data_type = self::$R_data['int_flag'][$return_data_type];

        /*
        A matrix of all of 
        the *current output 
        possibilities for 
        boolean-ish-type 
        CLR-SSL System 
        data architectures 
        and native PHP 
        runtime memory data 
        structures/types 
        of similar ilk.
        -----
        self::$R_data['int_flag']['R_string']             ['true', 'false']
        self::$R_data['int_flag']['R_soap_tunnel']        ['TRUE', 'FALSE']
        self::$R_data['int_flag']['R_integer']            [0, 1]
        self::$R_data['int_flag']['R_boolean']            [(bool) true, (bool) false]
        self::$R_data['int_flag']['R_icy_bitmask']        ['ON', 'OFF']
        self::$R_data['int_flag']['R_bool_is_html']       ['HTML', 'TEXT']    // Wednesday, November 22, 2023 @ 0055 hrs.
        self::$R_data['int_flag']['R_js_css_min_mode']    ['PROD', 'DEV']     // Thursday, November 23, 2023 @ 1034 hrs.
        self::$R_data['int_flag']['R_fs_map_css_lib']     ['ON', 'OFF']       // Thursday, November 23, 2023 @ 1142 hrs.

        E.g. when $return_data_type = self::$R_data['int_flag']['R_icy_bitmask'], 
             (string) 'ON' or (string) 'OFF' will 
             be returned:

            therefore, ergo, visa-vie, concordantly,

                $oCRNRSTN->tidy_boolean(1, (int) self::$R_data['int_flag']['R_icy_bitmask']);

            returns:

                (string) 'ON'

            To acquire the "is active" 
            state for the OpenSSL v1.1.1
            Encryption Rotation Services 
            Layer (OERSL) on any initialized
            CRNRSTN :: Lightsaber RoCEv2 
            SOAP Services Layer (CLR-SSL) 
            Multi-Channel Decoupled Data 
            Object (MC-DDO) channel, the 
            same method can be used. 

            For example, to check to see 
            if encryption is activated
            and running on $_GET[] for 
            all system resources, use:

                $oCRNRSTN->tidy_boolean(
                           self::$R_data['int_flag']['R_encrypt_TUNNEL'] & 
                           self::$R_data['int_flag']['R_channel_GET'], 
                           self::$R_data['int_flag']['R_icy_bitmask'], 
                           self::$R_data['int_flag']['R_icy_bitmask']);

            If the CRNRSTN :: Lightsaber 
            RoCEv2 SOAP Services Data 
            Tunnel Layer (SSDTL/
            PSSDTL) is running on HTTP/
            HTTPS $_GET[]...i.e., if the
            CLR-SSL OpenSSL encryption 
            services are up and running 
            for all data that is tunneled 
            through system generated <a> 
            links, then the above method 
            call would return:

                (string) 'ON'

            Here are the CLR-SSL 
            encryption profile string  
            constant system globals. 

            self::$R_data['int_flag']['R_encrypt_TUNNEL']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_GET']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_POST']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_COOKIE']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_SESSION']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_DATABASE']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_SOAP']
            self::$R_data['int_flag']['R_encrypt_OERSL']

            Also Consider:
            R_encrypt_FILE

            Are these three moot for 
            encryption?
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_FORM']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_RDMA']
            self::$R_data['int_flag']['R_encrypt_TUNNEL'] & self::$R_data['int_flag']['R_channel_RUNTIME']


            5 :: Tuesday, November 21, 2023 @ 0741 hrs.
            Last Modified: Tuesday, March 3, 2026 @ 0837 hrs.

        */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CRNRSTN :: Boolean 
         * state computation 
         * by architecture. 
         *
         */
        switch($architecture){
            case 'R_fs_map_css_lib':
            case self::$R_data['int_flag']['R_fs_map_css_lib']:
            case 'R_js_css_min_mode':
            case self::$R_data['int_flag']['R_js_css_min_mode']:
            case 'R_icy_bitmask':
            case self::$R_data['int_flag']['R_icy_bitmask']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Support for serialized 
                 * CRNRSTN :: Icy Digital ITCC 
                 * Bitmask Bits. 
                 *
                 * Developer Note: this utilizes an 
                 * array of CRNRSTN :: Bitmask objects 
                 * that are initialized with indexes 
                 * salted by md5(name). 
                 *
                 * Please see,
                 *      $oCRNRSTN->initialize_serialized_bit($name, $integer_constant);
                 *      $oCRNRSTN->is_serialized_bit_set($name, $integer_constant);
                 *      $oCRNRSTN->toggle_serialized_bit($name, $integer_constant);
                 *      $oCRNRSTN->serialized_bit_stringin($name, $bits_stringin);
                 *      $oCRNRSTN->serialized_bit_stringout($name);
                 *
                 */
                if(isset($serialized_bit_name)){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Input data is 
                     * assumed to be 
                     * null if the 
                     * string is empty. 
                     *
                     */
                    if(\strlen($serialized_bit_name) > 0){

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * CRNRSTN :: Lightsaber Icy 
                         * Digital ITCC Bitmask 
                         * Integer State (Bit Flip) 
                         * Management Services Layer. 
                         *
                         */
                        $tmp_tidy_boolean = $this->is_serialized_bit_set($serialized_bit_name, $data);

                        if($return_raw_byte_read !== false)
                            return $tmp_tidy_boolean;

                    }else{

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Support for a single 
                         * system wide CRNRSTN :: 
                         * Icy Digital ITCC 
                         * Bitmask Bit. 
                         *
                         * Please see, 
                         *      $oCRNRSTN->initialize_bit($integer_constant);
                         *      $oCRNRSTN->is_bit_set($integer_constant);
                         *      $oCRNRSTN->toggle_bit($integer_constant);
                         *      $oCRNRSTN->bit_stringin($bits_stringin);
                         *      $oCRNRSTN->bit_stringout();
                         *
                         * 5 :: Tuesday, November 21, 2023 @ 0439 hrs.
                         *
                         */

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * CRNRSTN :: Lightsaber Icy 
                         * Digital ITCC Bitmask 
                         * Integer State (Bit Flip) 
                         * Management Services Layer. 
                         *
                         */
                        $tmp_tidy_boolean = $this->is_bit_set($data);

                        if($return_raw_byte_read !== false)
                            return $tmp_tidy_boolean;

                    }

                }else{

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * CRNRSTN :: Lightsaber Icy 
                     * Digital ITCC Bitmask 
                     * Integer State (Bit Flip) 
                     * Management Services Layer. 
                     *
                     */
                    $tmp_tidy_boolean = $this->is_bit_set($data);

                    if($return_raw_byte_read !== false)
                        return $tmp_tidy_boolean;

                }

            break;
            case 'R_bool_is_html':
            case self::$R_data['int_flag']['R_bool_is_html']:
            case 'R_soap_tunnel':
            case self::$R_data['int_flag']['R_soap_tunnel']:
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: is first 
                 * and foremost a robust 
                 * SOAP services layer. 
                 *
                 *
                 * 5 :: Tuesday, November 21, 2023 @ 0732 hrs.
                 *
                 * $architecture = 'DEFAULT':
                 *
                 */
                if(is_bool($data) === true){

                    //return $data;
                    $tmp_tidy_boolean = (bool) $data;

                }else{

                    if(!isset($data))
                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * This functions like 
                         * a "bad data" filter. 
                         *
                         * return false;
                         *
                         */
                        $tmp_tidy_boolean = false;
                    else
                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * SOURCE :: https://www.php.net/manual/en/function.is-bool.php
                         * COMMENT :: https://www.php.net/manual/en/function.is-bool.php#124179
                         * AUTHOR :: Julio Marchi
                         *
                         * Note:
                         * is_enabled($variable) from Julio on  
                         * php.net has been renamed in CRNRSTN :: to 
                         * $this->boolean_conversion($variable).
                         *
                         * return $this->boolean_conversion($data);
                         *
                         */
                        $tmp_tidy_boolean = $this->boolean_conversion($data);

                }

            break;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Begin CRNRSTN :: output 
         * formating of the 
         * computated boolean 
         * state by architecture. 
         *
         */
        switch($architecture){
            case 'R_soap_tunnel':
            case self::$R_data['int_flag']['R_soap_tunnel']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Guarantee a proper 
                 * CLR-SSL system 
                 * integer data type. 
                 *
                 * $oCRNRSTN->data_type_filter() 
                 * returns CRNRSTN_UNKNOWN_TYPE, 
                 * if the input value is 
                 * not recognized. 
                 *
                 */
                $tmp_return_data_type_int = $this->data_type_filter($return_data_type, self::$R_data['int_flag']['R_integer']);

                switch($tmp_return_data_type_int){
                    //case CRNRSTN_STRING:
                    case self::$R_data['int_flag']['R_string']:

                        if($tmp_tidy_boolean !== false)
                            return 'true';

                        return 'false';

                    break;
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * case CRNRSTN_INT:      //<-- Moved to switch 
                     *                        //    default for support 
                     *                        //    of unknown type.
                     *
                     * case CRNRSTN_INTEGER:  //<-- Moved to switch 
                     *                        //    default for support 
                     *                        //    of unknown type. 
                     *
                     */
                    //case CRNRSTN_BOOL:
                    //case CRNRSTN_BOOLEAN:
                    case self::$R_data['int_flag']['R_bool']:
                    case self::$R_data['int_flag']['R_boolean']:
                    //case CRNRSTN_SOAP_TUNNEL:
                    case self::$R_data['int_flag']['R_soap_tunnel']:

                        if($tmp_tidy_boolean !== false)
                            return 'TRUE';

                        return 'FALSE';

                    break;
                    //case CRNRSTN_CSS_LIB_ASSET_MAPPING:
                    case self::$R_data['int_flag']['R_fs_map_css_lib']:
                    //case CRNRSTN_ICY_BITMASK:
                    case self::$R_data['int_flag']['R_icy_bitmask']:

                        if($tmp_tidy_boolean !== false)
                            return 'ON';

                        return 'OFF';

                    break;
                    //case CRNRSTN_PROD_MIN_JS_CSS:
                    case self::$R_data['int_flag']['R_js_css_min_mode']:

                        if($tmp_tidy_boolean !== false)
                            return 'PROD';

                        return 'DEV';

                    break;
                    default:
                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * case self::$R_data['int_flag']['R_int']:
                         * case self::$R_data['int_flag']['R_integer']:
                         * case self::$R_data['int_flag']['R_float']:
                         * case self::$R_data['int_flag']['R_double']:
                         * case self::$R_data['int_flag']['R_array']:
                         * case self::$R_data['int_flag']['R_object']:
                         * case self::$R_data['int_flag']['R_resource']:
                         * case self::$R_data['int_flag']['R_resource_closed']:
                         * case self::$R_data['int_flag']['R_unknown_type']:
                         * case self::$R_data['int_flag']['R_null']:
                         * case self::$R_data['int_flag']['R_mixed']:
                         *
                         */

                        if($tmp_tidy_boolean !== false)
                            return 1;

                        return 0;

                    break;

                }

            break;
            case 'R_bool_is_html':
            case self::$R_data['int_flag']['R_bool_is_html']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
