    /**
     * R :: Check "Booleanic" Conditions :) Lol...more like "NERD"-eanic Conditions...imho. 5 ::
     *
     * SOURCE :: https://www.php.net/manual/en/function.is-bool.php
     * COMMENT :: https://www.php.net/manual/en/function.is-bool.php#124179
     * AUTHOR :: Julio Marchi
     *
     *
     * Julio Marchi
     * 
     * Note:
     * is_enabled($variable) from Julio on  
     * php.net has been renamed in CRNRSTN :: to 
     * $this->boolean_conversion($variable).
     *
     * @param [mixed] $variable Can be anything (string, bol, integer, etc.)
     * @return [boolean]        Returns TRUE  for "1", "true", "on" and "yes"
     *                          Returns FALSE for "0", "false", "off" and "no"
     *                          Returns NULL otherwise.
     * @access public
     *
     */
    function boolean_conversion($variable = NULL)
    {

        if(!isset($variable)) return NULL;

        return filter_var(
               $variable, 
               FILTER_VALIDATE_BOOLEAN, 
               FILTER_NULL_ON_FAILURE);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function ui_css_length_unit_clean(
             &$length, 
             $unit_return_override = NULL, 
             $append_unit = true)
    {

        /*
        # C # R # N # R # S # T # N # :: # L # I # G # H # T
        5 :: Thursday, June 22, 2023 @ 0555 hrs.
        https://www.w3schools.com/cssref/css_units.php

        Absolute Lengths
        -----
        Note: Maths conversions between 
              abs units are actually possible.
              See, https://www.freecodecamp.org/news/css-unit-guide/
        -----
        The absolute length units are fixed 
        and a length expressed in any of these 
        will appear as exactly that size.

        Absolute length units are not 
        recommended for use on screen, 
        because screen sizes vary so much. 
        However, they can be used if the 
        output medium is known, such as 
        for print layout.
        -----
            Unit	        Description
            cm	            centimeters
            mm	            millimeters
            in	            inches (1in = 96px = 2.54cm)
            px *	        pixels (1px = 1/96th of 1in)
            pt	            points (1pt = 1/72 of 1in)
            pc	            picas (1pc = 12 pt)

        Relative Lengths
        Relative length units specify a 
        length relative to another 
        length property. Relative length 
        units scale better between 
        different rendering medium.
        -----
            Unit	        Description
            em	            Relative to the 
                            font-size of the element 
                            (2em means 2 times the 
                            size of the current font)
            ex	            Relative to the x-height 
                            of the current font 
                            (rarely used)
            ch	            Relative to the width of 
                            the "0" (zero)
            rem	            Relative to font-size of 
                            the root element
            vw	            Relative to 1% of the 
                            width of the viewport*
            vh	            Relative to 1% of the 
                            height of the viewport*
            vmin	        Relative to 1% of 
                            viewport's* smaller dimension
            vmax	        Relative to 1% of 
                            viewport's* larger dimension
            %	            Relative to the parent element

        */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * First pass logic. 
         * are any CSS 
         * units here? 
         *
         */
        $tmp_length_clean = $this->str_sanitize(
                                   $length, 
                                   'css_length_to_clean_int');

        $tmp_hide_units_append = false;

        if(((string) $tmp_length_clean === '0') || 
            ((string) $tmp_length_clean === '0.0') || 
            ((string) $tmp_length_clean === '0.00') || 
            ((string) $tmp_length_clean === '0.000') || 
            ((string) $tmp_length_clean === '0.0000'))
        {

            $tmp_hide_units_append = true;

        }

        if($tmp_hide_units_append == true){

            $length = $tmp_length_clean;

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Ignore unit return 
             * override if 
             * append_unit == false. 
             *
             */
            if($append_unit == false){

                $length = $tmp_length_clean;

            }else{

                if(isset($unit_return_override)){

                    if(\strlen($unit_return_override) > 0){

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Append override length 
                         * units to the clean 
                         * CSS data value. 
                         *
                         */
                        $length = $tmp_length_clean . $unit_return_override;

                    }else{

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Initialize CSS 
                         * length default. 
                         *
                         */
                        if(!isset($this->css_length_unit)){

                            $this->css_length_unit = $this->get_resource(
                                                            'default_css_unit_length', 
                                                            0, 
                                                            'CRNRSTN::RESOURCE::DEFAULT_UNIT_CSS');

                        }

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Append override length 
                         * units to the clean 
                         * CSS data value. 
                         *
                         */
                        $length = $tmp_length_clean . $this->css_length_unit;

                    }

                }else{

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Initialize CSS 
                     * length default. 
                     *
                     */
                    if(!isset($this->css_length_unit)){

                        $this->css_length_unit = $this->get_resource(
                                                        'default_css_unit_length', 
                                                        0, 
                                                        'CRNRSTN::RESOURCE::DEFAULT_UNIT_CSS');

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Append override length 
                     * units to the clean 
                     * CSS data value. 
                     *
                     */
                    $length = $tmp_length_clean . $this->css_length_unit;

                }

            }

        }

    }

