     *
     * @param
     * @return
     * @access public
     *
     */
    function return_cache_channels($return_active_channels = false)
    {

        // Where, self::$data_channel_init_sequence = 'GPHSJTCDROMF';
        $tmp_channel_init_ARRAY = str_split(self::$data_channel_init_sequence);
        $tmp_channel_ARRAY = array();

/*
 *        if(isset(self::$channel_syntax_ARRAY)){
 *
 *            if(count(self::$channel_syntax_ARRAY) > 1){
 *
 *                return self::$channel_syntax_ARRAY;
 *
 *            }
 *
 *        }
 *
 */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * The channel sequence 
         * controller for any 
         * channels that are 
         * in the output array. 
         *
         * Always honor the 
         * order of operations 
         * for data handling 
         * in settings, 
         * i.e. 'GPHSJCDROF'. 
         *
         */
        foreach($tmp_channel_init_ARRAY as 
            $alpha_ch_index => $channel_alpha)
        {

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Channel sequence is 
             * validated (and 
             * confirmed [or made] 
             * to be complete) at 
             * DDO input. 
             *
             *
             * 5 :: Sunday, October 15, 2023 @ 0236 hrs.
             *
             */
            if(isset(self::$channel_syntax_ARRAY[$channel_alpha])){

                if($return_active_channels == true){

                    if($this->get_channel_config($channel_alpha, 'cache_is_active') == true){

                        /*error_log(__LINE__ . 
                         *    ' crnrstn MC-DDO ' . 
                         *    'CHANNEL ACTIVE [' . 
                         *    $channel_alpha . '] ' . 
                         *    $this->get_channel_config($channel_alpha, 'NAME') . 
                         *    ' MC-DDO CHANNEL.');
                         *
                         */

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Return only active 
                         * data storage channels 
                         * in the sequence of 
                         * their initialization. 
                         *
                         */
                        $tmp_channel_ARRAY[] = $this->get_channel_config(
                                                      $channel_alpha, 
                                                      'AUTHORIZATION', 
                                                      'PROFILE', 
                                                      'PRIMARY', 
                                                      self::$R_data['int_flag']['R_integer']);

                    }else{

                        /*$tmp = \strlen(array('324324'));
                         *error_log(__LINE__ . 
                         *    ' crnrstn MC-DDO ' . 
                         *    'CHANNEL INACTIVE [' . 
                         *    $channel_alpha . '] ' . 
                         *    $this->get_channel_config($channel_alpha, 'NAME') . 
                         *    ' MC-DDO CHANNEL.');
                         *
                         */

                    }

                }else{

                    /*error_log(__LINE__ . 
                     *    ' crnrstn MC-DDO ' . 
                     *    'CHANNEL ACTIVE [' . 
                     *    $channel_alpha . '] ' . 
                     *    $this->get_channel_config($channel_alpha, 'NAME') . 
                     *    '.');
                     *
                     */

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Return all data 
                     * storage channels 
                     * in the sequence 
                     * of their initialization. 
                     *
                     */
                    $tmp_channel_ARRAY[] = self::$channel_syntax_ARRAY[$channel_alpha];

                }

            }

        }

        return $tmp_channel_ARRAY;

    }

