    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function finalize_ttl_secs($ttl)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Check for 
         * no TTL.
         *  
         *expire, [-1]. 
         *
         */
        if($ttl < 0){

            return $ttl;

        }

        $tmp_secs = time();
        $tmp_secs += (int) $ttl;

        return $tmp_secs;

    }

