            if(isset($filename) && isset($file_extension)){

                $tmp_filepath = $filepath_override;
                $tmp_filename = $filename;
                $tmp_file_extension = $file_extension;

            }else{

                $this->error_log('Unable to return ' . 
                       'file output due to missing data.', 
