    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function proper_version($system = 'CRNRSTN')
    {

        $system = \trim(\strtoupper($system));

        switch($system){
            case 'LINUX':

                return $this->version_linux();

            break;
            case 'APACHE':

                return 'Apache v' . 
                       $this->version_apache();

            break;
            case 'MYSQLI':

                return 'MySQLi v' . 
                       $this->version_mysqli();

            break;
            case 'PHP':

                return 'php v' . 
                       $this->version_php();

            break;
            case 'SOAP':

                return $this->version_soap();

            break;
            case 'OPENSSL':

                return 'OpenSSL v' . 
                       $this->version_openssl();

            break;
            case 'CRNRSTN':

                return 'CRNRSTN :: v' . 
                       self::$R_data['version_crnrstn'];

            break;
            case 'SYSTEM_REGISTRY':

                return 'CRNRSTN :: Lightsaber System Registry v' . 
                       $this->version_system_registry();

            default:

                return 'UNKNOWN[' . $system . 
                       '] :: v[x].[y].[z]';

            break;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function byte_reporting(
             $report_profile, 
             $channel, 
             $source, 
             $data_len = NULL)
    {

        switch($report_profile){
            case 'total_bytes_processed[r]':
                //Read

                return self::$_R['kivotos']->R['rrs_map']->byte_reporting(
                                                           'total_bytes_processed[r]',
                                                           $channel,
                                                           $source);

            break;
            case 'channel_bytes_processed[r]':
                //Read

                return self::$_R['kivotos']->R['rrs_map']->byte_reporting(
                                                           'channel_bytes_processed[r]',
                                                           $channel,
                                                           $source);

            break;
            case 'total_bytes_processed[w]':
                //Writes

                foreach($channel as 
                    $ch_index => $ch_channel)
                {

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Extract reporting 
                     * for channel byte 
                     * storage. 
                     *
                     */
                    $tmp_total_bytes_processed[$ch_channel] = self::$_R['kivotos']->R['rrs_map']->byte_reporting(
                                                                                                  'total_bytes_processed[r]',
                                                                                                  $ch_channel,
                                                                                                  $source);

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Increment bytes 
                     * processed by channel. 
                     *
                     */
                    $tmp_total_bytes_processed[$ch_channel] += (int) $data_len;

                    self::$_R['kivotos']->R['rrs_map']->byte_reporting(
                                                        'total_bytes_processed[w]',
                                                        $ch_channel,
                                                        $source,
                                                        $tmp_total_bytes_processed);

                }

            break;
            case 'channel_bytes_processed[w]':
                //Writes

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Extract reporting 
                     * for channel byte 
                     * storage. 
                 *
                 */
                $tmp_total_bytes_processed = self::$_R['kivotos']->R['rrs_map']->byte_reporting(
                                                                                 'channel_bytes_processed[r]',
                                                                                 $channel,
                                                                                 $source);

                $tmp_total_bytes = $tmp_total_bytes_processed[$channel];
                $tmp_total_bytes += $data_len;

                $tmp_total_bytes_processed[$channel] = (int) $tmp_total_bytes;

                /*error_log(__LINE__ . 
                 *    '  crnrstn $channel[' . 
                 *    $this->get_channel_config($channel, 'NAME') . 
                 *    ']. tmp_total_bytes[' . 
                 *    print_r($tmp_total_bytes, true) . 
                 *    ']. ');
                 *error_log(__LINE__ . 
                 *    '  crnrstn $channel[' . 
                 *    $channel . ']. tmp_total_bytes[' . 
                 *    print_r($tmp_total_bytes, true) . 
                 *    ']. ');
                 *die();
                 *
                 */
                self::$_R['kivotos']->R['rrs_map']->byte_reporting(
                                                    'channel_bytes_processed[w]',
                                                    $channel,
                                                    $source,
                                                    $tmp_total_bytes_processed);

            break;

        }

        return true;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function format_sql_interval($interval_str)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * 5 :: Wednesday, October 4, 2023 @ 0025 hrs.
         *
         * https://dev.mysql.com/doc/refman/8.0/en/expressions.html
         * The following table shows the 
         * expected form of the expr argument 
         * for each unit value.
         *
         * Table 9.2 Temporal Interval 
         *           Expression and Unit 
         *           Arguments
         *
         * Unit Value	       Expected expr Format
         * -----               -----
         * MICROSECOND         MICROSECONDS
         * SECOND              SECONDS
         * MINUTE              MINUTES
         * HOUR                HOURS
         * DAY                 DAYS
         * WEEK                WEEKS
         * MONTH               MONTHS
         * QUARTER             QUARTERS
         * YEAR                YEARS
         * SECOND_MICROSECOND  'SECONDS.MICROSECONDS'
         * MINUTE_MICROSECOND  'MINUTES:SECONDS.MICROSECONDS'
         * MINUTE_SECOND       'MINUTES:SECONDS'
         * HOUR_MICROSECOND    'HOURS:MINUTES:SECONDS.MICROSECONDS'
         * HOUR_SECOND         'HOURS:MINUTES:SECONDS'
         * HOUR_MINUTE         'HOURS:MINUTES'
         * DAY_MICROSECOND     'DAYS HOURS:MINUTES:SECONDS.MICROSECONDS'
         * DAY_SECOND          'DAYS HOURS:MINUTES:SECONDS'
         * DAY_MINUTE          'DAYS HOURS:MINUTES'
         * DAY_HOUR            'DAYS HOURS'
         * YEAR_MONTH          'YEARS-MONTHS'
         *
         */

        try{

            $tmp_is_seconds = false;

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Is this 
             * just seconds? 
             *
             */
            if(is_numeric($interval_str)){

                $tmp_is_seconds = true;

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Handle base 
             * integers as 
             * seconds. 
             *
             */
            if($tmp_is_seconds == true){

                foreach(self::$sql_interval_ARRAY['UNITS']['VALUES'][self::$sql_interval_ARRAY['UNITS']['STRING_PATTERN']['SECOND']] as 
                    $tmp_unit => $tmp_format)
                {

                    return $interval_str . ' ' . $tmp_unit;

                }

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Strip spaces. 
             *
             */
            $tmp_interval = $this->str_sanitize($interval_str, 'sql_interval');

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * UPPERCASE the data.
             *
             */
            $tmp_interval_upper = strtoupper($interval_str);

            foreach(self::$sql_interval_ARRAY['UNITS']['STRING_PATTERN'] as 
                $tmp_unit_str_ptrn => $unit_index)
            {

                $tmp_pos_unit = strpos($tmp_interval, $tmp_unit_str_ptrn);
                if($tmp_pos_unit !== false){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Successful match on SQL 
                     * interval unit. Acquire 
                     * the integer/float value 
                     * via splitting the data 
                     * on unit. 
                     *
                     */
                    $tmp_data_str_ARRAY = explode($tmp_unit_str_ptrn, $tmp_interval_upper);
                    foreach(self::$sql_interval_ARRAY['UNITS']['VALUES'][$unit_index] as 
                        $tmp_unit => $tmp_format)
                    {

                        return $tmp_data_str_ARRAY[0] . ' ' . $tmp_unit;

                    }

                    break 1;

                }

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * HOOOSTON, VE HAFF PROBLEM!
             * https://www.wired.com/2011/04/alt-text-spacecraft/
             *
             */
            $clr_ssl_msg = 'CRNRSTN :: is unable to ' . 
                           'format the input data, ' . 
                           $interval_str . 
                           ', to a recognized ' . 
                           'SQL time interval. ' . 
                           $this->data_report(
                                  $interval_str, 
                                  'CRNRSTN :: MC-DDO Input ' . 
                                  'Data Report |');
            // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
            $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                         'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
            $token = array(
                     'token'                   => $msg_token, 
                     'token_generation_date'   => $token_generation_date, 
                     'request_type'            => __METHOD__, 
                     'code'                    => 200, 
                     'clr_ssl_msg'             => $clr_ssl_msg);
            $this->error_log(
                   $clr_ssl_msg, 
                   \LOG_ERR, 
                   \E_ERROR, 
                   __LINE__, 
                   __METHOD__, 
                   __FILE__, 
                   $token);

            throw new \Exception($clr_ssl_msg);

        }catch(\Exception $e){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Exception handling performed 
             * by the Logging Services Layer 
             * of the CRNRSTN :: Lightsaber 
             * RoCEv2 SOAP Services 
             * Layer (CLR-SSL). 
             *
             * Allow the CLR-SSL to handle 
             * this exception per the 
             * configured logging profile of 
             * the running application on 
             * this server. 
             *
             *
             * 5
             *
             * Sunday, June 30, 2024 @ 1540 hrs.
             * Last Modified: Friday, February 27, 2026 @ 0233 hrs.
             *
             */
            $this->catch_exception(
                   $e, 
                   \LOG_ERR, 
                   __METHOD__, 
                   __NAMESPACE__);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Return false.
             *
             */
            return NULL;

        }

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE :: https://www.php.net/manual/en/function.floatval
     * COMMENT :: https://www.php.net/manual/en/function.floatval.php#106367
     * AUTHOR :: PapaPinguoin 
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function float_to_str($val)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * function remove_scientific_notation($val)
         * {
         *
         * EN: To view the very large 
         *     and very small numbers 
         *     (eg from a database 
         *     DECIMAL), without 
         *     displaying scientific
         *     notation, or 
         *     leading zeros.
         *
         * FR: Pour afficher les très 
         *     grand et très petits 
         *     nombres (ex. depuis une 
         *     base de données DECIMAL), 
         *     sans afficher la notation 
         *     scientifique, ni les 
         *     zéros non significatifs.
         *
         *
         * echo floattostr("0000000000000001"); 
         * echo floattostr("1.00000000000000"); 
         * echo floattostr("0.00000000001000"); 
         * echo floattostr("0000.00010000000"); 
         * echo floattostr("000000010000000000.00000000000010000000000"); 
         * echo floattostr("-0000000000000.1"); 
         * echo floattostr("-00000001.100000");
         *
         * // result
         * // 1
         * // 1
         * // 0.00000000001
         * // 0.0001
         * // 10000000000.0000000000001
         * // -0.1
         * // -1.1
         *
         */

        preg_match("#^([\+\-]|)([0-9]*)(\.([0-9]*?)|)(0*)$#", trim($val), $o);
        return $o[1].sprintf('%d',$o[2]).($o[3]!='.'?$o[3]:'');

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function data_reporting_bytes($data)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This is used by format_bytes() 
         * so that we get (bytes) 
         * integer as input and (bytes) 
         * integer as output. 
         *
         * TODO :: Add method input 
         *         parameter to 
         *         modulate integer 
         *         handling behavior. 
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Removed unused 
         *       input parameter, 
         *       $integer_mode_bytes = true, 
         *       from the crnrstn 
         *       data_reporting_bytes() 
         *       method. 
         *       5 :: Wednesday, June 24, 2026 @ 0036 hrs.
         *       
         */

        $bytes = 0;

        if(!isset(self::$R_data['R_datatype_master']))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * The CLR-SSL is not yet 
             * ready, so we shall step 
             * into our Initialization 
             * Series to complete this 
             * assignment, hopefully 
             * with A+ 100% marks. 
             *
             *
             * 5 :: Wednesday, June 24, 2026 @ 0100 hrs.
             *
             */
            return $this->initialization_series_data_reporting_bytes($data);

        switch($this->gettype($data, self::$R_data['int_flag']['R_integer'])){
            case self::$R_data['int_flag']['R_string']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE :: https://stackoverflow.com/questions/7568949/measure-string-size-in-bytes-in-php
                 * COMMENT :: https://stackoverflow.com/a/25299281
                 * AUTHOR :: Ulver :: https://stackoverflow.com/users/1773335/ulver
                 *
                 * Further to PhoneixS answer to get 
                 * the correct length of string in 
                 * bytes - Since mb_strlen()
                 * is slower than strlen(), for the 
                 * best performance one can check 
                 * "mbstring.func_overload" ini
                 * setting so that mb_strlen() is 
                 * used only when it is 
                 * really required:
                 *
                 * Thankfully, this check is no 
                 * longer needed as of PHP 8.0.0. 
                 * The function overloading
                 * "feature" has been removed as 
                 * of PHP 8.0.0, and deprecated 
                 * in 7.2.0.
                 *
                 *
                 * - Buttle Butkus, 2022, https://stackoverflow.com/a/7568984
                 *
                 * CRNRSTN :: PHP support.
                 * PHP 5 >= 5.5, PHP 7, PHP 8.
                 *
                 */
                $bytes = $this->tidy_boolean(self::$R_data['operating_system']['mbstring_func_overload']) ? \mb_strlen((string) $data, '8bit') : \strlen((string) $data);

            break;
            case self::$R_data['int_flag']['R_int']:
            case self::$R_data['int_flag']['R_integer']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: PHP SUPPORT.
                 * PHP 5 >= 5.5, PHP 7, PHP 8.
                 *
                 */
                $bytes = $this->tidy_boolean(self::$R_data['operating_system']['mbstring_func_overload']) ? \mb_strlen((string) $data, '8bit') : \strlen((string) $data);

            break;
            case self::$R_data['int_flag']['R_bool']:
            case self::$R_data['int_flag']['R_boolean']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE :: https://dev.to/shevchenkonik/memory-size-of-javascript-boolean-3mlj
                 *        Posted on Feb 20, 2020
                 *        [Originally published at shevchenkonik.com]
                 * AUTHOR :: Nik Shevchenko
                 *
                 * A boolean is actually 1 
                 * byte. But alignment may cause 
                 * 4 bytes to be used on a 
                 * 32-bit platform or 8 bytes on 
                 * a 64-bit platform. This old 
                 * trick comes from the 
                 * observation that allocated 
                 * memory takes up at least 4 
                 * or 8 bytes, and are aligned 
                 * in the way that the least 
                 * significant bit or three 
                 * will be zero. 
                 *
                 * In C++, the size of the type 
                 * boolean is implementation-
                 * defined and is usually equal 
                 * to 1 (the size of the type char, 
                 * and the smallest size a 
                 * type can have), but is not 
                 * required to be in 
                 * particular, in Visual Studio 
                 * up to version 4.2, it was 4. 
                 * More information about 
                 * C++ boolean values is 
                 * available at docs. 
                 * 
                 */

                switch(self::$R_data['os_bit_size']){
                    case 32:

                        $bytes = 4;

                    break;
                    case 64:

                        $bytes = 8;

                    break;
                    default:

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * HOOOSTON, VE HAFF PROBLEM!
                         * https://www.wired.com/2011/04/alt-text-spacecraft/
                         *
                         */
                        $clr_ssl_msg = 'Unknown operating ' . 
                                       'system bit size. 8 bytes will ' . 
                                       'be assigned for BOOLEAN data; ' . 
                                       'on 64-bit platforms, CRNRSTN :: ' . 
                                       'reports BOOLEAN data as ' . 
                                       '8 bytes.';
                        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token = array(
                                 'token'                   => $msg_token, 
                                 'token_generation_date'   => $token_generation_date, 
                                 'request_type'            => __METHOD__, 
                                 'code'                    => 200, 
                                 'clr_ssl_msg'             => $clr_ssl_msg);
                        $this->error_log(
                               $clr_ssl_msg, 
                               \LOG_NOTICE, 
                               \E_NOTICE, 
                               __LINE__, 
                               __METHOD__, 
                               __FILE__, 
                               $token);

                        $bytes = 8;

                    break;

                }

            break;
            case self::$R_data['int_flag']['R_float']:
            case self::$R_data['int_flag']['R_double']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: PHP Support.
                 * PHP 5 >= 5.5, PHP 7, PHP 8.
                 *
                 */
                $bytes = $this->tidy_boolean(self::$R_data['operating_system']['mbstring_func_overload']) ? \mb_strlen((string) $data, '8bit') : \strlen((string) $data);

            break;
            case self::$R_data['int_flag']['R_null']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE :: https://stackoverflow.com/questions/2430655/java-does-null-variable-require-space-in-memory
                 * COMMENT :: https://stackoverflow.com/a/2430672
                 * AUTHOR :: dsimcha :: https://stackoverflow.com/users/23903/dsimcha
                 *
                 * In Java, null is just a 
                 * value that a reference (which is 
                 * basically a restricted pointer) 
                 * can have. It means that 
                 * the reference refers to 
                 * nothing. In this case you still 
                 * consume the space for the 
                 * reference. This is 4 bytes on 
                 * 32-bit systems or 8 bytes on 
                 * 64-bit systems. However, 
                 * you're not consuming any space 
                 * for the class that the 
                 * reference points to until you 
                 * actually allocate an 
                 * instance of that class to 
                 * point the reference at. 
                 *
                 */

                switch(self::$R_data['os_bit_size']){
                    case 32:

                        $bytes = 4;

                    break;
                    case 64:

                        $bytes = 8;

                    break;
                    default:

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * HOOOSTON, VE HAFF PROBLEM!
                         * https://www.wired.com/2011/04/alt-text-spacecraft/
                         *
                         */
                        $clr_ssl_msg = 'Unknown operating ' . 
                                       'system bit size. 8 bytes will ' . 
                                       'be assigned for NULL data; on ' . 
                                       '64-bit platforms, CRNRSTN :: ' . 
                                       'reports NULL data as 8 bytes.';
                        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token = array(
                                 'token'                   => $msg_token, 
                                 'token_generation_date'   => $token_generation_date, 
                                 'request_type'            => __METHOD__, 
                                 'code'                    => 200, 
                                 'clr_ssl_msg'             => $clr_ssl_msg);
                        $this->error_log(
                               $clr_ssl_msg, 
                               \LOG_NOTICE, 
                               \E_NOTICE, 
                               __LINE__, 
                               __METHOD__, 
                               __FILE__, 
                               $token);

                        $bytes = 8;

                    break;

                }

            break;
            case self::$R_data['int_flag']['R_array']:
            case self::$R_data['int_flag']['R_object']:
            case self::$R_data['int_flag']['R_resource']:
            case self::$R_data['int_flag']['R_resource_closed']:
            case self::$R_data['int_flag']['R_unknown_type']:

                //$bytes = \strlen(\serialize($data));

                // 5 :: Saturday, June 27, 2026 @ 1157 hrs.
                $bytes = $this->tidy_boolean(self::$R_data['operating_system']['mbstring_func_overload']) ? \mb_strlen((string) \serialize($data), '8bit') : \strlen((string) \serialize($data));

            break;
            default:




            break;

        }

        return $bytes;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE :: https://stackoverflow.com/questions/2510434/format-bytes-to-kilobytes-megabytes-gigabytes
     * COMMENT :: https://stackoverflow.com/a/2510459
     * AUTHOR :: Leo :: https://stackoverflow.com/users/227532/leo
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_bytes(
             $data, 
             $precision_override = 2, 
             $power_unit_system = NULL, // ['ISO_80000' or 'SI_Metric']
             $append_byte_units = true, 
             $nerf_bytes_reporting = true, 
             $calculate_data_bytes = true, 
             $int_bytes_output = false)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed crnrstn->return_bytes() 
         *       to return_bytes() and with 
         *       redesigned input parameters. 
         *       5 :: Monday, April 13, 2026 @ 0156 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed return_bytes() input parameter,  
         *       precision, to precision_override. 
         *       5 :: Saturday, June 27, 2026 @ 1119 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed crnrstn class 
         *       private static 
         *       $byte_reporting_units 
         *       to private static 
         *       $byte_reporting_system.
         *       5 :: Saturday, June 27, 2026 @ 1130 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Replaced crnrstn class 
         *       private static 
         *       $byte_units_ARRAY 
         *       with $R_data['R_byte_units']. 
         *       5 :: Saturday, June 27, 2026 @ 1136 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added input parameter, 
         *       $force_output_units_bytes = false.
         *       5 :: Case of the Monday's, August 3, 2026 @ 0859 hrs.
         *
         */

        if($calculate_data_bytes !== false)
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Convert input data into 
             * a more proper integer bytes 
             * representation for 
             * better output 
             * formatting. 
             *
             *
             * 5 :: Friday, December 8, 2023 @ 0019 hrs.
             *
             */
            $reporting_bytes = $bytes = $this->data_reporting_bytes($data);
        else
            $reporting_bytes = $bytes = $data;

        // Return (int) bytes?
        if(($int_bytes_output !== false) && 
            ($append_byte_units == false))
            return (int) $reporting_bytes;
        else
            if(($int_bytes_output !== false) && 
            ($append_byte_units !== false))
            return (string) $reporting_bytes . ' bytes';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CLR-SSL Configuration 
         * Settings Override. 
         *
         * File: 
         * _R/_config
         * /_config.defaults
         * /_crnrstn.system_settings.inc.php
         *
         * Please see: byte_reporting_precision
         *
         */
        if(!isset($precision_override))
            $precision_override = self::$byte_reporting_precision;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CLR-SSL Configuration 
         * Settings Override. 
         *
         * File: 
         * _R/_config
         * /_config.defaults
         * /_crnrstn.system_settings.inc.php
         *
         * Please see: byte_reporting_units
         *
         */
        if(!isset($power_unit_system))
            $power_unit_system = self::$byte_reporting_system;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Integer Bytes Processing to 
         * Human Readable ISO/IEC 80000-13 
         * or SI METRIC string data.
         *
         * ISO/IEC 80000-13
         *      Part 13: Information science 
         *               and technology
         *      The Standard also includes definitions 
         *      for units relating to information 
         *      technology, such as the erlang (E), 
         *      bit (bit), octet (o), byte (B), 
         *      baud (Bd), shannon (Sh), hartley (Hart) 
         *      and the natural unit of 
         *      information (nat).
         *
         *      Clause 4 of the Standard defines 
         *      standard binary prefixes used to 
         *      denote powers of 1024 as 1024^1 (kibi-), 
         *      1024^2 (mebi-), 1024^3 (gibi-), 
         *      1024^4 (tebi-), 1024^5 (pebi-), 
         *      1024^6 (exbi-), 1024^7 (zebi-) 
         *      and 1024^8 (yobi-).
         *
         *      International System of Quantities
         *      Part 1 of ISO 80000 introduces the 
         *      International System of Quantities 
         *      and describes its relationship with 
         *      the International System of Units (SI). 
         *      Specifically, its introduction states 
         *
         *        "The system of quantities, 
         *        including the relations among the 
         *        quantities used as the basis of 
         *        the units of the SI, is named the 
         *        International System of Quantities, 
         *        denoted 'ISQ', in all languages." 
         *
         *      It further
         *      clarifies that "ISQ is simply a 
         *      convenient notation to assign to the 
         *      essentially infinite and continually 
         *      evolving and expanding system of 
         *      quantities and equations on which all 
         *      of modern science and technology 
         *      rests. ISQ is a shorthand notation 
         *      for the 'system of quantities on 
         *      which the SI is based'."
         *
         * https://en.wikipedia.org/wiki/ISO/IEC_80000#Part_13:_Information_science_and_technology
         * This page was last edited 
         * on 12 August 2023, at 08:50 (UTC).
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * International System of Units
         *
         *      The BIPM specifies 24 prefixes 
         *      for the International System 
         *      of Units (SI):
         *
         *      SI prefixes
         *      Prefix              Base 10     Decimal Adoption
         *      Name    Symbol
         *      quetta  Q           10^30       1000000000000000000000000000000	    2022
         *      ronna   R           10^27       1000000000000000000000000000        2022
         *      yotta   Y           10^24       1000000000000000000000000           1991
         *      zetta   Z           10^21       1000000000000000000000              1991
         *      exa	    E           10^18       1000000000000000000	                1975
         *      peta    P           10^15       1000000000000000                    1975
         *      tera    T           10^12       1000000000000                       1960
         *      giga    G           10^9        1000000000                          1960
         *      mega    M           10^6        1000000	                            1873
         *      kilo    k           10^3        1000                                1795
         *      hecto   h           10^2        100                                 1795
         *      deca    da          10^1        10                                  1795
         *      —       —           10^0        1                                   —
         *      deci    d           10^−1       0.1	                                1795
         *      centi   c           10^−2       0.01                                1795
         *      milli   m           10^−3       0.001                               1795
         *      micro   μ           10^−6       0.000001                            1873
         *      nano    n           10^−9       0.000000001	                        1960
         *      pico    p           10^−12      0.000000000001                      1960
         *      femto   f           10^−15      0.000000000000001                   1964
         *      atto    a           10^−18      0.000000000000000001                1964
         *      zepto   z           10^−21      0.000000000000000000001	            1991
         *      yocto   y           10^−24      0.000000000000000000000001          1991
         *      ronto   r           10^−27      0.000000000000000000000000001       2022
         *      quecto  q           10^−30      0.000000000000000000000000000001    2022
         *
         *      Notes:
         *      Prefixes adopted before 1960 already 
         *      existed before SI. The introduction 
         *      of the CGS system was in 1873. 
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         *
         * https://en.wikipedia.org/wiki/International_System_of_Units
         *
         * This page was last edited 
         * on 26 September 2023, at 19:58 (UTC).
         *
         */
        if(\is_numeric($bytes)){

            /*
            if($always_bytes_out == true){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Bytes in. 
                 * Bytes out. 
                 * Always. 
                 *
                 *
                  return $bytes;

            }
            */

            $bytes = $bytes * 1;

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * CRNRSTN v2.00.0000 :: MODS
             * See, https://en.wikipedia.org/wiki/Binary_prefix
             * 
             * See also, ISO/IEC 80000 family 
             * of standards (November 1, 2009)
             * https://en.wikipedia.org/wiki/ISO/IEC_80000#Information_science_and_technology
             *
             * See comment below 
             * by Devator :: https://stackoverflow.com/users/659731/devator
             * SOURCE :: https://stackoverflow.com/questions/2510434/format-bytes-to-kilobytes-megabytes-gigabytes
             *
             * Actually, it's KiB, MiB,
             * GiB and TiB since you are
             * dividing by 1024.
             *
             * If you divided by 1000
             * it would be without the i.
             *
             *
             * Devator
             * May 16, 2013 at 19:41
             *
             * # C # R # N # R # S # T # N # :: # L # I # G # H # T
             *
             * This is my impetus 
             * to include the above 
             * links to additional 
             * material from 
             * wikipedia into 
             * this source code. 
             *
             *
             * 5
             *
             * Friday, July 5, 2024 @ 0147 hrs.
             *
             */
            switch($power_unit_system){
                case 'SI_Metric':

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * SI :: METRIC. 
                     *
                     *
                     */
                    $units       = self::$R_data['R_byte_units']['SI_Metric']['units'];
                    $units_power = 1000;

                break;
                case 'ISO_80000':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * IEC :: ISO 80000-13 
                     * or IEC 80000-13. 
                     *
                     *
                     */
                    $units       = self::$R_data['R_byte_units']['ISO_80000']['units'];
                    $units_power = 1024;

                break;

            }

            $bytes = \max($bytes, 0);
            $pow   = \floor(($bytes ? \log($bytes) : 0) / \log($units_power));
            $pow   = \min($pow, \count($units) - 1);

            $bytes /= \pow($units_power, $pow);

            $tmp_number = \round($bytes, $precision_override);
            $tmp_number = $this->number_format_keep_precision($tmp_number);

            if($append_byte_units !== false)
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * BYTES :: human 
                 * readable. 
                 *
                 */
                return $tmp_number . 
                       ' ' . 
                       $units[$pow];
           else
               return $tmp_number;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * CRNRSTN :: SI_METRIC (Decimal)
         * -----
         * Value        Metric
         * 1000         kB  kilobyte
         * 1000^2       MB  megabyte
         * 1000^3       GB  gigabyte
         * 1000^4       TB  terabyte
         * 1000^5       PB  petabyte
         * 1000^6       EB  exabyte
         * 1000^7       ZB  zettabyte
         * 1000^8       YB  yottabyte
         * 1000^9       RB  ronnabyte
         * 1000^10      QB  quettabyte
         *
         * CRNRSTN :: ISO_80000 (Binary)
         * -----
         * Value        IEC             Memory
         * 1024         KiB	kibibyte    KB  kilobyte
         * 1024^2       MiB	mebibyte    MB  megabyte
         * 1024^3       GiB	gibibyte    GB  gigabyte
         * 1024^4       TiB	tebibyte    TB  terabyte
         * 1024^5       PiB	pebibyte        –
         * 1024^6       EiB	exbibyte        –
         * 1024^7       ZiB	zebibyte        –
         * 1024^8       YiB	yobibyte        –
         *              –
         *              –
         *
         * https://en.wikipedia.org/wiki/Byte#Multiple-byte_units
         *
         * This page was last edited 
         * on 30 August 2023, at 16:54 (UTC).
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Human readable string 
         * bytes processing to 
         * integer data. 
         *
         */
        $tmp_bytes_human_str_to_lower = $this->str_sanitize(
                                               $bytes, 
                                               'string_to_bytes');

        //$tmp_detection_track_breadcrumb_ARRAY = array();
        $tmp_input_byte_unit_matched = NULL;
        $tmp_unit_system             = NULL;
        $tmp_unit_index              = NULL;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Is there an ISO/IEC 80000-13 
         * 2 char/full text unit 
         * match to input data? 
         *
         */
        foreach(self::$R_data['R_byte_units']['ISO_80000']['string_pattern']['ISO_units_exponential'] as 
            $unit_pattern => $unit_word)
        {

            $tmp_iso_short_pos = \strpos($tmp_bytes_human_str_to_lower, $unit_pattern);
            $tmp_iso_full_pos  = \strpos($tmp_bytes_human_str_to_lower, $unit_word);
            if(($tmp_iso_short_pos !== false) || 
                ($tmp_iso_full_pos !== false))
            {

