    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE  :: https://stackoverflow.com/questions/11807115/php-convert-kb-mb-gb-tb-etc-to-bytes
     * COMMENT :: https://stackoverflow.com/a/17364338
     * AUTHOR  :: https://stackoverflow.com/users/1382046/kristian-williams
     *
     *
     * Kristian Williams
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function to_bytes(
                     $number, 
                     $power, 
                     $system = 'ISO_80000')
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Are we working 
         * with a number? 
         *
         */
        if(!is_numeric($number)){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * It would certainly appear 
             * that this is not a valid 
             * number for the 
             * requested operation. 
             *
             * We shall run a genuinely 
             * invalid calculation and 
             * use the system error that 
             * is generated to clearly 
             * communicate that the input 
             * datum is an "invalid number". 
             *
             * This may be the only way 
             * that an application which 
             * absolutely loves numbers as 
             * much as the CRNRSTN :: 
             * Lightsaber RoCEv2 SOAP 
             * Services Layer (CLR-SSL) 
             * loves numbers would be able 
             * to produce a respectable 
             * error message on this, the 
             * subject matter. 
             * 
             * And the CLR-SSL has really 
             * been loving the numbers 
             * lately, man. We happily pay 
             * the price ($$$) of compute 
             * to acquire an authentic NAN 
             * (not a number), real bad data. 
             *
             * We buy a properly shit value 
             * that can be consistently 
             * and reliably returned with 
             * confidence by the CLR-SSL. 
             *
             * And all this...even in the 
             * midst of "these economic 
             * times", at that! 
             *
             * CRNRSTN :: <3's... 
             * ...(int) CRNRSTN_INTEGER 4 LIFE! 
             *
             *
             * 5 :: Monday, December 4, 2023 @ 1117 hrs.
             * Last Modified: Friday, February 27, 2026 @ 0151 hrs.
             *
             * See, https://www.php.net/manual/en/function.is-nan.php
             *
             */
            return sqrt(-1);

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Truncation of 
         * double/float values. 
         * 
         * Avoid data loss. 
         *
         * Do not cast 
         * $number to an 
         * integer (int), 
         * and by-pass 
         * the following. 
         *
         * return (int) $iUnits * pow(1024, $aUnits[$sUnit]);
         *
         */

        return $number * pow(self::$R_data['R_byte_units'][$system]['base'], $power);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function number_format_keep_precision(
             $number, 
             $dec_places = 0, 
             $dec_point = '.', 
             $thou_separate = ',')
    {
        // 5 :: Friday, July 5, 2024 @ 0106 hrs.

        if($dec_places > 0){

            return \number_format(
                   $number, 
                   $dec_places, 
                   $dec_point, 
                   $thou_separate);

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * SOURCE   :: https://www.php.net/manual/en/function.number-format.php
             * AUTHOR   :: https://www.php.net/manual/en/function.number-format.php#52311
             *
             *
             * stm555 at hotmail dot com
             *
             */
            $broken_number = \explode($dec_point, $number);
            if(isset($broken_number[1]))
                return \number_format(
                       $broken_number[0], 
                       0, 
                       $dec_point, 
                       $thou_separate) . 
                       $dec_point . 
                       $broken_number[1];
            else
                return \number_format(
                       $broken_number[0], 
                       0, 
                       $dec_point, 
                       $thou_separate);

        }

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE  :: https://www.php.net/manual/en/function.highlight-string.php
     * COMMENT :: https://www.php.net/manual/en/function.highlight-string.php#118550
     * AUTHOR  :: stanislav dot eckert at vizson dot de
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function highlight_text(
             $text, 
             $theme_profile = NULL)
    {

        switch($theme_profile){
            case self::$R_data['int_flag']['CRNRSTN_UI_GLASS_DARK_COPY']:
            case self::$R_data['int_flag']['CRNRSTN_UI_GLASS_LIGHT_COPY']:
            case self::$R_data['int_flag']['CRNRSTN_UI_TERMINAL']:
            case self::$R_data['int_flag']['CRNRSTN_UI_WOOD']:
            case self::$R_data['int_flag']['CRNRSTN_UI_PHP']:
            case self::$R_data['int_flag']['CRNRSTN_UI_HTML']:
            case self::$R_data['int_flag']['CRNRSTN_UI_DARKNIGHT']:
            case self::$R_data['int_flag']['CRNRSTN_UI_DAYLIGHT']:
            case self::$R_data['int_flag']['CRNRSTN_UI_FEATHER']:
            case self::$R_data['int_flag']['CRNRSTN_UI_GREYSKY']:
            case self::$R_data['int_flag']['CRNRSTN_UI_RANDOM']:
            default:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Alone and sad with 
                 * a nice cup of coffee, 
                 * a rack mounted 
                 * dual-video card Mac 
                 * Pro, and four (4) 
                 * Apple Pro displays. 
                 *
                 * CRNRSTN_UI_GREYSKY
                 *
                 *
                 * 5
                 *
                 */
                \ini_set('highlight.comment', $this->theme_attributes_ARRAY[$theme_profile]['highlight.comment']);
                \ini_set('highlight.default', $this->theme_attributes_ARRAY[$theme_profile]['highlight.default']);
                \ini_set('highlight.html', $this->theme_attributes_ARRAY[$theme_profile]['highlight.html']);
                \ini_set('highlight.keyword', $this->theme_attributes_ARRAY[$theme_profile]['highlight.keyword']);
                \ini_set('highlight.string', $this->theme_attributes_ARRAY[$theme_profile]['highlight.string']);

            break;

        }

        $text = \trim($text);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * highlight_string() requires 
         * opening PHP tag or otherwise 
         * it will not colorize the text. 
         *
         */
        $text = \highlight_string("<?php " . $text, true);

        $text = \trim($text);

        // Remove Prefix.
        $text = \preg_replace("|^\\<code\\>\\<span style\\=\"color\\: #[a-fA-F0-9]{0,6}\"\\>|", '', $text, 1);

        // Remove Suffix 1.
        $text = \preg_replace("|\\</code\\>\$|", '', $text, 1);

        // Remove Line Breaks.
        $text = \trim($text);

        // Remove Suffix 2.
        $text = \preg_replace("|\\</span\\>\$|", '', $text, 1);

        // Remove Line Breaks.
        $text = \trim($text);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Remove Custom 
         * Added "<?php ". 
         *
         */
        $text = \preg_replace("|^(\\<span style\\=\"color\\: #[a-fA-F0-9]{0,6}\"\\>)(&lt;\\?php&nbsp;)(.*?)(\\</span\\>)|", "\$1\$3\$4", $text);

        return $text;

    }

    /**
     * R :: Calculate the crc32 polynomial of a string and return the same output for both 64 bit and 32 bit operating systems. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function crc_int32($str)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Changed crnrstn->crcINT() 
         *       method visibility from 
         *       private to public. 
         *       5 : Tuesday, April 14, 2026 @ 0219 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed the crnrstn->crcINT() 
         *       input parameter from $value 
         *       to $str, renamed the 
         *       method to crc_int32(), and 
         *       applied a PHP.net solution 
         *       from dave at jufer dot info 
         *       in order to to standardize 
         *       the integer output return 
         *       to match the signed output 
         *       return of 32 bit 
         *       operating systems. 
         *       5 : Wednesday, July 1, 2026 @ 0443 hrs.
         *
         */

        /*
        SOURCE  :: https://www.php.net/manual/en/function.crc32.php
        COMMENT :: https://www.php.net/manual/en/function.crc32.php#79567
        AUTHOR  :: dave at jufer dot info
        
        This function returns the same 
        int value on a 64 bit mc. 
        like the crc32() function on 
        a 32 bit mc.

        dave at jufer dot info

        */

        $crc = \crc32($str);

        if($crc & 0x80000000){

            $crc ^= 0xffffffff;
            $crc += 1;
            $crc = -$crc;

        }

        return $crc;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE   :: https://www.php.net/manual/en/function.str-split.php
     * AUTHOR   :: https://www.php.net/manual/en/function.str-split.php#113274
     *
     *
     * qeremy [atta] gmail [dotta] com
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function str_split_unicode(
             $str, 
             $length = 1)
    {

        $tmp = \preg_split('~~u', $str, -1, PREG_SPLIT_NO_EMPTY);

        if($length > 1){

            $chunks = \array_chunk($tmp, $length);

            foreach($chunks as
                    $i => $chunk)
                $chunks[$i] = \join('', (array)$chunk);

            $tmp = $chunks;

        }

        return $tmp;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE   :: https://stackoverflow.com/questions/13076480/php-get-actual-maximum-upload-size
     * AUTHOR   :: https://stackoverflow.com/users/710377/meustrus
     * COMMENT  :: https://stackoverflow.com/a/25370978
     *
     *
     * meustrus
     *
     * -----
     * Drupal has this implemented
     * fairly elegantly:
     *   Returns a file size
     *   limit in bytes based
     *   on the PHP upload_max_filesize
     *   and post_max_size.
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function file_upload_max_size($crnrstn_bypass = false)
    {

        static $max_size = -1;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * The CRNRSTN :: bypass 
         * is used to prevent 
         * infinite loops when 
         * trying to read this 
         * system value during 
         * CRNRSTN :: Lightsaber 
         * system boot. 
         *
         */
        if(!($crnrstn_bypass !== false)){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * $this->ini_get() 
             *
             * Data reads here will touch 
             * the CRNRSTN :: Lightsaber 
             * RoCEv2 SOAP Services Layer 
             * (CLR-SSL) Multi-Channel 
             * Decoupled Data Object 
             * (MC-DDO) RRS MAP situation.
             *
             */
            $post_max_size = $this->parse_size($this->ini_get('post_max_size'));
            $upload_max    = $this->parse_size($this->ini_get('upload_max_filesize'));

        }else{

            $post_max_size = $this->parse_size(ini_get('post_max_size'));
            $upload_max    = $this->parse_size(ini_get('upload_max_filesize'));

        }

        if($max_size < 0){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Start with 
             * post_max_size. 
             *
             */
            if($post_max_size > 0)
                $max_size = $post_max_size;

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * If upload_max_size 
             * is less, then reduce. 
             *
             * Except if upload_max_size 
             * is zero, which indicates 
             * no limit. 
             *
             */
            if($upload_max > 0 && $upload_max < $max_size)
                $max_size = $upload_max;

        }

        return $max_size;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function parse_size($size)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Remove the non-unit 
         * characters from 
         * the size. 
         *
         */
        $unit = \preg_replace('/[^bkmgtpezy]/i', '', $size);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Remove the non-numeric 
         * characters from 
         * the size. 
         *
         */
        $size = \preg_replace('/[^0-9\.]/', '', $size);

        if($unit)
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Find the position of the 
             * unit in the ordered string 
             * which is the power of 
             * magnitude by which to 
             * multiply a kilobyte. 
             *
             */
            return \round($size * \pow(1024, \stripos('bkmgtpezy', $unit[0])));
        else
            return \round($size);

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     *    private function fileMove_DF(
     *                     $ftp_stream, 
     *                     $SOURCE_filePath, 
     *                     $oEndpoint_serial_SOURCE, 
     *                     $oEndpoint_serial_DESTINATION, 
     *                     $oElectrum_STATS, 
     *                     $SOURCE_filePath_ORIGINAL=NULL)
     *   {
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function file_local_send_by_ftp(
             $ftp_stream_target, 
             $file_source_path, 
             $oEndpoint_serial_SOURCE, 
             $oEndpoint_serial_DESTINATION, 
             $oElectrum_STATS)
    {

        $continue_process            = false;
        $tmp_stats_DESTINATION_ARRAY = array();
        $tmp_stats_dest_path         = '';
        #$tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH']
        #$tmp_stats_DESTINATION_ARRAY['MKSUB_DIR']
        #$tmp_stats_DESTINATION_ARRAY['DESTINATION_FILEPATH']
        #$tmp_stats_DESTINATION_ARRAY['SPLIT_DIR']

        /* $tmp_stats_DESTINATION_ARRAY = $oElectrum_STATS->return_DF_destination_stats_array(
         *                                                  $oEndpoint_serial_SOURCE,
         *                                                  $oEndpoint_serial_DESTINATION,
         *                                                  $file_source_path);
         *
         * $tmp_stats_dest_path = $oElectrum_STATS->return_destination_stats_path(
         *                                          $oEndpoint_serial_SOURCE,
         *                                          $oEndpoint_serial_DESTINATION);
         *
         * self::$_R['kivotos']->R['usr']->error_log(
         *                                 'oWheel :: Run ' .
         *                                 'ftp_mksubdirs=>[ftp_root_dir_path=' .
         *                                 $ftp_root_dir_path .
         *                                 '][tmp_mksubdir_destination_path=' .
         *                                 $tmp_mksubdir_destination_path .
         *                                 ']',
         *                                 __LINE__,
         *                                 __METHOD__,
         *                                 __FILE__,
         *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
         *
         */

        if(\is_dir($file_source_path)){

            /* self::$_R['kivotos']->R['usr']->error_log(
             *                                'oWheel :: Run ' .
             *                                'ftp_mksubdirs=>[source_filepath=' .
             *                                $file_source_path.']',
             *                                __LINE__,
             *                                __METHOD__,
             *                                __FILE__,
             *                                'CRNRSTN_oELECTRUM_FILE_TRANSFER');
             *
             */
            error_log('[mthd ' . 
                __METHOD__ . '] [lnum ' . 
                __LINE__ . 
                '] Is a dir. crnrstn die().');
            die();

            /*$this->ftp_mksubdirs(
             *       $ftp_stream_target, 
             *       $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'], 
             *       $tmp_stats_DESTINATION_ARRAY['MKSUB_DIR']);
             *
             */

            $continue_process = true;

        }else{

            error_log('[mthd ' . 
                __METHOD__ . '] [lnum ' . 
                __LINE__ . 
                '] Not a dir. crnrstn die().');
            die();

            if(isset($SOURCE_filePath_ORIGINAL))
                $SOURCE_filepath_for_DESTINATION = $SOURCE_filePath_ORIGINAL;
            else
                $SOURCE_filepath_for_DESTINATION = $file_source_path;

            $tmp_slashChar = $this->return_slashChar($tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH']);

            $tmp_split_ARRAY = \explode(
                               $tmp_slashChar, 
                               $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH']);

            $tmp_split_cnt = \sizeof($tmp_split_ARRAY);

            $tmp_dir_split_ARRAY = \explode(
                                   $tmp_split_ARRAY[$tmp_split_cnt - 2], 
                                   $tmp_stats_DESTINATION_ARRAY['DESTINATION_FILEPATH']);

            $tmp_dir_sect_ARRAY = \explode(
                                  $tmp_slashChar, 
                                  $tmp_dir_split_ARRAY[1]);

            $tmp_sect_cnt = \sizeof($tmp_dir_sect_ARRAY);

            #$tmp_dir_sect_ARRAY[$tmp_sect_cnt-2] = wethrbug
            $tmp_dest_file_section_ARRAY = \explode(
                                           $tmp_dir_sect_ARRAY[$tmp_sect_cnt - 2], 
                                           $SOURCE_filepath_for_DESTINATION);

            //[tmp_dir_split_ARRAY[1]=/a_custom_folder_name/20201013_16-52-26/wethrbug/
            $tmp_sect_array = \explode(
                              $tmp_slashChar, 
                              $tmp_dir_split_ARRAY[1]);

            $tmp_cnt = \sizeof($tmp_sect_array);

            $tmp_cut_dir = $tmp_sect_array[$tmp_cnt - 2];

            $tmp_source_sect_ARRAY = \explode(
                                     $tmp_cut_dir, 
                                     $file_source_path);

            //$tmp_dir = dirname($tmp_source_sect_ARRAY[1]);

            $tmp_file_dest = \rtrim(
                             $tmp_dir_split_ARRAY[1], 
                             $tmp_slashChar) . 
                             $tmp_dest_file_section_ARRAY[1];

            $tmp_file_cap = \basename($tmp_file_dest);

            $tmp_file_dirpath_final = \rtrim(
                                      $tmp_file_dest, 
                                      $tmp_file_cap);

            $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'] = \rtrim(
                                                           $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'], 
                                                           $tmp_slashChar);

            /*$tmp_dfile = $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'] . 
             *             $SOURCE_filepath_for_DESTINATION;
             */

            $tmp_dfile = $tmp_stats_dest_path;
            $tmp_dfile = \rtrim($tmp_dfile, $tmp_slashChar);

            /* self::$_R['kivotos']->R['usr']->error_log(
             *                                 'oWheel :: SLASH CHAR = ' .
             *                                 $tmp_slashChar,
             *                                 __LINE__,
             *                                 __METHOD__,
             *                                 __FILE__,
             *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
             */

            $tmp_dfile_array = \explode(
                               $tmp_slashChar, 
                               $tmp_stats_DESTINATION_ARRAY['DESTINATION_FILEPATH']);
            $tmp_dfile_sect_cnt = \sizeof($tmp_dfile_array);

            /* self::$_R['kivotos']->R['usr']->error_log(
             *                                 'oWheel :: EXPLODE [' .
             *                                 $tmp_stats_DESTINATION_ARRAY['DESTINATION_FILEPATH'] . '] ON ' .
             *                                 $tmp_dfile_sect_cnt,
             *                                 __LINE__,
             *                                 __METHOD__,
             *                                 __FILE__,
             *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
             */

            $tmp_dfile_bi_path_ARRAY = \explode(
                                       $tmp_dfile_array[$tmp_dfile_sect_cnt - 2], 
                                       $SOURCE_filepath_for_DESTINATION);

            $tmp_dfile .= $tmp_dfile_bi_path_ARRAY[1];

            /* self::$_R['kivotos']->R['usr']->error_log(
             *                                 'oWheel :: Run ftp_mksubdirs=> [DESTINATION_FILEPATH]=' .
             *                                 $tmp_stats_DESTINATION_ARRAY['DESTINATION_FILEPATH'] .
             *                                 ' | [FTP_DIR_PATH]=' .
             *                                 $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'] .
             *                                 ' on tmp_split_ARRAY[tmp_split_cnt - 2]=' .
             *                                 $tmp_split_ARRAY[$tmp_split_cnt - 2],
             *                                 __LINE__,
             *                                 __METHOD__,
             *                                 __FILE__,
             *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
             *
             * self::$_R['kivotos']->R['usr']->error_log(
             *                                 'oWheel :: Run ftp_mksubdirs @ ' .
             *                                 $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'] .
             *                                 ' for =>[' .
             *                                 $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'] .
             *                                 $tmp_file_dirpath_final,
             *                                 __LINE__,
             *                                 __METHOD__,
             *                                 __FILE__,
             *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
             */

            if($this->ftp_mksubdirs(
                      $ftp_stream_target, 
                      $tmp_slashChar, 
                      $tmp_stats_DESTINATION_ARRAY['FTP_DIR_PATH'] . 
                      $tmp_file_dirpath_final) == true)
            {

                /* self::$_R['kivotos']->R['usr']->error_log(
                 *                                 'oWheel :: ftp_mksubdirs ' .
                 *                                 'SUCCESS',
                 *                                 __LINE__,
                 *                                 __METHOD__,
                 *                                 __FILE__,
                 *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
                 */

            }else{

                $error = \error_get_last();

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * We use FTP_CHDIR to see 
                 * if we need to call FTP_MKDIR. 
                 *
                 * It is ok (or expected) 
                 * to get FTP_CHDIR errors here. 
                 *
                 */
                $pos_ignore_err = \strpos($error['message'], 'ftp_chdir()');
                if($pos_ignore_err == false)
                    self::$_R['kivotos']->R['usr']->error_log('oWheel :: ftp_mksubdirs ' .
                                                    'ERROR :: ' .
                                                    $error['message'],
                                                    __LINE__,
                                                    __METHOD__,
                                                    __FILE__,
                                                    'CRNRSTN_oELECTRUM_FILE_TRANSFER');

            }

            if(\substr($tmp_dfile, -1) == $tmp_slashChar){

                $tmp_dfile = \rtrim($tmp_dfile, $tmp_slashChar) . $tmp_slashChar;
                $tmp_dfile_fname = \basename($SOURCE_filepath_for_DESTINATION);
                $tmp_dfile = $tmp_dfile . $tmp_dfile_fname;

            }

            /* self::$_R['kivotos']->R['usr']->error_log('oWheel :: SEE [' .
             *                                 $SOURCE_filepath_for_DESTINATION .
             *                                 ']. Now run ftp_put LOCAL FILE=>[' .
             *                                 $SOURCE_filepath_for_DESTINATION .
             *                                 '] to DEST FILE=>[' . $tmp_dfile .
             *                                 ']',
             *                                 __LINE__,
             *                                 __METHOD__,
             *                                 __FILE__,
             *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
             */

            if(\ftp_put(
                $ftp_stream_target,
                $tmp_dfile,
                $SOURCE_filepath_for_DESTINATION,
                FTP_BINARY))
            {

                $continue_process = true;

                /* self::$_R['kivotos']->R['usr']->error_log(
                 *                                 'oWheel FF - 2/2 ' .
                 *                                 '(or DF 1 of 1) :: Successfully ' .
                 *                                 'uploaded LOCAL FILE=>[' .
                 *                                 $SOURCE_filepath_for_DESTINATION .
                 *                                 '] to DEST FILE=>[' .
                 *                                 $tmp_dfile . ']',
                 *                                 __LINE__,
                 *                                 __METHOD__,
                 *                                 __FILE__,
                 *                                 'CRNRSTN_oELECTRUM_FILE_TRANSFER');
                 */

            }else{

                $error = \error_get_last();
                self::$_R['kivotos']->R['usr']->error_log('oWheel FF - 2/2 (or ' .
                                                'DF 1 of 1) :: ERROR uploading ' .
                                                'LOCAL FILE=>[' .
                                                $SOURCE_filepath_for_DESTINATION .
                                                '] to DEST FILE=>[' .
                                                $tmp_dfile . '] :: ' .
                                                $error['message'],
                                                __LINE__,
                                                __METHOD__,
                                                __FILE__,
                                                'CRNRSTN_oELECTRUM_FILE_TRANSFER');

                $this->is_error_on_transfer      = true;
                $this->error_on_transfer_message = $error['message'] . 
                                                   ' <= Error experienced ' . 
                                                   'while pushing local file [' . 
                                                   $SOURCE_filepath_for_DESTINATION . 
                                                   '] to FTP destination[' . 
                                                   '{FTP_OR_LOCAL_DETAIL}] as file=>[' . 
                                                   $tmp_dfile . '].';

            }

        }

        return $continue_process;

    }

