     */
    function append_url_param(
             $param_ARRAY, 
             $tunnel_encrypt = true, 
             $no_encrypt_param_ARRAY = NULL, 
             $include_no_encrypt = true)
    {

        /*error_log(__LINE__ . 
         *    ' user append_url_param=' . 
         *    print_r($param_ARRAY, true));
         *
         */

        if($this->is_ssl() == true){

            $tmp_lnk = 'https://' . 
                       $_SERVER['HTTP_HOST'] . 
                       $_SERVER['REQUEST_URI'];

        }else{

            $tmp_lnk = 'http://' . 
                       $_SERVER['HTTP_HOST'] . 
                       $_SERVER['REQUEST_URI'];

        }

        $tmp_lnk_explode_ARRAY = $this->explode_url($tmp_lnk);

        /* $tmp_lnk_explode_ARRAY['root']
         * $tmp_lnk_explode_ARRAY['param']
         *
         * echo $tmp_lnk_explode_ARRAY['param']['first'];  // value
         * echo $tmp_lnk_explode_ARRAY['param']['arr'][0]; // foo bar
         * echo $tmp_lnk_explode_ARRAY['param']['arr'][1]; // baz
         * 
         */

        $tmp_flag_param_ARRAY = array();
        $tmp_encrypted_params_pipe = '';
        $tmp_return_str = $tmp_lnk_explode_ARRAY['root'];

        $param_concatenator = '?';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * ADD ANY *NEW* 
         * URL PARAMS
         * 
         */
        foreach($param_ARRAY as $key => $value){

            /*if(!isset($tmp_flag_param_ARRAY[$this->return_param_name($value)]) && 
             *   ($key != 'crnrstn_encrypt_tunnel'))
             *{
             *
             */
            if($this->return_param_name($value) != 'crnrstn_encrypt_tunnel'){

                $tmp_flag_param_ARRAY[$this->return_param_name($value)] = 1;

                $tmp_return_str .= $param_concatenator . $this->url_param_append($value, $tunnel_encrypt);

                if($tunnel_encrypt == true){

                    $tmp_encrypted_params_pipe .= $key . '|';

                }

                if($param_concatenator == '?'){

                    $param_concatenator = '&';

                }

            }

        }

        if(isset($no_encrypt_param_ARRAY) && 
            $include_no_encrypt == true)
        {

            foreach($no_encrypt_param_ARRAY as $key => $value){

                /*if(!isset($tmp_flag_param_ARRAY[$this->return_param_name($value)]) && 
                 *   ($key != 'crnrstn_encrypt_tunnel'))
                 *{
                 *
                 */
                if($this->return_param_name($value) != 'crnrstn_encrypt_tunnel'){

                    $tmp_flag_param_ARRAY[$this->return_param_name($value)] = 1;

                    $tmp_return_str .= $param_concatenator . $this->url_param_append($value, false);

                    if($tunnel_encrypt == true){

                        $tmp_encrypted_params_pipe .= $key . '|';

                    }

                    if($param_concatenator == '?'){

                        $param_concatenator = '&';

                    }

                }

            }

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Keep all 
         * original 
         * URL params. 
         * 
         */
        foreach($tmp_lnk_explode_ARRAY['param'] as 
            $key00 => $value00)
        {

            if(!isset($tmp_flag_param_ARRAY[$key00]) && ($key00 != 'crnrstn_encrypt_tunnel')){

                if(isset($no_encrypt_param_ARRAY) && $include_no_encrypt == false){

                    $tmp_spoiled = false;

                    foreach($no_encrypt_param_ARRAY as 
                        $key01 => $value01)
                    {

                        if($key01 == $key00){

                            $tmp_spoiled = true;

                        }

                    }

                    if(!($tmp_spoiled == true)){

                        $tmp_flag_param_ARRAY[$key00] = 1;

                        $tmp_return_str .= $param_concatenator . 
                                           $this->url_param_append(
                                                  $key00 . '=' . $value00, 
                                                  $tunnel_encrypt);

                        if($tunnel_encrypt == true){

                            $tmp_encrypted_params_pipe .= $key00 . '|';

                        }

                        if($param_concatenator == '?'){

                            $param_concatenator = '&';

                        }

                    }

                }else{

                    $tmp_flag_param_ARRAY[$key00] = 1;

                    $tmp_return_str .= $param_concatenator . 
                                       $this->url_param_append(
                                              $key00 . '=' . $value00, 
                                              $tunnel_encrypt);

                    if($tunnel_encrypt == true){

                        $tmp_encrypted_params_pipe .= $key00 . '|';

                    }

                    if($param_concatenator == '?'){

                        $param_concatenator = '&';

                    }

                }

            }

        }

        if(isset($no_encrypt_param_ARRAY)){

            foreach($no_encrypt_param_ARRAY as 
                $key => $value00)
            {

                $tmp_flag_param_ARRAY[$this->return_param_name($value00)] = 1;

                $tmp_return_str .= $param_concatenator . 
                                   $this->url_param_append(
                                          $value00, 
                                          false);

            }

        }

        if($tunnel_encrypt == true){

            $tmp_return_str .= $param_concatenator . 
                               'crnrstn_encrypt_tunnel=' . 
                               urlencode($this->data_encrypt($tmp_encrypted_params_pipe));

        }

        return $tmp_return_str;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function url_param_append(
             $param_str, 
             $tunnel_encrypt)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Refactored 
         *       crnrstn->url_param_append() 
         *       method visibility from private 
         *       to public. 
         *       5 :: Monday, May 25, 2026 @ 0444 hrs.
         *       hits joint.
         *       sips coffee. 
         *
         */

        if($tunnel_encrypt == true){

            $tmp_str = '';
            $tmp_array = explode('=', $param_str);

            $tmp_str .= $tmp_array[0];
            $tmp_str .= '=';

            if(isset($tmp_array[1])){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Exclude crnrstn_m from 
                 * encryption for link 
                 * identification within 
                 * analytics. 
                 * 
                 */
                if($tmp_array[0] != 'crnrstn_m'){

                    $tmp_str .= urlencode($this->data_encrypt($tmp_array[1]));

                }else{

                    $tmp_str .= $tmp_array[1];

                }

            }else{

                $tmp_str .= $this->data_encrypt('');

            }

            return $tmp_str;

        }else{

            $tmp_str = '';
            $tmp_array = explode('=', $param_str);

            $tmp_str .= $tmp_array[0];
            $tmp_str .= '=';

            if(isset($tmp_array[1])){

                $tmp_str .= urlencode($tmp_array[1]);

            }

            return $tmp_str;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_param_name($param_str)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Refactored 
         *       crnrstn->return_param_name() 
         *       method visibility from private 
         *       to public. 
         *       5 :: Monday, May 25, 2026 @ 0446 hrs.
         *       hits joint.
         *       sips coffee. 
         *
         */

        $tmp_array = explode('=', $param_str);

        return $tmp_array[0];

    }

