    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function add_ssdtla_resource(
             $data_key, 
             $data_value, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $data_authorization_profile = NULL, 
             $index = NULL, 
             $ttl = NULL, 
             $spool_resource = false)
    {

        error_log(__LINE__ . 
            ' crnrstn ' . 
            __METHOD__ . 
            ' DO WE STILL RUN ' . 
            'THIS ARCHITECTURE? die();');

        die();
        $env_key = NULL;

        if(is_string($data_authorization_profile) || 
            !isset($data_authorization_profile))
        {

            switch($data_authorization_profile){
                case 'R_authorize & R_channel_RUNTIME':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Convert CLR-SSL channel 
                     * data to integer. 
                     *
                     *
                     * 5 :: Monday, July 13, 2026 @ 0225 hrs.
                     *
                     */
                    $data_authorization_profile = self::$R_data['int_flag']['R_authorize'] & 
                                                  self::$R_data['int_flag']['R_channel_RUNTIME'];

                break;

            }

        }

        switch($data_authorization_profile){
            //case CRNRSTN_AUTHORIZE_ALL:
            //case CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SESSION:
            //case CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SESSION & CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_RUNTIME:
            case self::$R_data['int_flag']['R_authorize_all']:
            case self::$R_data['int_flag']['R_authorize'] & 
                 self::$R_data['int_flag']['R_channel_SESSION']:
            case self::$R_data['int_flag']['R_authorize'] & 
                 self::$R_data['int_flag']['R_channel_SESSION'] & 
                 self::$R_data['int_flag']['R_authorize'] & 
                 self::$R_data['int_flag']['R_channel_RUNTIME']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Initialize TTL. 
                 *
                 */
                if(!isset($ttl)){

                    $ttl = $this->get_resource(
                                  'ssdtla_session_data_ttl', 
                                  0, 
                                  'CRNRSTN::RESOURCE::GENERAL_SETTINGS');

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Basic storage. 
                 *
                 */
                self::$_R['kivotos']->R['env']->add_ssdtla_resource(
                                                $data_key,
                                                $data_value,
                                                $data_type_family,
                                                $data_authorization_profile,
                                                $index,
                                                $ttl,
                                                $spool_resource);

            break;
            default:

                $this->env_key($env_key);

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * R_channel_RUNTIME
                 *
                 */
                $this->add_resource(
                       $data_key, 
                       $data_value, 
                       $data_type_family, 
                       $data_authorization_profile, 
                       $index, 
                       $ttl, 
                       $spool_resource, 
                       $env_key);

            break;

        }

    }

