    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE  :: https://www.php.net/manual/en/function.rtrim.php
     * COMMENT :: https://www.php.net/manual/en/function.rtrim.php#95802
     * AUTHOR  :: pinkgothic at gmail dot com
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function strrtrim(
             $message, 
             $strip)
    {
        // 5 :: Thursday, August 15, 2024 @ 0007 hrs.

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Break message 
         * apart by strip 
         * string. 
         *
         */
        $lines = explode($strip, $message);
        $last = '';

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Pop off empty 
         * strings at 
         * the end. 
         *
         */
        do{

            $last = array_pop($lines);

        }while(empty($last) && (count($lines)));

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Re-assemble what 
         * remains. 
         *
         */
        return \implode($strip, \array_merge($lines, array($last)));

    }

