    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function file_url_cache_id($file_path)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed the 
         *       crnrstn->resource_filecache_version 
         *       method to 
         *       file_url_cache_id($file_path), 
         *       and updated all CLR-SSL framework 
         *       resources accordingly (16 files in 
         *       total will have been reviewed by the 
         *       completion of this update). 
         *       5 :: Sunday, July 26, 2026 @ 0404 hrs.
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * SOURCE  :: https://www.php.net/manual/en/function.filesize.php
         * COMMENT :: https://www.php.net/manual/en/function.filesize.php#121370
         * AUTHOR  :: ivijan dot stefan at gmail dot com
         *
         * This function also can be great for browser 
         * caching controll. For example, you have a 
         * stylesheet and you want to make sure everyone 
         * has the most recent version. You could rename 
         * it every time you edit it, but that would be 
         * a waste of time. 
         *
         * Instead, you can do like: 
         *
         * echo '<link rel="stylesheet" href="style.css?ver=1.' . 
         *      filesize(dirname(__FILE__) . '/style.css') . '.' . 
         *      filemtime(dirname(__FILE__).'/style.css') . 
         *      '.0">';
         *
         * Sample output: 
         *
         *      <link rel="stylesheet" href="style.css?ver=1.8824.1499869132.0">
         *
         *      This also can be apply for JS and also images with same name.
         *
         */
        $file_cache_version_str = '420.' . 
                                  \filesize($file_path) . '.' . 
                                  \filemtime($file_path) . 
                                  '.0';

        return $file_cache_version_str;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function path_no_slash_dot($path)
    {

        $tmp_path_array = $this->str_split_unicode($path);
        $tmp_path_array_rev = array_reverse($tmp_path_array);

        if($tmp_path_array_rev[0] == '.' && 
            $tmp_path_array_rev[1] == '/')
        {

            return false;

        }else{

            return true;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    private function find_deepest_empty_dir(
                     $results, 
                     $is_dir_status_array, 
                     $results_pos, 
                     $tmp_dirPath_flag_ARRAY = NULL, 
                     $prev_result_pos = NULL, 
                     $prev_result_path = NULL)
    {

        $tmp_results_cnt = sizeof($results);
        for($search_pos = $results_pos; $search_pos < $tmp_results_cnt; $search_pos++){

            if($is_dir_status_array[$search_pos] == 1){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * We have a 
                 * directory result. 
                 *
                 */
                if($this->path_no_slash_dot($results[$search_pos]) == true){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Directory with 
                     * good format. 
                     *
                     */
                    if(!isset($prev_result_path)){

                        $prev_result_pos = $search_pos;
                        $prev_result_path = $results[$search_pos];
                        $current_result_path = $results[$search_pos];

                    }else{

                        $current_result_path = $results[$search_pos];
                        $pos = strpos($current_result_path, $prev_result_path);

                        if($pos !== false){

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Transition current 
                             * to previous. 
                             *
                             */
                            $prev_result_pos = $search_pos;
                            $prev_result_path = $current_result_path;

                        }else{

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Burn current path. 
                             *
                             */
                            if(!isset($tmp_dirPath_flag_ARRAY[$prev_result_path])){

                                /*error_log(__LINE__ . 
                                 *    ' crnrstn [' . 
                                 *    $search_pos . 
                                 *    '] Burn the DIR to disk as ->' . 
                                 *    $prev_result_path);
                                 *
                                 */

                                $tmp_deepest_empty_dir_ARRAY['burn_result_path'] = $prev_result_path;
                                $tmp_deepest_empty_dir_ARRAY['results_pos'] = $search_pos;

                                //$tmp_dirPath_flag_ARRAY[0] = $prev_result_path;
                                $tmp_deepest_empty_dir_ARRAY['flag_array'][0] = $prev_result_path;

                                return $tmp_deepest_empty_dir_ARRAY;

                            }else{

                                return NULL;

                            }

                        }

                    }

                }

            }else{

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * We have file. 
                 * skip directory. 
                 *
                 */

            }

        }

        return NULL;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE :: http://php.net/manual/en/class.recursivedirectoryiterator.php
     * COMMENT :: http://php.net/manual/en/class.recursivedirectoryiterator.php#85805
     * AUTHOR :: alvaro at demogracia dot com
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function scandir_system_integrations(
             $directory, 
             $endpoint_serial = NULL, 
             $return_files_only = false)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Try to be careful with 
         * this method. This is 
         * R&D kit built for a one-off. 
         *
         * Well, she is tied to 
         * config settings...there 
         * is potential...
         *
         * ...just maybe not here...
         *
         * TODO :: We are looking to 
         *         low-level splice 
         *         this R&D into 
         *         the CLR-SSL file 
         *         handling protocols. 
         *         This is now in 
         *         development; see 
         *         $this->scandir(), 
         *         $this->fwrite(), 
         *         et al. 
         *
         * There are no memory usage 
         * limits in place at the moment. 
         *
         * Sorry! Plz, give us a second 
         * to get this performance 
         * driven safety device hooked 
         * to the configuration 
         * settings of the CLR-SSL.
         *
         *
         * 5 :: Saturday, September 16, 2023 @ 0603 hrs.
         *
         */

        $results = array();
        $results_final_output = array();
        $results_filePath_output = array();
        $is_dir_status_array = array();
        $path = realpath($directory);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Since we are going to pay 
         * for the loops, might as well 
         * maximize ROI, and get some 
         * low hanging meta-data-fruit. 
         *
         */
        $tmp_results_total_filesize = 0;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Load active 
         * file attributes. 
         *
         */
        $tmp_active_file_attributes_ARRAY = $this->get_resource(
                                                   'system_file_active_attributes_profile', 
                                                   0, 
                                                   'CRNRSTN::RESOURCE::LOCAL_FILE_SYSTEM');

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Establish 
         * endpoint 
         * serialization. 
         *
         */
        if(!isset($endpoint_serial)){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Proper-relevant to the 
             * local file system...this 
             * exercise will be....even 
             * on top of the CRNRSTN :: 
             * Lightsaber RoCEv2 SOAP 
             * Services Layer (CLR-SSL) 
             * Real-Time Session Cast 
             * Services Layer (SSRT-SCSL). 
             *
             */
            $endpoint_serial = $this->hash($_SERVER['SERVER_ADDR']);

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Check for pre-existing 
         * file handling request. 
         *
         */
        if(!isset(self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']])){

            self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory]['DIR_PATH'] = $directory;
            self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory]['TYPE']     = \filetype($directory);

        }

        $tmp_stat = false;
        if($tmp_active_file_attributes_ARRAY['BLOCK_ALLOCATE'] == 1 ||
            $tmp_active_file_attributes_ARRAY['BLOCK_SIZE'] == 1 ||
            $tmp_active_file_attributes_ARRAY['DATE_LASTMODIFIED'] == 1 ||
            $tmp_active_file_attributes_ARRAY['DATE_LASTACCESSED'] == 1 ||
            $tmp_active_file_attributes_ARRAY['GID_STRING'] == 1 ||
            $tmp_active_file_attributes_ARRAY['GID_INT'] == 1 ||
            $tmp_active_file_attributes_ARRAY['UID_STRING'] == 1 ||
            $tmp_active_file_attributes_ARRAY['UID_INTEGER'] == 1)
        {

            $tmp_stat = true;

        }

/*
 *        $objects = new RecursiveIteratorIterator(
 *                       new RecursiveDirectoryIterator($path), 
 *                       RecursiveIteratorIterator::SELF_FIRST);
 *
 *        foreach($objects as $tmp_resource_path => $object){
 *
 *            $tmp_type = filetype($tmp_resource_path);
 *            error_log(__LINE__ . ' crnrstn $tmp_type[' . $tmp_type . '].');
 *            echo __LINE__ . ' crnrstn ' . $tmp_type . '<br>';
 *
 *        }
 *
 *        die();
 *
 */

        $objects = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path), RecursiveIteratorIterator::SELF_FIRST);
        foreach($objects as 
            $tmp_resource_path => $object)
        {

            /*if((strpos($tmp_resource_path, '/.') !== false) || 
             *   (strpos($tmp_resource_path, '/..') !== false))
             *{
             *
             */
            if((\strpos($tmp_resource_path, '/..') !== false)){

            }else{

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * filetype() 
                 *
                 * Returns the type of the 
                 * file. Possible values 
                 * are fifo, char, dir, 
                 * block, link, file, 
                 * socket and unknown. 
                 *
                 */
                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['TYPE'] = filetype($tmp_resource_path);

                switch(self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['TYPE']){
                    case 'dir':

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * If directory meta 
                         * is good to return. 
                         *
                         */
                        if(!($return_files_only !== false)){

                            if($tmp_active_file_attributes_ARRAY['FILESIZE'] == 1){

                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'] = 0;

                            }

                            $results[] = $tmp_resource_path;

                            /*error_log(__LINE__ . 
                             *    ' crnrstn RAW ->' . 
                             *    $tmp_resource_path);
                             *
                             */

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * If this is 
                             * a file. 
                             *
                             */
                            if(self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['TYPE'] == 'file'){

                                error_log(__LINE__ . 
                                    ' crnrstn FILE ->' . 
                                    $tmp_resource_path);

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * We have 
                                 * a file. 
                                 *
                                 */
                                if($this->path_no_slash_dot($tmp_resource_path) == true){

                                    $results_filePath_output[$tmp_resource_path] = 1;
                                    $results_final_output[$tmp_resource_path]    = 1;

                                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                     * To disable use of 
                                     * stat(), SEE system_file_active_attributes_profile
                                     * in: 
                                     * /_R/_config
                                     * /_config.defaults
                                     * /_crnrstn.system_settings.inc.php.
                                     *
                                     */
                                    if($tmp_stat == true)
                                        $tmp_filestat_ARRAY = \stat($tmp_resource_path);

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['UID_INTEGER'] == 1))
                                    
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['UID_INTEGER'] = $tmp_filestat_ARRAY['uid'];

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['GID_INT'] == 1))
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['GID_INT'] = $tmp_filestat_ARRAY['gid'];

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['DATE_LASTACCESSED'] == 1))
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DATE_LASTACCESSED'] = $tmp_filestat_ARRAY['atime'];

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['DATE_LASTMODIFIED'] == 1))
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DATE_LASTMODIFIED'] = $tmp_filestat_ARRAY['mtime'];

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['BLOCK_SIZE'] == 1))
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['BLOCK_SIZE'] = $tmp_filestat_ARRAY['blksize'];

                                    if($tmp_active_file_attributes_ARRAY['FILESIZE'] == 1)
                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * To disable use of 
                                         * Windows compatible. 
                                         *
                                         */
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'] = $this->find_filesize($tmp_resource_path);

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['UID_STRING'] == 1))
                                    {

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * To disable use of 
                                         * posix_getpwuid(), 
                                         * see, system_file_active_attributes_profile
                                         * in: 
                                         * /_R/_config
                                         * /_config.defaults
                                         * /_crnrstn.system_settings.inc.php.
                                         *
                                         */
                                        $tmp_array = \posix_getpwuid($tmp_filestat_ARRAY['uid']);
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['UID_STRING'] = $tmp_array['name'];

                                    }

                                    if(($tmp_stat == true) && 
                                        ($tmp_active_file_attributes_ARRAY['UID_STRING'] == 1))
                                    {

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * To disable use of 
                                         * posix_getgrgid(), 
                                         * see, system_file_active_attributes_profile
                                         * in: 
                                         * /_R/_config
                                         * /_config.defaults
                                         * /_crnrstn.system_settings.inc.php.
                                         *
                                         */
                                        $tmp_array = \posix_getgrgid($tmp_filestat_ARRAY['gid']);
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['GID_STRING'] = $tmp_array['name'];

                                    }

                                    if($tmp_active_file_attributes_ARRAY['PERMISSIONS_FULL'] == 1){

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * To disable use of 
                                         * fileperms(), 
                                         * see, system_file_active_attributes_profile
                                         * in: 
                                         * /_R/_config
                                         * /_config.defaults
                                         * /_crnrstn.system_settings.inc.php.
                                         *
                                         */
                                        $perms = \fileperms($tmp_resource_path);
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['PERMISSIONS_FULL'] = $this->return_full_permissions($perms);

                                    }

                                    if($tmp_active_file_attributes_ARRAY['PERMISSIONS_OCTAL'] == 1){

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * To disable use of 
                                         * fileperms(), 
                                         * see system_file_active_attributes_profile
                                         * in: 
                                         * /_R/_config
                                         * /_config.defaults
                                         * /_crnrstn.system_settings.inc.php.
                                         *
                                         */
                                        $perms = \fileperms($tmp_resource_path);

                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * SOURCE :: https://www.php.net/manual/en/function.fileperms.php
                                         * COMMENT :: https://www.php.net/manual/en/function.fileperms.php#113060
                                         * AUTHOR :: coolmic at example dot com
                                         *
                                         */
                                        self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['PERMISSIONS_OCTAL'] = decoct($perms & 0777);

                                    }

                                    if($tmp_active_file_attributes_ARRAY['TOTAL_FILESIZE'] == 1)
                                        $tmp_results_total_filesize += self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'];

                                }

                                $is_dir_status_array[] = 0;

                            }else{

                                /*error_log(__LINE__ . 
                                 *    ' crnrstn DIR ->' . 
                                 *    $tmp_resource_path);
                                 *
                                 */

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * We have 
                                 * a directory. 
                                 *
                                 */
                                $is_dir_status_array[] = 1;
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DIR_PATH'] = $directory;
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['TYPE'] = filetype($directory);

                            }

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Legacy code for 
                             * empty directories. 
                             *
                             */
                            $tmp_dirPath_flag_ARRAY    =
                            $tmp_dirPath_flagOut_ARRAY = array();

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Loop through result 
                             * set and add any 
                             * empty dir. 
                             *
                             */
                            $tmp_result_cnt  = \sizeof($results);
                            for($results_pos = 0; $results_pos < $tmp_result_cnt; $results_pos++){

                                $tmp_dir_selection = $this->find_deepest_empty_dir(
                                                            $results, 
                                                            $is_dir_status_array, 
                                                            $results_pos, 
                                                            $tmp_dirPath_flag_ARRAY);

                                if(isset($tmp_dir_selection))
                                    /*error_log(__LINE__ . 
                                     *    ' crnrstn WE LIKE DIR ->' . 
                                     *    $tmp_dir_selection['flag_array'][0]);
                                     *
                                     */
                                    $tmp_dirPath_flag_ARRAY[$tmp_dir_selection['flag_array'][0]] = 1;
                                    /*self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DIR_PATH'] = $directory;
                                     *self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['TYPE'] = filetype($directory);
                                     *
                                     */

                            }

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * For each directory path, 
                             * is there a file 
                             * containing it therein? 
                             *
                             */
                            foreach($results_filePath_output as 
                                $filePth => $fileKey)
                            {

                                foreach($tmp_dirPath_flag_ARRAY as 
                                    $dirPath => $dirKey)
                                {

                                    $pos = strpos($filePth, $dirPath);
                                    if($pos !== false && !isset($tmp_dirPath_flagOut_ARRAY[$dirPath]))
                                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                         * Disqualify this 
                                         * directory for file 
                                         * path match. 
                                         *
                                         *error_log(__LINE__ . 
                                         *    ' crnrstn is to disqualify ' . 
                                         *    'this directory->' . 
                                         *    $dirPath);
                                         *
                                         */

                                        $tmp_dirPath_flagOut_ARRAY[$dirPath] = 5;

                                }

                            }

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Append empty 
                             * directories 
                             * to array 
                             * of filepaths. 
                             *
                             */
                            foreach($tmp_dirPath_flag_ARRAY as 
                                $dirPath => $dirKey)
                            {

                                if(!isset($tmp_dirPath_flagOut_ARRAY[$dirPath]))
                                    /* error_log(__LINE__ . 
                                     *     ' crnrstn WE ' . 
                                     *     'BURN DIR ->' . 
                                     *     $dirPath);
                                     *
                                     */
                                    $results_final_output[$dirPath] = 1;

                                    /* self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DIR_PATH'] = $directory;
                                     * self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['TYPE'] = filetype($directory);
                                     *
                                     */

                            }

                        }

                        if($tmp_active_file_attributes_ARRAY['FILESIZE'] == 1)
                            self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'] = 0;

                    break;
                    case 'char':
                    case 'fifo':
                    case 'block':
                    case 'link':
                    case 'socket':
                    case 'unknown':
                    case 'file':
                    default:

                        if($tmp_active_file_attributes_ARRAY['FILESIZE'] == 1)
                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * Initialize filesize. 
                             *
                             */
                            self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'] = 0;

                        $results[] = $tmp_resource_path;

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * We have a file. 
                         *
                         */
                        if($this->path_no_slash_dot($tmp_resource_path) == true){

                            $results_filePath_output[$tmp_resource_path] = 1;
                            $results_final_output[$tmp_resource_path] = 1;

                            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                             * To disable use of stat(), 
                             * see system_file_active_attributes_profile
                             * in: 
                             * /_R/_config
                             * /_config.defaults
                             * /_crnrstn.system_settings.inc.php.
                             *
                             */
                            if($tmp_stat == true)
                                $tmp_filestat_ARRAY = \stat($tmp_resource_path);

                            if(($tmp_stat == true) && ($tmp_active_file_attributes_ARRAY['UID_INTEGER'] == 1))
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['UID_INTEGER'] = $tmp_filestat_ARRAY['uid'];

                            if(($tmp_stat == true) && ($tmp_active_file_attributes_ARRAY['GID_INT'] == 1))
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['GID_INT'] = $tmp_filestat_ARRAY['gid'];

                            if(($tmp_stat == true) && ($tmp_active_file_attributes_ARRAY['DATE_LASTACCESSED'] == 1))
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DATE_LASTACCESSED'] = $tmp_filestat_ARRAY['atime'];

                            if(($tmp_stat == true) && ($tmp_active_file_attributes_ARRAY['DATE_LASTMODIFIED'] == 1))
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['DATE_LASTMODIFIED'] = $tmp_filestat_ARRAY['mtime'];

                            if(($tmp_stat == true) && ($tmp_active_file_attributes_ARRAY['BLOCK_SIZE'] == 1))
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['BLOCK_SIZE'] = $tmp_filestat_ARRAY['blksize'];

                            if($tmp_active_file_attributes_ARRAY['FILESIZE'] == 1)
                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * Windows compatible. 
                                 *
                                 */
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'] = $this->find_filesize($tmp_resource_path);

                            if(($tmp_stat == true) && ($tmp_active_file_attributes_ARRAY['UID_STRING'] == 1)){

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * To disable use of posix_getpwuid(), 
                                 * see system_file_active_attributes_profile 
                                 * in: 
                                 * /_R/_config
                                 * /_config.defaults
                                 * /_crnrstn.system_settings.inc.php.
                                 *
                                 */
                                $tmp_array = \posix_getpwuid($tmp_filestat_ARRAY['uid']);
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['UID_STRING'] = $tmp_array['name'];

                            }

                            if(($tmp_stat == true) && 
                                ($tmp_active_file_attributes_ARRAY['UID_STRING'] == 1))
                            {

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * To disable use of posix_getgrgid(), 
                                 * see system_file_active_attributes_profile
                                 * in: 
                                 * /_R/_config
                                 * /_config.defaults
                                 * /_crnrstn.system_settings.inc.php.
                                 *
                                 */
                                $tmp_array = \posix_getgrgid($tmp_filestat_ARRAY['gid']);
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['GID_STRING'] = $tmp_array['name'];

                            }

                            if($tmp_active_file_attributes_ARRAY['PERMISSIONS_FULL'] == 1){

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * To disable use of fileperms(), 
                                 * see system_file_active_attributes_profile
                                 * in: 
                                 * /_R/_config
                                 * /_config.defaults
                                 * /_crnrstn.system_settings.inc.php.
                                 *
                                 */
                                $perms = \fileperms($tmp_resource_path);
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['PERMISSIONS_FULL'] = $this->return_full_permissions($perms);

                            }

                            if($tmp_active_file_attributes_ARRAY['PERMISSIONS_OCTAL'] == 1){

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * To disable use of fileperms(), 
                                 * see system_file_active_attributes_profile
                                 * in: 
                                 * /_R/_config
                                 * /_config.defaults
                                 * /_crnrstn.system_settings.inc.php.
                                 *
                                 */
                                $perms = \fileperms($tmp_resource_path);

                                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                                 * SOURCE :: https://www.php.net/manual/en/function.fileperms.php
                                 * COMMENT :: https://www.php.net/manual/en/function.fileperms.php#113060
                                 * AUTHOR :: coolmic at example dot com
                                 *
                                 */
                                self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['PERMISSIONS_OCTAL'] = decoct($perms & 0777);

                            }

                            if($tmp_active_file_attributes_ARRAY['TOTAL_FILESIZE'] == 1)
                                $tmp_results_total_filesize += self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial][$directory][$tmp_resource_path]['FILESIZE'];

                        }

                        $is_dir_status_array[] = 0;

                    break;

                }

            }

        }

        if($tmp_active_file_attributes_ARRAY['TOTAL_FILESIZE'] == 1)
            self::$system_integrations_directory_content_ARRAY[self::$R_data['R_request_id']][$endpoint_serial]['TOTAL_FILESIZE'][] = $tmp_results_total_filesize;

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE :: https://www.php.net/manual/en/function.fileperms.php
     *
     * Example #2 Display full permissions. 
     * PHP.net. 
     *
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function return_full_permissions($perms)
    {

        //$perms = fileperms('/etc/passwd');

        switch($perms & 0xF000){
            case 0xC000: // socket

                $info = 's';

            break;
            case 0xA000: // symbolic link

                $info = 'l';

            break;
            case 0x8000: // regular

                $info = 'r';

            break;
            case 0x6000: // block special

                $info = 'b';

            break;
            case 0x4000: // directory

                $info = 'd';

            break;
            case 0x2000: // character special

                $info = 'c';

            break;
            case 0x1000: // FIFO pipe

                $info = 'p';
            break;
            default: // unknown

                $info = 'u';

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Owner.
         *
         */
        $info .= (($perms & 0x0100) ? 'r' : '-');
        $info .= (($perms & 0x0080) ? 'w' : '-');
        $info .= (($perms & 0x0040) ?
            (($perms & 0x0800) ? 's' : 'x' ) :
            (($perms & 0x0800) ? 'S' : '-'));

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Group.
         *
         */
        $info .= (($perms & 0x0020) ? 'r' : '-');
        $info .= (($perms & 0x0010) ? 'w' : '-');
        $info .= (($perms & 0x0008) ?
            (($perms & 0x0400) ? 's' : 'x' ) :
            (($perms & 0x0400) ? 'S' : '-'));

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * World.
         *
         */
        $info .= (($perms & 0x0004) ? 'r' : '-');
        $info .= (($perms & 0x0002) ? 'w' : '-');
        $info .= (($perms & 0x0001) ?
            (($perms & 0x0200) ? 't' : 'x' ) :
            (($perms & 0x0200) ? 'T' : '-'));

        return $info;

    }

