    /**
     * R :: Returns a string with the output of var_dump.
     *
     * Taken from: 
     * /_R/class/thirdparty/nusoap
     * /class.nusoap_base.php [lnum 872]
     *
     * @param   mixed $data The variable to var_dump
     * @param   bool $string_output When True, the 
     *                              method returns 
     *                              the string output 
     *                              of var_dump. 
     * @return   NULL|string The output of var_dump 
     *                       is returned as string 
     *                       data if $string_output=true
     * @access public
     *
     */
    function var_dump(
             $data, 
             $string_output = true)
    {

        if($string_output){

            ob_start();
            var_dump($data);
            $ret_val = ob_get_contents();
            ob_end_clean();

            return $this->print_r_str_skinny(
                          $ret_val, 
                          NULL, 
                          NULL, 
                          NULL, 
                          NULL, 
                          NULL);

        }

        var_dump($data);

        return NULL;

    }

