    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function return_cache_data($channel = NULL)
    {

        if(isset($channel)){

            $cache_ARRAY = array();

            switch($channel){
                case 'R_channel_RUNTIME':

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Please see,
                     *  $oCRNRSTN->set_channel_config(
                     *             $channel_constant, 
                     *             $attribute_name, 
                     *             $data);
                     *
                     *  $oCRNRSTN->get_channel_config(
                     *             $channel, 
                     *             $index_0 = NULL, 
                     *             $index_1 = NULL, 
                     *             $index_2 = NULL, 
                     *             $index_3 = NULL);
                     *
                     *  $oCRNRSTN->isset_channel_config(
                     *             $channel_constant, 
                     *             $attribute_name, 
                     *             $return_type = CRNRSTN_BOOLEAN);
                     *
                     *  $oCRNRSTN->is_channel_active(
                     *             $channel_constant, 
                     *             $return_type = CRNRSTN_BOOLEAN);
                     *
                     */
                    if(self::$_R['kivotos']->R['rrs_map']->get_channel_config($channel, 'cache_is_active') == true){

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * Extract RRS 
                         * Map data. 
                         *
                         */
                        $cache_ARRAY = self::$_R['kivotos']->R['rrs_map']->return_cache_data($channel);

                    }else{

                        error_log(__LINE__ . 
                            ' crnrstn NO CACHE DATA ' . 
                            'AUTHORIZED TO RETURN FROM $channel[' . 
                            $channel . '] ' . 
                            $this->get_channel_config($channel, 'NAME') . 
                            '.');

                    }

                break;
                case 'R_channel_SESSION':
                    // SILENCE IS GOLDEN.
                case 'R_channel_COOKIE':
                case 'R_channel_DATABASE':
                case 'R_channel_SSDTLA':
                case 'R_channel_GET':
                case 'R_channel_POST':
                case 'R_channel_PSSDTLA':
                case 'R_channel_SOAP':
                case 'R_channel_FILE':
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Implementation pending.
                     *
                     * 
                     * 5 :: Tuesday, April 4, 2023 @ 2046 hrs.
                     *
                     */
                    error_log(__LINE__ . 
                        ' ' . 
                        __METHOD__ . 
                        ' (' . $channel . 
                        ') ' . 
                        $this->get_channel_config($channel, 'NAME') . 
                        ' CHANNEL IS LOOKING ' . 
                        'TO RETURN CACHE.');

                break;
                default:

                    error_log(__LINE__ . ' crnrstn UNKNOWN CHANNEL ' . 
                        'AUTHORIZATION INTEGER ' . 
                        'RECEIVED $channel[' . 
                        $channel . ']' . 
                        $this->get_channel_config($channel, 'NAME') . 
                        '.');

                break;

            }

            return $cache_ARRAY;

        }

        $cache_ARRAY       = array();
        $tmp_channel_ARRAY = self::$_R['kivotos']->R['rrs_map']->return_cache_channels();

        foreach($tmp_channel_ARRAY as 
            $index => $channel)
        {

            switch($channel){
                case self::$R_data['int_flag']['R_channel_SESSION']:
                    // SILENCE IS GOLDEN.
                break;
                case self::$R_data['int_flag']['R_channel_RUNTIME']:

                    /* if(self::$_R['kivotos']->R['rrs_map']->xxxxxxxxx($channel .
                     *        '_cache_is_active'))
                     * {
                     *
                     *
                     * Extract RRS 
                     * Map data. 
                     *
                     */
                    $cache_ARRAY = self::$_R['kivotos']->R['rrs_map']->return_cache_data($channel);

                break;
                case self::$R_data['int_flag']['R_channel_COOKIE']:
                case self::$R_data['int_flag']['R_channel_DATABASE']:
                case self::$R_data['int_flag']['R_channel_SSDTLA']:
                case self::$R_data['int_flag']['R_channel_GET']:
                case self::$R_data['int_flag']['R_channel_POST']:
                case self::$R_data['int_flag']['R_channel_PSSDTLA']:
                case self::$R_data['int_flag']['R_channel_SOAP']:
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Implementation pending. 
                     *
                     * Catch these with the 
                     * default case until we are 
                     * ready to process. 
                     *
                     *
                     * 5 :: Tuesday, April 4, 2023 @ 2046 hrs.
                     *
                     */
                default:

                    error_log(__LINE__ . 
                        ' crnrstn UNKNOWN CHANNEL ' . 
                        'AUTHORIZATION INTEGER ' . 
                        'RECEIVED $channel[(' . 
                        gettype($channel) . ') '. print_r($channel, true) . ']' . 
                        $this->get_channel_config($channel, 'NAME') . 
                        '.');

                break;

            }

        }

        return $cache_ARRAY;

    }

