     */
    function cache_storage_report($is_HTML = false)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * The Possibilities:
         *      $tmp_content_type = 'HTML'
         *      $tmp_content_type = 'TEXT'
         *
         * See, 
         * $this->tidy_boolean(
         *        $is_HTML, 
         *        CRNRSTN_STRING, 
         *        (int) self::$R_data['int_flag']['R_bool_is_html']);
         *
         * switch($tmp_content_type){
         *     case 'TEXT':
         *         //TEXT OUTPUT FORMAT.
         *
         *     break;
         *     default:
         *         //case 'HTML':
         *         //HTML OUTPUT FORMAT.
         *
         *     break;
         *
         * }
         *
         */

        $tmp_str_out = '';

        if(isset($_SESSION['CRNRSTN_' . self::$R_data['R_cluster_id']])){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * All session 
             * data. 
             *
             */
            $tmp_str_out .= 'START_SESSION::' . 
                            print_r($_SESSION['CRNRSTN_' . self::$R_data['R_cluster_id']], true);

        }else{

            $tmp_str_out .= 'START_SESSION::' . 
                            print_r($_SESSION, true);

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * All runtime data.
         *
         * $tmp_str_out .= 'START_RUNTIME::' . 
         *                 print_r(self::$_R['kivotos']->R['rrs_map']->cache_ARRAY, true);
         *
         */

        return $tmp_str_out;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function return_int_arithmetic_sign($value)
    {

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This method evaluates 
         * raw PHP native and 
         * XDEBUG method output. 
         * 
         * Do you even XDEBUG, bro? 
         *
         * Buyer beware of the 
         * incoming value. 
         *
         */
        if(is_bool($value) || 
            is_null($value) || 
            ($value == ''))
        {

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Oops! Fail quietly.
             *
             */
            return '';

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Is there a faster 
         * way to remove "+" 
         * for "zero"?
         * 
         * Since this is for 
         * CLR-SSL HTML and Text 
         * output reporting, we don't 
         * want to see a "+" 
         * symbol when the 
         * delta = 0.
         *
         */
        if($value == '0.00' || 
            $value == '0.0' || 
            $value == '0' || 
            $value == 0 || 
            $value == 0.0 || 
            $value == 0.00 )
        {

            return '';

        }

        if((double) $value > -1){

            return '+';

        }

        return '-';

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function mem_report_compile(
                     $mem_report_queue, 
                     $return_data_type, 
                     $php_logo_height, 
                     $to_plaid, 
                     $is_HTML, 
                     $report_delimiter_TEXT, 
                     $report_delimiter_HTML)
    {

        $tmp_data_out_ARRAY = array();
        $tmp_content_type   = $this->tidy_boolean(
                                     $is_HTML, 
                                     (int) self::$R_data['int_flag']['R_string'], 
                                     (int) self::$R_data['int_flag']['R_bool_is_html']);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Capture Server 
         * Performance Snapshots. 
         *
         * Note: memory_performance() 
         *       stores historical RAW 
         *       reporting telemetry in 
         *       order to support DELTA 
         *       comparisons from current. 
         *       
         *       This thing has a 'history' 
         *       reporting mode. 
         *
         * Note: memory_performance() supports  
         *       custom DELTA performance  
         *       reports using a previous  
         *       lookup_key as the historical  
         *       snapshot "delta_key."
         * 
         * 5 ::
         *
         */
        $tmp_mem_start_ARRAY                  = $this->memory_performance('CRNRSTN_MEMORY_REPORT', 'start');
        $tmp_mem_delta_zero_output_ARRAY      = $this->memory_performance('CRNRSTN_MEMORY_REPORT', 'delta');
        $tmp_mem_delta_construct_output_ARRAY = $this->memory_performance('CRNRSTN_MEMORY_REPORT', 'delta', 'CRNRSTN_CONSTRUCTOR');
        $tmp_mem_curr_output_ARRAY            = $this->memory_performance('CRNRSTN_MEMORY_REPORT');

        $tmp_cnt = \count($mem_report_queue);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * The Possibilities:
         *      $tmp_content_type = 'HTML'
         *      $tmp_content_type = 'TEXT'
         *
         * See, $oCRNRSTN->tidy_boolean(
         *                 $is_HTML, 
         *                 CRNRSTN_STRING, 
         *                 (int) self::$R_data['int_flag']['R_bool_is_html']);
         *
         */
        switch($tmp_content_type){
            case 'TEXT':

                $tmp_php_logo_html = '';
                $tmp_crnrstn_logo_html = '';
                $tmp_apache_logo_html = '';

            break;
            default:
                //case 'HTML':

                /*
                CRNRSTN_LOGO
                CRNRSTN_R_MD
                R_STONE_PILLAR
                APACHE_FEATHER
                APACHE_POWER_VERSION <-- All image rotation is broken, atm.

                */

                $tmp_php_logo_html = $this->return_system_image(
                                            'PHP_ELLIPSE', 
                                            '', 
                                            $php_logo_height, 
                                            NULL, 
                                            NULL, 
                                            NULL, 
                                            NULL, 
                                            self::$R_data['int_flag']['CRNRSTN_HTML']);
                $tmp_crnrstn_logo_html = $this->return_system_image(
                                                'CRNRSTN_LOGO', 
                                                '', 
                                                $php_logo_height, 
                                                NULL, 
                                                NULL, 
                                                NULL, 
                                                NULL, 
                                                self::$R_data['int_flag']['CRNRSTN_HTML']);
                $tmp_apache_logo_html = $this->return_system_image(
                                               'APACHE_POWER', 
                                               '', 
                                               $php_logo_height, 
                                               NULL, 
                                               NULL, 
                                               NULL, 
                                               NULL, 
                                               self::$R_data['int_flag']['CRNRSTN_HTML']);

            break;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Build Report. 
         *
         */
        foreach($mem_report_queue as 
            $index => $report_id)
        {

            switch($report_id){
                case 0:
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * SYSTEM/SCRIPT Combined 
                     * Current Report - Both 
                     * system and script 
                     * memory allocations. 
                     * Real-time metrics. 
                     *
                     */

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Example Report
                     *
                     * MEM USAGE: 2 MiB total. 
                     * 410.625 KiB by CRNRSTN ::
                     * 
                     */

                    $tmp_space = '';

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Current Performance 
                     * Data. 
                     *
                     */
                    $mem_PHP     = $this->return_bytes($tmp_mem_curr_output_ARRAY['memory_get_real_usage']);
                    $mem_CRNRSTN = $this->return_bytes($tmp_mem_curr_output_ARRAY['memory_get_script_usage']);

                    $mem_descript[self::$R_data['int_flag']['R_integer']] = 0;
                    $mem_descript[self::$R_data['int_flag']['R_string']]  = '0';
                    //$mem_descript['TITLE']['HTML']['MODULE_OPEN'] = '<!--' . $this->html_version_burn('HTML META MODULE', 'END') . '-->';
                    $mem_descript['TITLE']['HTML']       = 'SYSTEM/SCRIPT COMBINED CURRENT REPORT';
                    $mem_descript['TITLE']['TEXT']       = 'SYSTEM/SCRIPT COMBINED CURRENT REPORT';
                    $mem_descript['DESCRIPTION']['HTML'] = 'Both system and script memory allocations. Real-time metrics.';
                    $mem_descript['DESCRIPTION']['TEXT'] = 'Both system and script memory allocations. Real-time metrics.';

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Reporting Output 
                     * for CRNRSTN :: PLAID. 
                     *
                     * - Direct injection to session 
                     *   cache for real-time asset 
                     *   return performance reporting. 
                     *
                     *   This should be associated 
                     *   with admin auth session. 
                     *
                     *   Configuration settings
                     *   can be found at: 
                     *   /_R/_config/_config.defaults
                     *   /_crnrstn.system_settings.inc.php.
                     *
                     * - Direct exposure to CRNRSTN :: 
                     *   INTERACT UI via the 
                     *   CRNRSTN :: Lightsaber RoCEv2 
                     *   SOAP Services Layer (CLR-SSL) 
                     *   Data Tunnel Layer Architecture 
                     *   (SOAP, XML, JavaScript). 
                     *
                     */
                    if($to_plaid == true){

                        $tmp_data_out_ARRAY['report_id'][]   = $report_id;
                        $tmp_data_out_ARRAY['php'][]         = $mem_PHP;
                        $tmp_data_out_ARRAY['crnrstn'][]     = $mem_CRNRSTN;
                        $tmp_data_out_ARRAY['rtime'][]       = $this->wall_time();
                        $tmp_data_out_ARRAY['datecreated'][] = $this->return_micro_time();

                        break;

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Text Output 
                     * Format. 
                     *
                     */
                    if($is_HTML == false){

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * MEM USAGE: 2 MiB total. 
                         * 410.625 KiB by CRNRSTN ::
                         *
                         */
                        $tmp_data_out_ARRAY[] = $tmp_space . 
                                                'MEM USAGE: ' . 
                                                $mem_PHP . 
                                                ' total. ' . 
                                                $mem_CRNRSTN . 
                                                ' by CRNRSTN ::';

                        break;

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * HTML Output 
                     * Format. 
                     *
                     * MEM USAGE: 2 MiB <img> 
                     * 410.625 KiB <img> by CRNRSTN ::
                     *
                     */
                    $tmp_data_out_ARRAY[] = $tmp_space . 
                                            'MEM USAGE: ' . 
                                            $mem_PHP . ' ' . 
                                            $tmp_php_logo_html . 
                                            '&nbsp;&nbsp;' . 
                                            $mem_CRNRSTN . 
                                            '&nbsp;' . 
                                            $tmp_crnrstn_logo_html;

                break;
                case 1:
                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * COMPLETE CPU LOAD 
                     * REPORT - Current 
                     * System processor 
                     * load and with 
                     * averages taken 
                     * over 1, 5, and 
                     * 15 min.
                     *
                     */

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Example Report
                     *
                     * CPU LOAD: [0.1%, 0.1%, 0.1%] average 
                     * in the last [1, 5, 15min] respectively.
                     * 
                     */

                    $tmp_space = '';

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Current CPU Load.
                     *
                     */
                    $cpu_ARRAY = $tmp_mem_curr_output_ARRAY['sys_getloadavg'];

                    $mem_descript[self::$R_data['int_flag']['R_integer']] = 1;
                    $mem_descript[self::$R_data['int_flag']['R_string']]  = '1';
                    $mem_descript['TITLE']['HTML']       = 'COMPLETE CPU ' . 
                                                           'LOAD REPORT';
