                        $tmp_data_out_ARRAY['report_id'][]   = $report_id;
                        $tmp_data_out_ARRAY['php'][]         = $mem_PHP;
                        $tmp_data_out_ARRAY['crnrstn'][]     = $mem_CRNRSTN;
                        $tmp_data_out_ARRAY['rtime'][]       = $this->wall_time();
                        $tmp_data_out_ARRAY['datecreated'][] = $this->return_micro_time();

                        break;

                    }

                    if($is_HTML == false){
                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * MEM USAGE: 
                         * PHP [2 MiB]. 
                         * CRNRSTN :: [410.5625 KiB]. 
                         * XDEBUG_CRNRSTN [410.625 KiB].
                         * 
                         *$tmp_data_out_ARRAY[] = $tmp_space . 
                         *                        'MEM USAGE: PHP [' . 
                         *                        $this->return_bytes($mem_PHP, 5) . 
                         *                        ']. CRNRSTN :: [' . 
                         *                        $this->return_bytes($mem_CRNRSTN, 5) . 
                         *                        ']. XDEBUG_CRNRSTN [' . 
                         *                        $this->return_bytes(xdebug_memory_usage(), 5) . 
                         *                        '].';
                         *
                         */
                        $tmp_data_out_ARRAY[] = $tmp_space . 
                                                'MEM USAGE: PHP [' . 
                                                $this->return_bytes($mem_PHP, 5) . 
                                                ']. CRNRSTN :: [' . 
                                                $this->return_bytes($mem_CRNRSTN, 5) . 
                                                '].';

                        break;

                    }

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * HTML Output 
                     * Format.
                     *
                     * MEM USAGE: PHP [2 MiB]. 
                     * CRNRSTN :: [410.5625 KiB]. 
                     * XDEBUG_CRNRSTN [410.625 KiB]. 
                     *
                     *$tmp_data_out_ARRAY[] = $tmp_space . 
                     *                        'MEM USAGE: ' . 
                     *                        $this->return_bytes($mem_PHP, 5) . 
                     *                        ' ' . 
                     *                        $tmp_php_logo_html . 
                     *                        '&nbsp;&nbsp;' . 
                     *                        $this->return_bytes($mem_CRNRSTN, 5) . 
                     *                        ' ' . 
                     *                        $tmp_crnrstn_logo_html . 
                     *                        '&nbsp;&nbsp;' . 
                     *                        $this->return_bytes(xdebug_memory_usage(), 5) . 
                     *                        ' ' . 
                     *                        $tmp_crnrstn_logo_html . ' by XDEBUG';
                     *
                     */
                    $tmp_data_out_ARRAY[] = $tmp_space . 
                                            'MEM USAGE: ' . 
                                            $this->return_bytes($mem_PHP, 5) . 
                                            ' ' . 
                                            $tmp_php_logo_html . 
                                            '&nbsp;&nbsp;' . 
                                            $this->return_bytes($mem_CRNRSTN, 5) . 
                                            ' ' . 
                                            $tmp_crnrstn_logo_html;

                break;

            }

        }

        switch($this->data_type_filter($return_data_type)){
            case self::$R_data['int_flag']['R_string']:

                $tmp_str = '';
                foreach($tmp_data_out_ARRAY as 
                    $index_str => $report_str)
                {

                    if($is_HTML !== false){

                        $tmp_str .= $report_str . $report_delimiter_HTML;

                    }else{

                        $tmp_str .= $report_str . $report_delimiter_TEXT;

                    }

                }

                return $tmp_str;

            break;
            case self::$R_data['int_flag']['R_array']:
            default:

                return $tmp_data_out_ARRAY;

            break;

        }

    }

