    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function lightweight_page_return(
             $str, 
             $is_html_doc = true, 
             $content_prefix = '<pre><code>', 
             $content_append = '</code></pre>')
    {

        $tmp_str_out = '';

        if($is_html_doc !== false){

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Return content as 
             * a proper <HTML> 
             * document. 
             *
             */
            $tmp_str_out .= '<!DOCTYPE html>
<html lang="' . $this->iso_language_html() . '">
<head>
    <title>' . $this->get_crnrstn('CLR_SSL_long_TEXT') .
    ' v' . self::$R_data['version_crnrstn'] . '</title>
    '. $this->system_output_head_html(self::$R_data['int_flag']['CRNRSTN_CSS_MAIN_DESKTOP']) . '

</head>
<body>
';
            $tmp_str_out .= $content_prefix . $str . $content_append;

            $tmp_str_out .= '
</body>
</html>';

            return $tmp_str_out;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Return content as a 
         * simple tag wrapped 
         * string.
         *
         */
        $tmp_str_out .= $content_prefix . $str . $content_append;

        return $tmp_str_out;

    }

    /**
     * R :: Returns array of desired reports (string data). 
     *
     * E.g. "Memory Usage: TOTAL_SYS[2 MiB]. 
     * SCRIPT_SYS[410.5625 KiB]. 
     * XDEBUG[410.625 KiB]."
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function mem_report(
             $mem_report_queue, 
             $return_data_type = 'R_string', 
             $php_logo_height = 20, 
             $to_plaid = false, 
             $is_HTML = false, 
             $report_delimiter_TEXT = '. ', 
             $report_delimiter_HTML = '<br>')
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Where, $mem_report_queue = array(0, 3, 1);
         * Where, $mem_report_queue = 1;
         * Where, $return_data_type = CRNRSTN_STRING OR CRNRSTN_ARRAY
         *
         */

        if(\is_string($return_data_type)) 
            // 5 :: Tuesday, July 28, 2026 @ 2147 hrs.
            $return_data_type = self::$R_data['int_flag'][$return_data_type];

        if(!isset($php_logo_height))
            $php_logo_height = 20;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Process array of 
         * integer report 
         * types. 
         *
         */
        if(\is_array($mem_report_queue)){

            $tmp_report = $this->mem_report_compile(
                                 $mem_report_queue, 
                                 $return_data_type, 
                                 $php_logo_height, 
                                 $to_plaid, 
                                 $is_HTML, 
                                 $report_delimiter_TEXT, 
                                 $report_delimiter_HTML);

            return $tmp_report;

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Process integer 
         * report type. 
         *
         */
        if(\is_int($mem_report_queue)){

            $tmp_ARRAY = array();
            $tmp_ARRAY[] = $mem_report_queue;

            $tmp_report = $this->mem_report_compile(
                                 $tmp_ARRAY, 
                                 $return_data_type, 
                                 $php_logo_height, 
                                 $to_plaid, 
                                 $is_HTML, 
                                 $report_delimiter_TEXT, 
                                 $report_delimiter_HTML);

            return $tmp_report;

        }

        return '';

    }

