               \strtoupper(\gettype($data)) . 
               ']. LEN=[' . 
               \strlen(\strval($data)) . '].';

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function concat_log_string(
             &$log_string, 
             $new_activity_string = NULL, 
             $is_HTML = true, 
             $is_recursive = false)
    {

        if($is_HTML == true){

            if(($log_string != '') && 
                ($is_recursive == false))
            {

                if(is_array($new_activity_string))
                    foreach($new_activity_string as 
                        $index => $log)
                        $log_string .= '<br>' . $log;
                else
                    if($new_activity_string != '')
                        $log_string .= '<br>' . $new_activity_string;

            }else{

                if($is_recursive == true){

                    if($log_string == '')
                        $log_string .= $new_activity_string;
                    else
                        $log_string .= '<br>' . $new_activity_string;

                }else{

                    if(is_array($new_activity_string))
                        foreach($new_activity_string as 
                            $index => $log)
                            $this->concat_log_string(
                                   $log_string, 
                                   $log, 
                                   true, 
                                   true);
                    else
                        $log_string .= $new_activity_string;

                }

            }

        }

    }

