    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function initialization_series_add_header_attribute(
                     $name, 
                     $value, 
                     $overwrite_existing = true)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method,
         * initialization_series_add_header_attribute,
         * from the CRNRSTN :: HTTP Manager class
         * to crnrstn, and refactored it for 2026.
         *
         * 5 :: Case of the Monday's, August 3, 2026 @ 1114 hrs.
         *
         */
 
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Store header 
         * option data in 
         * server memory. 
         *
         */
        $attribute_id = $this->generate_key('http_response_header_attribute_id');

        self::$R_data['response_header']['attribute_id'][]                      = $attribute_id;
        self::$R_data['response_header']['name'][]                              = $name;
        self::$R_data['response_header']['isset'][\strtolower($name)]           = $attribute_id;

        self::$R_data['response_header'][$attribute_id]['name'][]               = $name;
        self::$R_data['response_header'][$attribute_id]['value'][]              = $value;

        if($overwrite_existing === true)
            self::$R_data['response_header'][$attribute_id]['overwrite_existing'][] = 1;
        else
            self::$R_data['response_header'][$attribute_id]['overwrite_existing'][] = 0;

    }

    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function initialization_series_header_options_apply()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method,
         * initialization_series_header_options_apply,
         * from the CRNRSTN :: HTTP Manager class
         * to crnrstn, and refactored it for 2026.
         * 
         * 5 :: Case of the Monday's, August 3, 2026 @ 1128 hrs.
         *
         */

        $http_header_options_count = \sizeof(self::$R_data['response_header']['attribute_id']);

        for($i = 0; $i < $http_header_options_count; $i++){

            if((int) self::$R_data['response_header'][self::$R_data['response_header']['attribute_id'][$i]]['overwrite_existing'][0] == 1)
                \header(self::$R_data['response_header'][self::$R_data['response_header']['attribute_id'][$i]]['name'][0] . 
                        ': ' . 
                        self::$R_data['response_header'][self::$R_data['response_header']['attribute_id'][$i]]['value'][0]);
            else
                \header(self::$R_data['response_header'][self::$R_data['response_header']['attribute_id'][$i]]['name'][0] . 
                        ': ' . 
                        self::$R_data['response_header'][self::$R_data['response_header']['attribute_id'][$i]]['value'][0], false);
        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function initialization_series_get_headers($return_type = 'R_array')
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method,
         * initialization_series_get_headers,
         * from the CRNRSTN ::
         * HTTP Manager public function 
         * get_headers($returnType = 'R_array'){}
         * to crnrstn.
         * 
         * 
         * 5 :: Case of the Monday's, August 3, 2026 @ 1135 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * TODO :: Use the CLR-SSL framework 
         *         delimiting character to delimit 
         *         response header name/value options. 
         *         5 :: Tuesday, August 4, 2026 @ 0143 hrs.
         *
         */
        if(\is_string($return_type)) 
            // 5 :: Tuesday, July 21, 2026 @ 0702 hrs.
            $return_type = self::$R_data['int_flag'][$return_type];

        switch($return_type){
            case self::$R_data['int_flag']['R_array']:

                return \getallheaders();

            break;
            case self::$R_data['int_flag']['R_string']:
            default:

                $str          = '';
                $http_headers = \getallheaders();

                foreach($http_headers as 
                    $attrib_nom => $value)
                    $str .= $attrib_nom . '=' . 
                            $value . ',';

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Strip trailing comma. 
                 *
                 */
                $str = \rtrim($str, ',');
        
                return $str;

            break;

        }

    }

