                    // Is the data concatenated?
                    $pos_comma = \strpos($resource_name, ',');
                    $pos_pipe  = \strpos($resource_name, '|');

                    if($pos_comma !== false)
                        $delimiter = ',';
                    else
                        if($pos_pipe !== false)
                            $delimiter = '|';

                    if(isset($delimiter)){

                        $res_names = \explode($delimiter, $resource_name);
                        $cnt       = \sizeof($res_names);

                        for($i = 0; $i < $cnt; $i++)
                        {

                            if(!($R_resp = _crnrstn_native_resource_registry(
                                           'evaluate',
                                           $this,
                                           NULL,
                                           $res_names[$i],
                                           self::$R_data['R_debug_mode'])))
                            {

                                $clr_ssl_msg = 'CLR-SSL resource ' .
                                               'evaluation failure: ' .
                                               $res_names[$i];
                                // 5 :: Sunxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
                                $msg_token = 'a5ae9de61711d0b7f00f639bfcc45405' .
                                             'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
                                $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
                                $token = array(
                                         'token'                   => $msg_token,
                                         'token_generation_date'   => $token_generation_date,
                                         'request_type'            => __METHOD__,
                                         'code'                    => 200,
                                         'clr_ssl_msg'             => $clr_ssl_msg);
                                $this->error_log(
                                       $clr_ssl_msg,
                                       \LOG_ALERT,
                                       \E_ERROR,
                                       __LINE__,
                                       __METHOD__,
                                       __FILE__,
                                       $token);

                            }else{

                                $R_resp[] = $R_resp;

                            }

                        }

                        return NULL;

                    }

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Requesting one (1)
                 * resource from the CLR-SSL
                 * Resource Registry.
                 *
                 */
                if(!($R_resp = _crnrstn_native_resource_registry(
                               'evaluate',
                               $this,
                               NULL,
                               $resource_name,
                               self::$R_data['R_debug_mode'])))
                {

                    $clr_ssl_msg = 'CLR-SSL resource ' .
                                   'evaluation failure: ' .
                                   $resource_name;
                    // 5 :: Sunxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
                    $msg_token = 'a5ae9de61711d0b7f00f639bfcc45405' .
                                 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token = array(
                             'token'                   => $msg_token,
                             'token_generation_date'   => $token_generation_date,
                             'request_type'            => __METHOD__,
                             'code'                    => 200,
                             'clr_ssl_msg'             => $clr_ssl_msg);
                    $this->error_log(
                           $clr_ssl_msg,
                           \LOG_ALERT,
                           \E_ERROR,
                           __LINE__,
                           __METHOD__,
                           __FILE__,
                           $token);

                }

            break;
            case self::$R_data['int_flag']['R_array']:
                // 5 :: Thursday, August 20, 2026 @ 0657 hrs.

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Array Structure A: array('resource_name0', 'resource_name1', ...)
                 * Array Structure B: array('resource_name0' => 'val', 'resource_name1' => 'val', ...)
                 *
                 */

                $i = 0;
                foreach($resource_name as
                        $index => $val)
                {

                    // Array Structure A
                    if(\is_int($index))
                        $res_name = $val;
                    else
                        // Array Structure B
                        $res_name = $index;

                    if(!($R_resp = _crnrstn_native_resource_registry(
                                   'evaluate',
                                   $this,
                                   NULL,
                                   $res_name,
                                   self::$R_data['R_debug_mode'])))
                    {

                        $clr_ssl_msg = 'CLR-SSL resource ' .
                                       'evaluation failure: ' .
                                       $res_name;
                        // 5 :: Sunxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
                        $msg_token = 'a5ae9de61711d0b7f00f639bfcc45405' .
                                     'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token = array(
                                 'token'                   => $msg_token,
                                 'token_generation_date'   => $token_generation_date,
                                 'request_type'            => __METHOD__,
                                 'code'                    => 200,
                                 'clr_ssl_msg'             => $clr_ssl_msg);
                        $this->error_log(
                               $clr_ssl_msg,
                               \LOG_ALERT,
                               \E_ERROR,
                               __LINE__,
                               __METHOD__,
                               __FILE__,
                               $token);

                    }else{

                        $R_resp[] = $R_resp;

                    }

                }

                return NULL;

            break;

        }

        return NULL;

